var e={"tool.look":`Ansehen`,"tool.build":`Bauen`,"tool.remove":`Abreißen`,"action.rotate":`Drehen`,"action.undo":`Rückgängig`,"action.redo":`Wiederholen`,"action.inventory":`Inventar`,"action.alt":`Details`,"action.close":`Schließen`,"action.save":`Speichern`,"key.hint":`{key}`,"status.0":`Wartet`,"status.1":`Arbeitet`,"status.2":`Keine Zufuhr`,"status.3":`Ausgang voll`,"status.4":`Kein Gürtel in Reichweite`,"status.5":`Kein Rezept`,"status.6":`Kein Ziel`,"status.2.hint":`Zutaten per Greifer zuführen oder von Hand einlegen.`,"status.3.hint":`Erzeugnis per Greifer oder mit der Schaltfläche „Nehmen“ entnehmen. Flüssigkeit – Rohre oder einen Tank verlegen.`,"status.4.hint":`Der Förderer erreicht keinen Gürtel – setzen Sie ihn näher ans Gesteinsband: Die Vorschau in der Hand färbt sich rot, wenn kein Gürtel erreichbar ist.`,"status.5.hint":`Wählen Sie unten ein Rezept.`,"status.6.hint":`Ein Greifer braucht vorn und hinten eine Maschine oder ein Gravoband.`,"machine.recipe":`Rezept`,"machine.input":`Eingang`,"machine.output":`Ausgang`,"machine.contents":`Inhalt`,"machine.empty":`Leer`,"machine.held":`In der Hand`,"machine.take":`Nehmen`,"machine.put":`{item} einlegen`,"machine.remove":`Abreißen`,"machine.time":`{s} s`,"inv.title":`Inventar`,"inv.craft":`Handfertigung`,"inv.queue":`Warteschlange`,"inv.missing":`Fehlt`,"inv.craftOne":`×1`,"inv.craftFive":`×5`,"inv.cancel":`Abbrechen`,"inv.empty":`Leer`,"goal.title":`Ziel`,"goal.skip":`Ziel einklappen`,"goal.ask.go":`Zeigen`,"goal.show":`Ziele zeigen`,"goal.done":`Alle Ziele erreicht! Was jetzt kommt, ist Ihre eigene Fabrik um einen lebenden Stern.`,"goal.mine":`{n} Quarz von Hand abbauen`,"goal.mine.hint":`{touch, select, yes {Tippen Sie auf einen blauen Brocken des Gürtels an der Markierung – der Strahl des Kutters baut dann selbst Quarz ab; erneutes Antippen desselben Brockens stoppt ihn.} other {Klicken Sie auf einen blauen Brocken des Gürtels an der Markierung – der Strahl des Kutters baut dann selbst Quarz ab; ein zweiter Klick auf denselben Brocken stoppt ihn.}}`,"goal.grinder":`Eine Schleiferei neben den Strahlempfänger setzen`,"goal.grinder.hint":`Bauleiste → Schleiferei → ein Platz neben dem Strahlempfänger. Dann „Ansehen“, die Schleiferei {touch, select, yes {antippen} other {anklicken}} und „Linse“ wählen.`,"goal.grabber":`Die Linie mit Greifern verbinden: die erste Linse`,"goal.grabber.hint":`Ein Greifer nimmt von hinten und legt nach vorn ab, in Pfeilrichtung. Erster: Gravoband → Schleiferei. Zweiter: Schleiferei → Lager (Kiste).`,"goal.lenses":`Auf {n, plural, one {# Linse} other {# Linsen}} aus der Linie warten`,"goal.lenses.hint":`Nichts zu tun: Die Linie liefert alle {sec} s eine Linse. Steht sie still – die Maschine mit dem Symbol {touch, select, yes {antippen} other {anklicken}}, ihr Fenster sagt, was fehlt.`,"goal.obsidian":`Eine Harpune an die orangen Brocken, dann {n, plural, one {# Platte} other {# Platten}} aus der Linie`,"goal.obsidian.hint":`Die dritte Harpune kommt in den Rahmen zwischen Gürtel und Plattenschleiferei, Ausgang (der helle Punkt) direkt in sie: Sie beschickt die Schleiferei selbst, ohne Gravoband. Sobald sie einen Brocken fängt, erlischt der Rahmen, und die Linie fertigt Platten von selbst: auf {n} warten. Licht: ein weiterer Bogen und ein Lichtleiter.`,"goal.expand":`Eine zweite Schleiferei – für Platten, an den orangen Brocken`,"goal.expand.hint":`Eine Schleiferei im „Inventar“ fertigen ({plates} Platten, {quartz} Quarz) und in den Rahmen am orangen Gürtel setzen – auf der Seite der Basis. Rezept: „Obsidianplatte“. Die Harpune kommt zwischen sie und den Gürtel: Gravobänder können keinen Gürtel kreuzen.`,"goal.progress":`{have} / {need}`,"toast.saved":`Gespeichert`,"toast.loaded":`Welt geladen`,"toast.noItem":`„{item}“ fehlt im Inventar – dort herstellen`,"toast.newWorld":`Neue Welt`,"hud.mining":`Abbau`,"hud.debug":`FPS {fps} · UPS {ups} · Tick {tick} · Maschinen {entities} · Hash {hash}`,"hotbar.label":`Bauten`,"a11y.game":`Spielfeld von Starwarden`,"machine.rate":`Verbraucht {rate} {item}/s`,"machine.drills":`≈ {n} Harpune(n) am Eingang`,"action.pause":`Pause`,"action.resume":`Weiter`,"hud.paused":`Pausiert`,"toast.recipeCopied":`Rezept kopiert – Shift+Klick auf einen Montierer fügt es ein`,"goal.light":`Licht vom Empfänger zur Schleiferei bringen`,"goal.light.hint":`Einen Lichtleiter von der Empfängerschüssel bis an eine Seite der Schleiferei ziehen – oder die Schleiferei direkt an den Empfänger setzen: Das Licht fließt auch ohne Lichtleiter. Leuchtet sie – das Licht ist da. Ein Bogen I liefert {arc} ph/s (Photonen pro Sekunde) – genau eine Schleiferei.`,"goal.collectors":`Licht für die Basis: {n} ph/s ({arcs, plural, one {# Bogen} other {# Bögen}})`,"goal.collectors.hint":`„Bogen I“ im „Inventar“ fertigen und auf den Ring beim Stern werfen. Jeder Bogen liefert {arc} ph/s; ein Empfänger nimmt bis {cap}.`,"goal.mix":`Bernstein mischen`,"goal.mix.hint":`Mischer: verschiedene Farben in die Seiteneingänge → Bernstein nach vorn. Gleiches Licht von beiden Seiten verbrennt. Farben nicht in einem Lichtleiter vereinen – sie interferieren.`,"goal.focus":`Resonatoren herstellen`,"goal.focus.hint":`Ein Resonator braucht weißes Licht der Helligkeit {b}: Ein Fokussierer erhöht die Helligkeit um 1. Ein langer Lichtleiter wird alle {fade} Felder schwächer.`,"machine.light":`Licht: {amount} ph {color}, Helligkeit ≥ {b}`,"machine.flux":`Fluss: {n} ph/s`,"machine.lightBuf":`Im Puffer: {n} ph`,"color.1":`Scharlach`,"color.2":`Smaragd`,"color.4":`Azur`,"color.3":`Bernstein`,"color.6":`Cyan`,"color.5":`Magenta`,"color.7":`Weiß`,"status.7":`Kein Licht`,"status.8":`Schwaches Licht`,"status.9":`Störung`,"status.10":`Falsche Farbe`,"status.7.hint":`Einen Lichtleiter vom Empfänger heranführen oder die Maschine direkt an seinen Ausgang setzen. Licht wird portionsweise pro Zyklus gesammelt.`,"status.8.hint":`Nicht hell genug: Netze länger als {fade} Felder werden schwächer – verkürzen oder einen Fokussierer einbauen.`,"status.9.hint":`Eine Farbe – ein Netz: Lichtleiter, die sich berühren, verschmelzen. Netze verschiedener Farben durch ein leeres Feld trennen; ein Lichtleiter in der Hand zeigt, womit er sich verbindet.`,"status.10.hint":`Das Rezept braucht eine andere Farbe – den passenden Ausgang von Prisma oder Mischer anschließen.`,"goal.beam":`Licht als Strahl senden`,"goal.beam.hint":`Ein Port an einem Lichtleiter macht Licht zum Strahl, ein Spiegel lenkt ihn um, ein gegenüberliegender Port empfängt ihn. Ein Port ohne Gegenstück verschwendet Licht.`,"goal.plates":`Eine weitere Harpune für die Plattenlinie: {n, plural, one {# Platte} other {# Platten}}`,"goal.plates.hint":`Eine Harpune kostet {lenses} Linsen und {plates} Platten: Die Linsen liegen in der Kiste der Linie – „Nehmen“ in ihrem Fenster. Eine Harpune im „Inventar“ fertigen und in den Rahmen neben der Plattenschleiferei setzen, Ausgang in sie. Steht sie, erlischt der Rahmen, und die Linie läuft mit voller Kraft: auf {n} Platten warten. Die Schleiferei braucht {light} ph/s Licht: zu wenig – einen weiteren Bogen werfen.`,"action.sound":`Ton`,"action.soundOn":`Ton an`,"action.soundOff":`Ton aus`,"stats.title":`Statistik`,"stats.min1":`1 Min.`,"stats.min10":`10 Min.`,"stats.perMin":`{n}/Min.`,"stats.empty":`Noch nichts produziert.`,"goal.completed":`Ziel erreicht`,"goal.mine.why":`Das Modul der „Schwalbe“ ist zerstört, die Schläfer hängen an Notpaneelen. Retten kann sie nur eine Fabrik – und die beginnt mit Quarz: Aus ihm werden Linsen geschliffen.`,"goal.grinder.why":`Das Archiv der „Aussaat“ enthält Baupläne aller Maschinen der Kolonie, doch ohne Linsen lässt sich keine bauen. Die Schleiferei schleift sie aus Quarz.`,"goal.light.why":`Das Licht des Bogens ist erst der Anfang: Es muss zu den Maschinen gelangen. Ein Lichtleiter ist die erste Ader der künftigen Kolonie.`,"goal.grabber.why":`Eine Fabrik, die auf die Hände des Wardens wartet, rettet die Schläfer nicht. Greifer reichen Gegenstände von Maschine zu Maschine – die Linie läuft von selbst.`,"goal.lenses.why":`Bögen, das Zentrum und fast jede Maschine des Archivs brauchen Linsen. Ein Linsenvorrat ist Zeit, die Sie für die Schläfer gewinnen.`,"goal.expand.why":`Um das Modul zu flicken und Maschinen zu bauen, braucht es Gehäuse – Platten. Sie entstehen aus den orangen Brocken, dem Obsidian.`,"goal.obsidian.why":`Platten von Hand dauern zu lange, und das Modul der „Schwalbe“ braucht Flicken. Die Linie fertigt sie von selbst.`,"goal.plates.why":`Platten stecken in allem – in Maschinen, in Flicken für das Modul, im künftigen Tor. Volles Licht auf der Linie – volle Geschwindigkeit.`,"goal.collectors.why":`Vierzig Kapseln, das Archiv, das Zentrum – alles lebt von Licht. Jeder Bogen ist ein Stück der künftigen Sphäre um die Wiege.`,"goal.mix.why":`Nach dem Angriff ist klar: Die Basis braucht Verteidigung. Bernstein ist die Ladung des Speers: {n} in jedem Speer. Ein Prisma liefert diese Farbe nicht – wir mischen sie selbst.`,"goal.focus.why":`Ein Resonator hält das Licht stetig. Daraus werden der Speer und neuere Maschinen gebaut – und stetiges Licht blendet den Schwarm weniger.`,"goal.beam.why":`Die Kolonie braucht Licht jenseits der Gürtel – dort liegen neue Brocken und Platz für Maschinen. Ein Strahl trägt Licht weit, ohne schwächer zu werden, und fliegt über Gürtel hinweg.`,"goal.spectrum_m.why":`Ein Spektrum ist eine Probe des Lichts einer Sternklasse. Das Archiv schaltet Baupläne nach gelesenen Klassen frei: Die erste, M, öffnet die Resonanz.`,"goal.spectrum_m.hint":`Montierer: das Rezept „Spektrum M“ – eine Rubinlinse, eine Platte und rotes Licht. Die Spektren per Gravoband und Greifer oder von Hand zum Zentrum bringen.`,"goal.spectrum_m":`{n, plural, one {# Spektrum} other {# Spektren}} M ans Zentrum liefern`,"goal.resonance.why":`Resonanz macht Förderer doppelt so schnell: Die Fabrik wächst schneller – und das Licht erreicht die Schläfer früher.`,"goal.resonance.hint":`„Resonanz“ erforschen. Ein Segel an einem Lichtleiter beschleunigt Förderer in der Nähe; Pylonen tragen den Schub weiter (bis {link} Felder). Harpunen müssen in einer Zone von {zone}×{zone} liegen.`,"goal.resonance":`Resonanz erforschen und {n, plural, one {# Harpune} other {# Harpunen}} beschleunigen`,"goal.spectrum_k.why":`Die zweite Sternklasse ist K, orange. Jede gelesene Klasse schaltet im Archiv neue Baupläne frei – und bringt das Tor näher.`,"goal.spectrum_k.hint":`„Spektroskopie“ erforschen und einen zweiten Montierer aufstellen. K: eine Bernsteinlinse, ein Greifer und das Bernsteinlicht des Mischers (Rot + Smaragd). Hält ein Greifer mit dem Montierer nicht mit, durch einen Schnellgreifer ersetzen („Logistik“). Nichts von Hand tragen: ein Greifer von der Werkbank in eine Kiste, ein Gravoband von der Kiste zum Montierer; die Greiferkiste daneben mit „Alles einlegen“ auffüllen.`,"goal.spectrum_k":`{n, plural, one {# Spektrum} other {# Spektren}} K ans Zentrum liefern`,"goal.liquid.why":`Verdichtetes Licht ist der nächste Schritt zur Klasse G – der Klasse der Wiege selbst. Ohne flüssiges Licht lässt sich ihr Spektrum nicht lesen.`,"goal.liquid.hint":`„Flüssiges Licht“ erforschen. Eis kommt von Meteoriten: {touch, select, yes {Tippen Sie auf einen Meteoriten} other {Klicken Sie auf einen Meteoriten}} und sammeln Sie die Splitter im Vorbeiflug ein. Einen Kondensator an das Azurlicht eines Prismas setzen und mit Eis befüllen. Die Flüssigkeit muss irgendwohin fließen: Ein Rohr fasst {cap} Einh. – {pipes} Rohre vom Kondensator verlegen (später ein Tank oder ein Montierer für Spektrum G).`,"goal.liquid":`{n} Einh. flüssiges Licht erzeugen`,"goal.spectrum_g.why":`Klasse G – wie die Wiege selbst. Drei gelesene Klassen, und das Zentrum kann ihr Licht bis in die schwächsten Linien zerlegen.`,"goal.spectrum_g.hint":`„Klasse G“ erforschen. Rezept: ein Resonator, flüssiges Licht und Bernstein der Helligkeit {b} (nach einem Fokussierer).`,"goal.spectrum_g":`{n, plural, one {# Spektrum} other {# Spektren}} G ans Zentrum liefern`,"goal.mine.done":`Quarz im Laderaum. Der erste Stein einer Kolonie, die nie im Plan stand. Zeitpunkt protokolliert.`,"goal.grinder.done":`Eine Schleiferei! An so einer habe ich in der Ausbildung meine Prüfung gemacht. Rezept „Linse“ wählen, dann Licht und Gestein geben.`,"goal.light.done":`Sie leuchtet! Wenn das Licht bis zur Schleiferei kommt, kommt es auch zu den Schläfern. Nicht gleich, aber es kommt.`,"goal.grabber.done":`Erste Linse von der Linie. Die Fabrik lebt: Sie arbeitet, selbst wenn Sie woanders hinschauen.`,"goal.lenses.done":`{n, plural, one {# Linse} other {# Linsen}} – die Linie arbeitet ohne Sie.`,"goal.expand.done":`Eine zweite Schleiferei, für Platten – damit flicken wir das Modul. Jetzt eine Harpune daneben, Ausgang direkt in sie.`,"goal.obsidian.done":`Die Platten kommen. Jetzt gibt es etwas, um das Modul zu flicken – und um darauf eine Kolonie wachsen zu lassen.`,"goal.plates.done":`Das nenne ich Tempo! Mit so einer Linie holen sie mich bald unter dem Schott hervor. Kleiner Scherz: Die Schläfer zuerst.`,"goal.collectors.done":`{n} Photonen pro Sekunde – genug für {grinders, plural, one {# Schleiferei} other {# Schleifereien}}.`,"goal.mix.done":`Bernstein – eine Farbe, die kein Prisma liefert. Sie haben sie gemacht.`,"goal.focus.done":`Resonatoren fertig – Licht, gefangen in reiner Schwingung.`,"goal.beam.done":`Der Strahl ist angekommen. Licht ist nicht länger an Lichtleiter gebunden.`,"goal.spectrum_m.done":`Das Zentrum hat das erste Spektrum gelesen! Noch {n} Spektren M – und es erforscht die Resonanz.`,"goal.resonance.done":`Harpunen in Resonanz – doppelt so schnell.`,"goal.spectrum_k.done":`Zweite Klasse gelesen. Das Zentrum erhält einen zweiten Ring und Strahlen.`,"goal.liquid.done":`Licht fließt durch die Rohre wie Honig. Mama hätte das nicht geglaubt.`,"goal.spectrum_g.done":`Drei Spektren gelesen. Das Zentrum ist bereit für das Tiefensignal.`,"intro.title":`Saatschiff „Schwalbe“`,"intro.p1":`Sie sind der Warden des Saatschiffs „Schwalbe“ – die einzige Person, die während des Flugs wach bleibt. An Bord: vierzig schlafende Kolonisten, ein alter Bordingenieur und die KI namens ORA. Die „Schwalbe“ ist das siebte von zwölf Schiffen, Kurs: Klarstern.`,"intro.p2":`Geht unterwegs etwas schief, rettet Sie das Sternenlicht: Bögen fangen es ein, und die Fabrik macht daraus alles andere. Die Baupläne liegen im Archiv des Schiffs.`,"intro.start":`Abflug`,"card.pick":`Wählen Sie einen Gegenstand oder ein Rezept – hier steht, was es ist und wozu es dient.`,"card.byHand":`Von Hand`,"card.cat.ore":`Gestein`,"card.cat.intermediate":`Material`,"card.cat.building":`Bau`,"card.cat.ship":`Schiffsmodul`,"card.have":`vorhanden: {n}`,"card.made":`Herkunft`,"card.used":`Verwendet für`,"lock.lab":`Freigeschaltet im Zentrum: {tech}`,"toast.locked":`{item} ist gesperrt – das Zentrum schaltet es frei: {tech}`,"inv.items":`Gegenstände`,"inv.craftHint":`Klick – Beschreibung und Fertigung; Rechtsklick – eins fertigen`,"lab.title":`Forschungszentrum`,"lab.tier":`Rang {n}`,"lab.lore":`Zentren werden nach einem Bauplan aus dem Schiffsarchiv gebaut. Jedes liest Spektren im Licht – ein Lichtleiter an eine beliebige Seite. Warteschlange und Fortschritt sind gemeinsam, doch jedes Zentrum hat seine eigene Wissenschaft und liest seine eigene Einheit – mehr Zentren heißt schnellere Forschung. Jede gelesene Spektralklasse schaltet Technologien frei und entzündet einen Ring in ihrer Farbe.`,"lab.spectra":`Wissenschaft in allen Zentren`,"lab.delivered":`gesamt {n}`,"lab.putSpectra":`Wissenschaft an die Zentren abgeben (nächste zuerst)`,"lab.current":`Wird erforscht`,"lab.idle":`Wählen Sie eine Technologie: „Zuerst“ oder „Einreihen“ in der Liste unten oder im Baum. Das Zentrum beginnt nichts von selbst – die Forschung wartet in seinen Plätzen.`,"lab.tree":`Technologiebaum`,"lab.request":`{spectra} {have}/{need} → {tech}`,"tech.queued":`eingereiht · {n}`,"tech.state.done":`erforscht`,"tech.state.current":`in Forschung`,"tech.state.queued":`eingereiht`,"tech.state.available":`verfügbar`,"tech.state.locked":`gesperrt`,"tech.cost":`Kosten: Einheiten × je ein Stück jeder Stufe`,"tech.requires":`Zuerst: {list}`,"tech.enqueue":`Einreihen`,"tech.dequeue":`Entfernen`,"tech.first":`Zuerst`,"fluid.amount":`{n} Einh. {name}`,"machine.fluid":`{name}: {n} Einh.`,"machine.net":`{name} im Netz: {n} / {cap} Einh.`,"machine.boost":`Resonanz +{n} %`,"machine.resonance":`Resonanznetz: {n} % des Bedarfs gedeckt`,"etude.title":`Versuche`,"etude.lore":`Kurze Rätsel mit vertrautem Licht: begrenzter Bausatz, eine Aufgabe. Je schneller, billiger und kompakter, desto besser.`,"etude.parts":`{n, plural, one {# Bauteil} other {# Bauteile}}`,"etude.area":`Fläche {n}`,"etude.best":`Bestes Ergebnis:`,"etude.start":`Versuch starten`,"etude.solved":`Versuch gelungen!`,"etude.goal":`Mit Maschinen herstellen: {item} × {n}`,"etude.again":`Noch einmal`,"etude.pure_tone.name":`Reine Farbe`,"etude.pure_tone.task":`Drei Weißlichtquellen, ein Prisma und eine Bank: Geben Sie der Bank nur Rot und fertigen Sie {n} Rubinlinsen. Wertung – Bauteile, Fläche, Zeit. Strahlen sparen Lichtleiter.`,"lab.waiting":`Eine Einheit ist je ein Stück jeder Stufe. Es fehlt: {spectra}. Zusätzliche Spektren anderer Klassen beschleunigen nichts.`,"hint.prism.3":`Die Maschinen an den Ausgängen nehmen gerade kein Licht: Ihr Produkt kann nirgendwohin, oder ein anderer Eingang fehlt. Geben Sie ihnen Arbeit – das Prisma läuft von selbst weiter.`,"hint.drill.6":`Der Ausgang der Harpune führt ins Leere – drehen Sie sie (R) zu einem Gravoband, einer Maschine oder einem Lager.`,"hint.crafter.7":`Zu wenig Licht: Das Netz teilt das Licht unter allen Verbrauchern auf (auch Segel trinken mit). Setzen Sie mehr Bögen auf die Schale, einen zweiten Empfänger, oder trennen Sie das Netz.`,"menu.title":`Menü`,"menu.tagline":`Eine Fabrik um einen lebendigen Stern`,"menu.continue":`Fortsetzen`,"menu.newWorld":`Neue Welt`,"menu.back":`← Zurück`,"menu.difficulty":`Schwierigkeit`,"menu.seed":`Welt-Seed`,"menu.randomSeed":`Zufälliger Seed`,"menu.start":`Starten`,"difficulty.calm":`Betrachtung`,"difficulty.calm.desc":`Kein Schwarm. Nur Licht, Gürtel und Bauen.`,"difficulty.standard":`Standard`,"difficulty.standard.desc":`Nester erwachen durch Streulicht und schicken Wellen – immer mit Vorwarnung. Geschütze, Barrieren und Reparatur retten die Basis.`,"difficulty.abyss":`Abgrund`,"difficulty.abyss.desc":`Nester sind näher, Wellen häufiger und heftiger, Planeten unter Brutstöcken. Für Erfahrene.`,"settings.title":`Einstellungen`,"settings.tab.general":`Allgemein`,"settings.tab.graphics":`Grafik`,"settings.tab.sound":`Ton`,"settings.tab.controls":`Steuerung`,"settings.tab.access":`Barrierefreiheit`,"settings.lang":`Sprache`,"settings.quality":`Qualität`,"settings.quality.low":`Niedrig`,"settings.quality.medium":`Mittel`,"settings.quality.high":`Hoch`,"settings.quality.ultra":`Ultra`,"settings.quality.hint":`{touch, select, yes {Niedrig schaltet Bloom ab: für schwache Telefone und lange Akkulaufzeit. Ultra rendert in voller Bildschirmschärfe und erwärmt das Telefon stärker.} other {Niedrig schaltet Bloom ab: für schwache Grafikkarten und Laptops im Akkubetrieb. Ultra rendert in voller Bildschirmschärfe und belastet die Grafikkarte stärker.}}`,"settings.showFps":`FPS anzeigen`,"settings.muted":`Stumm`,"settings.master":`Lautstärke`,"settings.effects":`Effekte`,"settings.ambience":`Atmosphäre`,"settings.voices":`Figurenstimmen`,"settings.keys.hint":`Klicken Sie auf die Taste einer Aktion und drücken Sie dann eine neue. Esc bricht ab.`,"settings.keys.press":`Taste drücken…`,"settings.keys.fixed":`Immer: WASD – Flug; Mausrad – Zoom; gedrückt halten und ziehen – Umsehen; Leertaste – Kamera zum Kutter; LMT – platzieren oder öffnen; RMT – aus der Hand legen, mit leerer Hand abreißen; Shift+RMT / Shift+LMT – Rezept kopieren und einfügen; 1–0 – Bauten der Leiste, Shift+1–0 – ihre Reiter; Tab – Inventar; Strg+Z / Strg+Y – Rückgängig und Wiederholen; Strg+C / Strg+V – Bauplan; Strg+S – Speichern; Esc – Fenster schließen oder Pause.`,"settings.keys.reset":`Tasten zurücksetzen`,"settings.uiScale":`Oberflächengröße`,"settings.reduceFlashes":`Weniger Blitze und Blinken`,"settings.shapesAlways":`Farbformen immer zeigen – Licht auch ohne Farbe unterscheiden (Farbfehlsichtigkeit)`,"settings.access.hint":`Jede Lichtfarbe hat ihre eigene Form: Scharlach ▲, Smaragd ●, Azur ◆, Bernstein ■ – wie die Zeichen auf den Rücken des Schwarms.`,"key.rotate":`Drehen`,"key.pipette":`Pipette`,"key.remove":`Abreißen`,"key.inventory":`Inventar`,"key.lab":`Forschung`,"key.alt":`Alt-Modus`,"key.pause":`Pause`,"key.sound":`Ton an/aus`,"key.stats":`Statistik`,"key.blueprint":`Bauplan`,"status.13":`Kein Partner`,"status.13.hint":`Setzen Sie das zweite Portal in Laufrichtung, innerhalb der Faltenreichweite (Forschung erhöht sie). Eine Frachtfalte braucht einen Ausgang; Licht- und Rohrfalten ein Portal, das zurückzeigt.`,"status.14":`Überhitzt`,"status.14.hint":`Die Maschine ist zu heiß: Sie arbeitet langsamer, Licht geht als Streulicht verloren. Rücken Sie sie vom Stern weg (r ≥ 7,5) oder stellen Sie einen Eisradiator auf.`,"status.15":`Erloschen`,"status.15.hint":`Die Maschine steht: von Hagel betäubt oder unter einem Viertel ihrer Haltbarkeit. Reparieren Sie sie – oder warten Sie, die Betäubung lässt nach.`,"status.16":`Verliert Licht`,"status.16.hint":`Ein Teil des Lichts kann nirgendwohin und wird zu Streulicht. Nutzen Sie den überzähligen Ausgang oder leiten Sie ihn in einen Absorber.`,"status.17":`Kein Eis`,"status.17.hint":`Führen Sie mit einem Greifer Eis zu: 1 Stück pro {burn} Sekunden Kühlung.`,"hud.glare":`Streulicht {v} ph/s`,"bp.title":`Baupläne`,"bp.lore":`Ein gelungener Block? Nicht noch einmal zusammenbauen. Ziehen Sie einen Rahmen darüber: Der Bauplan landet in Ihrer Hand und in der Bibliothek. {touch, select, yes {„Drehen“ dreht ihn, ein Tippen wählt den Ort, „Platzieren“ baut.} other {R dreht, Klick platziert.}} Gebaut wird aus dem Inventar; was fehlt, wird übersprungen.`,"bp.copy":`Mit Rahmen kopieren`,"bp.copyHint":`Ziehen Sie einen Rahmen über Bauten, um sie zu kopieren. Esc bricht ab.`,"bp.library":`Bibliothek`,"bp.empty":`Noch leer: Kopieren Sie einen Teil Ihrer Basis.`,"bp.count":`{n, plural, one {# Bau} other {# Bauten}}`,"bp.use":`Nehmen`,"bp.share":`Code`,"bp.delete":`Bauplan löschen`,"bp.import":`Aus Code hinzufügen`,"bp.add":`Hinzufügen`,"bp.bad":`Das ist kein Bauplan-Code, oder er ist beschädigt.`,"bp.skipped":`Unbekannte Bauten übersprungen: {n}`,"bp.shared":`Bauplan-Code kopiert – zum Teilen einfügen.`,"bp.name":`Bauplan {n}`,"bp.copied":`{n, plural, one {# Bau} other {# Bauten}} kopiert. {touch, select, yes {Tippen Sie auf einen Ort und dann auf „Platzieren“.} other {R dreht, Klick platziert.}}`,"bp.pasted":`Gebaut: {n}`,"bp.pastedPart":`{n} von {all} gebaut: Der Rest ist blockiert, oder es fehlen Gegenstände.`,"etude.goal.light":`Liefern Sie {n} ph des richtigen Lichts an den Empfänger`,"etude.goal.item":`Liefern Sie {n} Stk. an den Empfänger`,"etude.goal.fluid":`Liefern Sie {n} Einh. flüssiges Licht an den Empfänger`,"etude.through_wall.name":`Durch die Wand`,"etude.through_wall.task":`Die Schleiferei steckt in einem doppelten Mauerring, zwischen den Ringen liegen 7 Felder – keine Falte reicht über beide auf einmal. Quarz, weißes Licht und Empfänger liegen außen. Führen Sie Fracht und Licht in zwei Sprüngen mit Landung zwischen den Ringen und liefern Sie {n} Linsen.`,"etude.amber_duet.name":`Bernsteinduo`,"etude.amber_duet.task":`Machen Sie aus Weiß Bernstein der Helligkeit 3 (Karmesin + Smaragd, dann ein Fokussierer) und liefern Sie {n} ph an den Empfänger hinter der Mauer. Durch die Mauer kommt nur ein Strahl – durchs Fenster.`,"etude.liquid_light.name":`Flüssiges Licht`,"etude.liquid_light.task":`Eine Mauer mit zwei Fenstern: Eis rechts, Licht links. Den blauen Strahl durch ein Fenster, die Flüssigkeit per Rohr durchs andere (ein Fenster ist ein Feld: Strahl und Rohr teilen es nicht). Liefern Sie {n} Einh. flüssiges Licht; überschüssiges Karmesin und Smaragd in Absorber.`,"goal.tunnel":`Ein Gravoband von den Harpunen zur Schleiferei legen`,"goal.tunnel.why":`Ein Kutter, Tausende Brocken. Ein Gravoband bringt sie ohne Sie zur Schleiferei – so wurden die ersten Kolonien an neuen Sternen gebaut.`,"goal.tunnel.hint":`Nehmen Sie ein Gravoband, {touch, select, yes {tippen Sie auf} other {klicken Sie auf}} das Feld am Ausgang der Harpune und ziehen Sie bis zur Schleiferei. Reicht nicht? Fertigen Sie im „Inventar“ weitere aus Quarz und einer Platte.`,"goal.tunnel.done":`Das Gravoband läuft! Im Hafen hat man seit vierzig Jahren keins mehr verlegt – Licht gibt es nur auf Zuteilung, da bleibt nichts übrig.`,"goal.haze":`Klarer Himmel: {n, plural, one {# Prisma} other {# Prismen}} in Betrieb, Streulicht ≤ {glare} ph/s`,"goal.haze.why":`Der graue Dunst ist Streulicht: Licht, das die Basis verloren hat. Es blendet den Schwarm, und ein geblendeter Schwarm fliegt los, um die Quelle zu löschen. Sauberes Licht – ruhiger Schwarm.`,"goal.haze.hint":`Streulicht entsteht an Prismenausgängen ohne Verbraucher, durch Strahlen ins Leere und durch Überhitzung. {touch, select, yes {Tippen Sie auf die Anzeige} other {Klicken Sie auf die Anzeige}} „Streulicht“ – sie zeigt die verursachenden Maschinen. Nutzen Sie überzählige Ausgänge oder leiten Sie sie per Lichtleiter in einen Absorber.`,"goal.haze.done":`Der Himmel ist klar – die Sterne sind wieder sichtbar.`,"goal.spear":`Den „Speer“ erforschen und laden`,"goal.spear.why":`Immer mehr Meteoriten – und der Schwarm war schon da, um die Basis zu prüfen. Der Speer feuert gebündeltes Licht: Er zerschlägt Meteoriten und wehrt Angriffe ab.`,"goal.spear.hint":`Der Speer braucht Helligkeit ≥ {b}: hinter einem Fokussierer. {shot} ph pro Schuss: bei {slow} ph/s ein Schuss alle {every} s, bei {fast} ph/s jede Sekunde. Reichweite {range} Felder.`,"goal.spear.done":`Der Speer ist geladen. Sehen Sie: Ein Komet hält auf die Basis zu – er trägt viel Eis.`,"goal.cooling":`Heißer Ring: {n, plural, one {# Empfänger} other {# Empfänger}} nahe am Stern ohne Überhitzung`,"goal.cooling.why":`Die Kolonie braucht mehr Licht, und am meisten gibt es davon an der Korona. Doch dort glühen die Maschinen: Eis in den Radiator – und die Hitze gehört Ihnen.`,"goal.cooling.hint":`Erforschen Sie „Kühlung“. Der heiße Ring liegt zwischen der Korona des Sterns und Schale I: Dort fängt ein Empfänger mehr Licht, erhitzt sich aber. Stellen Sie einen Eisradiator direkt neben die Empfänger ({n} Felder im Umkreis) und legen Sie Eis mit der Schaltfläche in seinem Fenster ein. Der Radiator verbraucht Eis, solange der Empfänger heiß ist: Eis kommt von Meteoriten, auf Dauer von einem Schleppnetz am Eisgürtel und einem Gravoband mit Greifer in den Radiator (das Schleppnetz wird im Baum freigeschaltet): Der Radiator verbrennt Eis, solange der Empfänger heiß ist.`,"goal.cooling.done":`Mein halbes Leben stehe ich an heißem Metall – ohne Eis dreht man da nicht mal eine Schraube fest. Der Ring ist abgekühlt!`,"goal.blueprint":`Einen Bereich kopieren ({n}+ Bauten) und die Kopie setzen`,"goal.blueprint.why":`Eine Kolonie baut man über Jahre – aus gleichen Blöcken. Ein gelungener Abschnitt muss nicht neu gebaut werden: Ein Bauplan wiederholt ihn.`,"goal.blueprint.hint":`{touch, select, yes {„Mehr“ → „Baupläne“ → „Mit Rahmen kopieren“: Ziehen Sie mit dem Finger einen Rahmen über Bauten, „Kopieren“, dann auf einen Ort tippen und „Platzieren“.} other {Knopf „Baupläne“ oder C – Rahmen ziehen, R dreht, Klick platziert.}}`,"goal.blueprint.done":`Bauplan gespeichert. Das Archiv der „Aussaat“ ist gewachsen – zum ersten Mal durch unsere Arbeit, nicht durch die des Instituts.`,"goal.node":`Schwarmnest: räumen oder einschläfern`,"goal.node.why":`Ein Schwarmnest neben der Basis ist eine ständige Bedrohung. Man kann es mit Gewalt räumen – oder es nicht mehr blenden: {calm} Minuten ohne Streulicht nach einer Welle, und das Nest schläft ein. Beide Wege bringen Antilicht.`,"goal.node.hint":`Setzen Sie einen Speer höchstens {range} Felder vom Nest entfernt (Pfeil) und geben Sie ihm gebündeltes Licht (Helligkeit {b}+): {shots} Schüsse für die Königin. Licht per Strahl: Port → Spiegel → Port. Die Königin schickt Wächter gegen Ihr Schiff – achten Sie auf den Schild.`,"goal.node.done":`Das Nest bedroht die Basis nicht mehr: Ein geräumtes leuchtet als Protostern, ein eingeschlafenes schläft.`,"status.11":`Keine Flüssigkeit`,"status.11.hint":`Schließen Sie ein Rohr mit flüssigem Licht an oder machen Sie den Abfluss frei: Das Rezept braucht Flüssigkeit am Eingang oder Platz dafür am Ausgang.`,"status.12":`Kein Netz`,"status.12.hint":`Kein Pylon oder Rohr in der Nähe – näher aufstellen.`,"machine.heat":`Hitze {n} %`,"machine.heatLoss":`verliert Licht als Streulicht – vom Stern wegrücken oder Radiator aufstellen`,"machine.glare":`Verliert {n} ph/s → Streulicht`,"machine.ice":`Eis: {n}`,"cfg.title.modulator":`Rhythmus`,"cfg.modulator.0":`Stetig ▬▬▬`,"cfg.modulator.1":`Puls ▮ ▮ ▮`,"cfg.modulator.2":`Doppelt ▮▮ ▮▮`,"cfg.modulator.3":`Versetzt ▮ ▮▮ ▮`,"cfg.title.polarizer":`Filterwinkel`,"cfg.polarizer.1":`0°  |`,"cfg.polarizer.2":`45°  /`,"cfg.polarizer.3":`90°  –`,"status.18":`Falscher Rhythmus`,"status.18.hint":`Das Rezept braucht Licht mit anderem Rhythmus: Setzen Sie einen Modulator und wählen Sie den Rhythmus in seinem Fenster.`,"status.19":`Falscher Winkel`,"status.19.hint":`Das Rezept braucht Licht in einem anderen Winkel: Setzen Sie einen Polarisator und wählen Sie den Winkel in seinem Fenster.`,"status.20":`Falsche Phase`,"status.20.hint":`Das Rezept braucht die andere Phase des Lichts: Setzen Sie einen Phasenschieber in den Lichtweg.`,"cfg.title.shutter":`Verschlussmodus`,"cfg.shutter.0":`Offen bei Signal`,"cfg.shutter.1":`NICHT: zu bei Signal`,"status.21":`Kein Empfänger`,"status.21.hint":`Kein Empfangsport auf demselben Kanal mit Platz für die Fracht im Umkreis von {range} Feldern.`,"status.22":`Keine Drohnen`,"status.22.hint":`Legen Sie Drohnen in die Plätze des Ports (ein Montierer baut sie aus Linsen, einem Resonator, Platten und einem Spektrum F).`,"cfg.title.drone_port":`Rolle des Ports`,"cfg.role.0":`Bauen`,"cfg.role.1":`Senden`,"cfg.role.2":`Empfangen`,"cfg.channel":`Kanal {n}`,"drone.title":`Kanal`,"drone.home":`Drohnen daheim: {n}`,"drone.trips":`Flüge gesamt: {n}`,"drone.put":`Drohnen einlegen ({n})`,"bp.pastedGhost":`{n} gebaut, {g} weitere als Geister: Drohnen bauen sie fertig, sobald die Gegenstände ankommen`,"bp.ghosted":`Geister: {g} – Baudrohnen stellen sie fertig, sobald Gegenstände geliefert werden`,"goal.spectrum_f":`{n, plural, one {# Spektrum} other {# Spektren}} F ans Zentrum liefern`,"goal.spectrum_f.why":`Rhythmus ist die dritte Eigenschaft des Lichts nach Farbe und Helligkeit: dasselbe Grün, aber es blinkt nach einem Muster. Die Nester und der Stern blinken genauso – Zeit herauszufinden, was es bedeutet.`,"goal.spectrum_f.hint":`Erforschen Sie „Rhythmus“, setzen Sie einen Modulator zwischen Prisma und Montierer und wählen Sie in seinem Fenster „Puls“. Spektrum F – zwei Smaragdlinsen unter pulsierendem Grün.`,"goal.spectrum_f.done":`Vierte Klasse gelesen. Drohnen tragen Fracht für Sie.`,"goal.drone":`Die erste Drohne auf den Weg schicken`,"goal.drone.why":`Drohnen tragen Fracht und Eis und stellen Bauten fertig, während Sie beschäftigt sind.`,"goal.drone.hint":`Erforschen Sie „Drohnen“. Zwei Ports: Der Sender (Rolle und Kanal in seinem Fenster) hat Drohnen und Fracht, {charge} ph Licht pro Flug; der Empfänger nutzt denselben Kanal. Die Rolle „Sammeln“ bringt Eissplitter.`,"goal.drone.done":`Die Drohne fliegt! Jetzt kann sich ein Bauplan selbst bauen.`,"goal.ghost":`Drohnen {n, plural, one {# Bau} other {# Bauten}} aus Geistern fertigstellen lassen`,"goal.ghost.why":`Ein Bauplan, der sich selbst baut: Drohnen bauen die Geister fertig, während Sie zu Gürteln und Nestern fliegen.`,"goal.ghost.hint":`Ein Bauport mit Drohnen und den Gegenständen der Bauten in seinen Plätzen. {touch, select, yes {Fügen Sie einen Bauplan ein: Was fehlt, erscheint als Geist – Drohnen bauen es fertig, sobald Sie die Gegenstände bringen.} other {Strg+Umschalt+V fügt einen Bauplan als Geister ein; fehlen beim normalen Einfügen Gegenstände, bleiben ebenfalls Geister.}}`,"goal.ghost.done":`Der Bau läuft ohne Sie weiter. Fügen Sie Baupläne vorausschauend ein.`,"goal.spectrum_a":`{n, plural, one {# Spektrum} other {# Spektren}} A ans Zentrum liefern`,"goal.spectrum_a.why":`Polarisation ist die Richtung, in der Licht schwingt. Die Muster des Schwarms sind verschieden gedreht, als wären sie an jemanden gerichtet. Ein Polarisator legt den Winkel fest, nimmt aber die Hälfte des Lichts.`,"goal.spectrum_a.hint":`Erforschen Sie „Polarisation“. A ist cyanfarbenes Licht unter 45°: ein Mischer, ein Polarisator auf 45°, ein Montierer.`,"goal.spectrum_a.done":`Fünf Klassen. Das Licht beherrscht Rhythmus und Winkel – Zeit, ihm das Rechnen beizubringen.`,"goal.logic":`Eine Schaltung bauen: Verschluss und Lampe, {n, plural, one {# Umschaltung} other {# Umschaltungen}} des Verschlusses`,"goal.logic.why":`Licht ist Eins, Dunkelheit ist Null: Die Fabrik kann entscheiden. Und Sonja ist sicher, dass man mit einer Lampe auch antworten kann.`,"goal.logic.hint":`Erforschen Sie „Optische Logik“. Ein Verschluss lässt Licht durch, solange am Seiteneingang ein Signal leuchtet; eine Lampe zeigt das Ergebnis. Ein NICHT mit Rückkopplung ergibt einen Blinker.`,"goal.logic.done":`Licht rechnet. Ein geschlossener Verschluss ist ein perfektes Ventil ohne Streulicht.`,"goal.spectrum_b":`{n, plural, one {# Spektrum} other {# Spektren}} B ans Zentrum liefern`,"goal.spectrum_b.why":`Die Phase ist die fünfte Eigenschaft des Lichts, die Verschiebung einer Welle. Zwei um π verschobene Wellen löschen einander aus – und für den Schwarm bedeutet diese Verschiebung „ja“.`,"goal.spectrum_b.hint":`Erforschen Sie „Phase“ – dafür braucht es die Spektren G, F und A: F und A teilen sich Smaragdlinsen, eine zweite Smaragd-Bank beschleunigt. Spektrum B ist blaues Licht mit Phase π: ein Phasenschieber im Lichtweg. Ein Interferometer zeigt die Auslöschung.`,"goal.spectrum_b.done":`Sechs Klassen gelesen – nur die letzte, O, fehlt noch.`,"achv.title":`Errungenschaften`,"achv.count":`{n} von {all}`,"achv.hidden":`Eine verborgene Errungenschaft – selbst entdecken.`,"achv.at":`in Spielminute {min}`,"achv.toast":`Errungenschaft: {name}`,"achv.group.story":`Geschichte`,"achv.group.mastery":`Meisterschaft`,"achv.group.challenge":`Herausforderungen`,"achv.first_light.name":`Erstes Licht`,"achv.first_light.desc":`Licht hat eine Maschine erreicht.`,"achv.first_spectrum.name":`Erstes Spektrum`,"achv.first_spectrum.desc":`Das Zentrum hat ein Spektrum M gelesen.`,"achv.liquid_dawn.name":`Licht im Rohr`,"achv.liquid_dawn.desc":`Flüssiges Licht floss durch die Rohre.`,"achv.dark_out.name":`Das Nest ist gefallen`,"achv.dark_out.desc":`Die Königin ist tot – wo das Nest war, entzündet sich ein Protostern.`,"achv.first_pulse.name":`Puls`,"achv.first_pulse.desc":`Rhythmus ist die dritte Eigenschaft des Lichts, nach Farbe und Helligkeit.`,"achv.sky_carriers.name":`Himmelskuriere`,"achv.sky_carriers.desc":`Der erste Drohnenflug.`,"achv.logic_gate.name":`Licht rechnet`,"achv.logic_gate.desc":`Die erste Verschlussschaltung läuft.`,"achv.awakening.name":`Verbindung`,"achv.awakening.desc":`Die Fernfaser steht – der Hafen hört die „Schwalbe“.`,"achv.red_horizon.name":`Roter Horizont`,"achv.red_horizon.desc":`Ein Außenposten an einem Protostern im Purpurgrat.`,"achv.spm_60.name":`Ein Spektrum pro Sekunde`,"achv.spm_60.desc":`{n} Spektren pro Minute.`,"achv.spm_300.name":`Spektrograf`,"achv.spm_300.desc":`{n} Spektren pro Minute.`,"achv.spm_1000.name":`Observatorium`,"achv.spm_1000.desc":`{n, number} Spektren pro Minute.`,"achv.machines_100.name":`Hundert Maschinen`,"achv.machines_100.desc":`{n} Bauten in der Welt.`,"achv.machines_500.name":`Eine ganze Stadt`,"achv.machines_500.desc":`{n} Bauten in der Welt.`,"achv.clean_100.name":`Klarer Himmel`,"achv.clean_100.desc":`{min} Minuten ohne Streulicht bei hundert arbeitenden Maschinen (Gravobänder und Lichtleiter zählen nicht).`,"achv.clean_1000.name":`Basis ohne Streulicht`,"achv.clean_1000.desc":`{min} Minuten klarer Himmel bei tausend arbeitenden Maschinen.`,"achv.tunnel_trio.name":`Stadt der Falten`,"achv.tunnel_trio.desc":`Fracht, Licht und Flüssigkeit fließen gleichzeitig durch Falten.`,"achv.blueprint_50.name":`Reißbrett`,"achv.blueprint_50.desc":`Ein Bauplan mit {n} Bauten eingefügt.`,"achv.swarm.name":`Die Schar`,"achv.swarm.desc":`{n} Drohnen gleichzeitig in der Luft.`,"achv.sings.name":`Der blinkende Rechner`,"achv.sings.desc":`Verschlüsse haben {n, number}-mal geschaltet.`,"achv.prima.name":`Prima`,"achv.prima.desc":`Fernfaser nach {h} Std. {m} Min. Spielzeit.`,"achv.no_hands.name":`Ohne Hände`,"achv.no_hands.desc":`Die Fernfaser mit höchstens {n} von Hand gefertigten Gegenständen.`,"achv.silent_hall.name":`Stetiges Licht`,"achv.silent_hall.desc":`Eine Stunde, ohne dass eine Maschine „Kein Licht“ blinkt, bei zehn oder mehr arbeitenden.`,"achv.abyss_awakening.name":`Abgrund`,"achv.abyss_awakening.desc":`Die Fernfaser in einer Welt „Abgrund“.`,"achv.clean_awakening.name":`Sauberer Weg`,"achv.clean_awakening.desc":`Die Fernfaser, ohne den Himmel je mit mehr als {glare} ph/s Streulicht zu erhellen.`,"etude.locked":`Verfügbar nach dem Ziel „{goal}“`,"tech.learned":`Erforscht: {name}`,"tech.learned.opens":`Erforscht: {name} · freigeschaltet: {list}`,"menu.system":`Sternsystem`,"system.cradle":`Die Wiege`,"system.cradle.desc":`Ein gelber Stern der Klasse G und sechs Gürtel. Hier beginnt alles.`,"system.red_ridge":`Der Purpurgrat`,"system.red_ridge.desc":`Ein Roter Zwerg: halb so viel Licht, enge und reiche Gürtel. Weißes Licht nur bei den Glutprotosternen in den Lücken.`,"goal.ridge_light":`{n} ph/s Licht mit Strahlempfängern sammeln`,"goal.ridge_light.why":`Das Licht eines Roten Zwergs ist nur halb so stark – sammeln Sie näher.`,"goal.ridge_light.hint":`Ohne weißes Licht arbeiten Schleifereien (Linsen und Platten) nicht, und der Rote Zwerg liefert nur Bernstein: Weiß gibt es bei Protosternen, jeder mit eigener kleiner Sphäre. Bögen auf der Sphäre des Zwergs liefern Bernstein; der Bausatz enthält 48 Linsen und zwei Bänke – genug für das Azur-Ziel und 4 Bögen, danach Linsen aus der eigenen Schleiferei.`,"goal.ridge_light.done":`Das Licht ist gesammelt. Aber Blau gibt es hier nicht.`,"goal.ridge_blue":`{n, plural, one {# Azurlinse} other {# Azurlinsen}} maschinell fertigen`,"goal.ridge_blue.why":`Blaues Licht gibt es nur bei Protosternen: Bauen Sie einen Außenposten.`,"goal.ridge_blue.hint":`Weiße Protosterne liegen in den Lücken zwischen den Gürteln – der Zielpfeil zeigt zum nächsten. Jeder hat eine eigene kleine Schale für {slots} Bögen: Setzen Sie Bögen und daneben einen Empfänger – er fängt das Weiß. Bei einem Protostern ist es heiß: Der Schild des Schiffs regeneriert dort nicht – setzen Sie Bögen vom Außenrand aus und verweilen Sie nicht.`,"goal.ridge_blue.done":`Der Außenposten arbeitet: Blaues Licht hat die Fabrik erreicht.`,"settings.haptics":`Haptisches Feedback`,"toast.autoQuality":`Niedrige Bildrate: Grafik auf „{q}“ gesenkt (weniger Leuchten).`,"touch.hint":`Ziehen zum Verschieben, Spreizen zum Zoomen. Tippen zeigt einen Geist, „Platzieren“ bestätigt. Maschine halten öffnet ihr Fenster, Tippen mit zwei Fingern bricht ab.`,"forge.title":`Sternschmiede`,"forge.stars":`entzündete Sterne: {n}`,"forge.lore":`Eine uralte Sternschmiede am Schwarzen Loch. Sie nimmt alle sieben Spektren, Antilicht und drei Zeichen der Systeme – und hält das volle Spektrum, bis ein Stern entflammt.`,"forge.chord":`Volles Spektrum: sieben Klassen und Antilicht`,"forge.relics":`Relikte der Systeme`,"forge.relic.in":`eingesetzt`,"forge.relic.have":`im Gepäck – einsetzen`,"forge.relic.none":`fehlt – für das Ziel eines Systems erhältlich`,"forge.put":`Aus dem Gepäck einsetzen`,"forge.progress":`Spektrum halten`,"forge.status.0":`Die Sternschmiede wartet auf das volle Spektrum.`,"forge.status.1":`Das Spektrum hält: Jeder Impuls nimmt je ein Spektrum jeder Klasse und Antilicht.`,"forge.status.2":`Der Stern wartet. Entzünden Sie ihn!`,"forge.status.noRelics":`Benötigte Relikte: {have}/{need}. Ziele der Systeme bringen sie: Grat, Saphir, Zwillinge, Schleier, Pulsar.`,"forge.status.starved":`Das Spektrum ist abgerissen: „{item}“ fehlt. Der Fortschritt sinkt.`,"forge.rule":`Ein Impuls alle {sec} s. Ein verpasster Impuls kostet {drain} Fortschritt, setzt ihn aber nie zurück.`,"forge.eta":`Noch etwa {time} halten.`,"forge.min":`{n} Min.`,"forge.sec":`{n} s`,"forge.ignite":`Stern entzünden`,"finale.nameTitle":`Stern benennen`,"finale.nameLead":`Er brennt. Wie soll er heißen?`,"finale.nameOk":`Benennen`,"finale.creditsTitle":`Abspann`,"finale.credits.0":`Die Sterne erloschen. Sie haben gebeten – und einer leuchtete auf.`,"finale.credits.1":`Jeder Bogen Ihrer Sphäre ist Licht, um das gebeten wurde.`,"finale.credits.2":`Weißes Licht sind sieben Farben, auf einmal gesehen.`,"finale.credits.3":`Die Schmiede ist neu geladen: Der nächste Stern wird mehr verlangen.`,"finale.credits.4":`Ihr Sternbild wartet im Hauptmenü.`,"finale.credits.5":`Eine Fabrik um einen lebendigen Stern.`,"finale.card.time":`Spielstunden`,"finale.card.npm":`Spitze an Spektren pro Minute`,"finale.card.machines":`Maschinen`,"finale.card.stars":`Sterne im Sternbild`,"finale.continue":`Weiter`,"finale.toast.lit":`Der Stern „{name}“ brennt!`,"menu.stars":`Sternbild ({n})`,"menu.starsTitle":`Ihr Sternbild`,"menu.starLine":`{h} h · Spitze {npm} Spektren/min · {machines} Maschinen`,"system.sapphire":`Saphir`,"system.sapphire.desc":`Ein Blauer Riese: um ein Vielfaches mehr Licht – und Hitze: Maschinen und Schild laufen heiß. Jenseits der Schneegrenze liegt ein Heliumreif-Gürtel.`,"system.horizon":`Horizont`,"system.horizon.desc":`Ein Schwarzes Loch mit Akkretionsscheibe – ein überreicher, schneller Gürtel in der Hitze. Die Sternschmiede: Hier wird das Finale entzündet.`,"goal.si":`{n, plural, one {# Spektrum} other {# Spektren}} O mit Maschinen herstellen`,"goal.si.why":`Klasse O – die heißesten Sterne. Der Torschlüssel ist das volle Spektrum von M bis O, und ohne die letzte Klasse lässt er sich nicht zusammensetzen.`,"goal.si.hint":`Erforschen Sie „Klasse O“. O ist purpurnes Licht mit doppeltem Rhythmus und Phase π (Helligkeit {b}+) plus Antilicht: Es kreist als kleiner Gürtel um ein geräumtes oder eingeschlafenes Schwarmnest – holen Sie es mit dem Schleppnetz.`,"goal.si.done":`Sieben Klassen – das volle Spektrum. Die Schmiede haben es den Sternen mit Gewalt abgerungen, wir haben es selbst gebaut.`,"goal.sap_cool":`„Kryotechnik“ erforschen und {n, plural, one {# Kryoradiator} other {# Kryoradiatoren}} aufstellen`,"goal.sap_cool.why":`Der Riesenstern überhitzt Maschinen nahe der Korona: Ohne Kühlung geht das Licht als Streulicht verloren.`,"goal.sap_cool.hint":`Öffnen Sie das Zentrum und reihen Sie „Kryotechnik“ ein (die Spektren liegen im Startbausatz). Der Kryoradiator kühlt Maschinen am Riesen.`,"goal.sap_cool.done":`Die Maschinen sind abgekühlt: Sie können näher am Stern bauen.`,"goal.sap_frost":`{n} Heliumreif mit einem Schleppnetz sammeln`,"goal.sap_frost.why":`Reif ist der Brennstoff des Kryoradiators: Ohne ihn kehrt die Hitze zurück.`,"goal.sap_frost.hint":`Der Reifgürtel liegt jenseits der Schneegrenze (Pfeil). Schleppnetz am Gürtel – Gravoband – Lager; der Radiator nimmt Reif von einem Greifer.`,"goal.sap_frost.done":`Der Reif kommt von selbst.`,"goal.sap_la":`{n, plural, one {# Spektrum} other {# Spektren}} B ans Zentrum liefern`,"goal.sap_la.why":`Im Licht des Riesen entstehen Spektren schneller – aber es ist auch heißer.`,"goal.sap_la.hint":`Spektrum B ist blaues Licht mit Phase π. Nutzen Sie alles, was Sie können: Hier ist das Licht großzügig.`,"goal.sap_la.done":`Der Riese schenkt Licht in Fülle.`,"goal.sap_relic":`{n, plural, one {# Spektrum} other {# Spektren}} pro Minute erreichen`,"goal.sap_relic.why":`Das Zeichen von Saphir: Das Reifrelikt wird am Schwarzen Loch gebraucht.`,"goal.sap_relic.hint":`Alle Spektren zusammen, mindestens {n} pro Minute – die Spitze wird einmal pro Minute gemessen. Setzen Sie Drohnen und äußere Schalen ein.`,"goal.sap_relic.done":`Das Reifrelikt gehört Ihnen und ist in Ihrem Profil gespeichert.`,"goal.hz_light":`{n} ph/s Licht mit Strahlempfängern sammeln`,"goal.hz_light.why":`Das volle Spektrum aus sieben Klassen braucht ≈ 1.000 ph/s Licht.`,"goal.hz_light.hint":`Die Scheibe des Schwarzen Lochs ist sehr hell: Eine Sphäre um sie liefert reichlich. Setzen Sie Bögen und Empfänger; Maschinen an der Korona erhitzen sich – Radiatoren sind Pflicht.`,"goal.hz_light.done":`Licht gesammelt. Jetzt der Schwarm.`,"goal.hz_node":`Schwarmnest: räumen oder einschläfern`,"goal.hz_node.why":`Ein Nest – geräumt oder eingeschlafen – gibt einen Antilichtgürtel frei: Er wird für Spektrum O und für die Sternschmiede selbst gebraucht.`,"goal.hz_node.hint":`Das Nest liegt hinter der Basis (Pfeil). Ein Speer reicht {range} Felder weit, Licht der Helligkeit {b}+. Hier ist die Königin zäher und die Wellen grimmiger; man kann es auch nicht mehr blenden – ein eingeschlafenes Nest gibt denselben Gürtel.`,"goal.hz_node.done":`Das Nest droht nicht mehr – um es kreist ein Antilichtgürtel.`,"goal.hz_si":`„Klasse O“ erforschen und {n, plural, one {# Spektrum} other {# Spektren}} O herstellen`,"goal.hz_si.why":`Die siebte Klasse vervollständigt das volle Spektrum.`,"goal.hz_si.hint":`Spektrum O – Purpur mit doppeltem Rhythmus und Phase π, Helligkeit {b}+, dazu Antilicht aus dem Gürtel eines Nests – geräumt oder eingeschlafen (Schleppnetz).`,"goal.hz_si.done":`Sieben Sternklassen – das volle Spektrum.`,"goal.hz_antilight":`{n} Antilicht mit Schleppnetzen sammeln`,"goal.hz_antilight.why":`{forge} gehen in Spektren O und {forge} in die Sternschmiede.`,"goal.hz_antilight.hint":`Der Antilichtgürtel kreist um ein geräumtes oder eingeschlafenes Nest: Zwei Schleppnetze reichen. Vergessen Sie die Verteidigung nicht.`,"goal.hz_antilight.done":`Antilicht ist da. Bleibt nur die Sternschmiede.`,"goal.hz_ignite":`Den Stern in der Sternschmiede entzünden`,"goal.hz_ignite.why":`Dafür war alles: Das volle Spektrum – weißes Licht – entzündet einen Stern.`,"goal.hz_ignite.hint":`Setzen Sie drei Relikte ein, führen Sie Gravobänder mit sieben Spektren und Antilicht heran (je {rate, number} pro Sekunde) und halten Sie das volle Spektrum {hold} s lang.`,"goal.hz_ignite.done":`Ein Stern brennt!`,"relic.earned":`Relikt erhalten: „{name}“. Es ist in Ihrem Profil gespeichert; drei beliebige öffnen Horizont.`,"achv.class_o_made.name":`Blauer Riese`,"achv.class_o_made.desc":`Ein Spektrum O maschinell gefertigt: Das volle Spektrum ist komplett.`,"achv.cold_giant.name":`Den Riesen kühlen`,"achv.cold_giant.desc":`Die Kryoradiatoren von Saphir laufen.`,"achv.frost_bearer.name":`Im Zeichen des Reifs`,"achv.frost_bearer.desc":`Das Reifrelikt in Saphir errungen.`,"achv.star_lit.name":`Einen Stern entzünden`,"achv.star_lit.desc":`Die Sternschmiede hat das volle Spektrum freigesetzt: Ein neuer Stern leuchtet auf der Karte.`,"hint.noLight.first":`Kein Licht erreicht die Maschine: Setzen Sie einen Bogen auf die Schale am Stern, einen Empfänger daneben und legen Sie einen Lichtleiter. Das Symbol über der Maschine zeigt, was fehlt.`,"toast.autoQuality.undo":`Rückgängig`,"forge.need":`Benötigt: {rate} jedes Spektrums und Antilicht pro Sekunde.`,"forge.relicsHint":`Ohne drei Relikte bleibt die Sternschmiede kalt: Ziele anderer Systeme bringen sie. Sie bleiben in Ihrem Profil und liegen im Gepäck jeder neuen Welt.`,"system.twins":`Zwillinge`,"system.twins.desc":`Zwei Sterne, Bernstein und Blau, mit Gürteln um beide. Weißes Licht wird aus beiden gemischt; Lichtspeicher tragen durch die Nacht.`,"system.veil":`Schleiernebel`,"system.veil.desc":`Ein Nebel: kein Gestein – nur Gürtel aus Eisdunst. Quarz und Obsidian entstehen aus Nebel.`,"system.pulsar":`Kepler-Pulsar`,"system.pulsar.desc":`Ein Neutronenstern blinkt: Alles Licht kommt mit Rhythmus, Spektrum F braucht keinen Modulator. Die Gürtel sind Supernova-Trümmer.`,"goal.twin_white":`{n, plural, one {# Linse} other {# Linsen}} maschinell fertigen`,"goal.twin_white.why":`Schleifereien brauchen weißes Licht, und hier haben die beiden Sterne verschiedene Farben.`,"goal.twin_white.hint":`Die Sphäre der Zwillinge umschließt beide Sterne: Tagsüber ist ihr Licht erst Bernstein, dann Blau – nie beides zugleich. Nehmen Sie Blau direkt von der Sphäre und Bernstein aus einem tagsüber gefüllten Lichtspeicher; beides in einen Mischer, das Weiß zur Schleiferei.`,"goal.twin_white.done":`Zwei Sterne verschmelzen zu weißem Licht.`,"goal.twin_blue":`{n, plural, one {# Azurlinse} other {# Azurlinsen}} maschinell fertigen`,"goal.twin_blue.why":`Blaues Licht gibt es nur beim zweiten Stern: Die Optikbank muss in seiner Nähe stehen.`,"goal.twin_blue.hint":`Der blaue Stern liegt 70 Felder vom bernsteinfarbenen entfernt. Bauen Sie dort einen Außenposten oder legen Sie einen Lichtleiter: Die Helligkeit sinkt mit der Entfernung.`,"goal.twin_blue.done":`Blaues Licht hat die Fabrik erreicht.`,"goal.twin_relic":`{n, plural, one {# Spektrum} other {# Spektren}} pro Minute auch nachts halten`,"goal.twin_relic.why":`Das Zeichen der Zwillinge: Das Relikt wird am Schwarzen Loch gebraucht.`,"goal.twin_relic.hint":`Alle Spektren zusammen, mindestens {n} pro Minute – auch am Ende der Nacht, wenn keine Sterne da sind. Das Licht der Sphäre wechselt die Farbe mit den Sternen, durch die Nacht tragen die Lichtspeicher.`,"goal.twin_relic.done":`Das Zwillingsrelikt ist erhalten und in Ihrem Profil gespeichert.`,"goal.veil_quartz":`{n} Quarz aus Nebel mit Maschinen gewinnen`,"goal.veil_quartz.why":`Hier gibt es kein Gestein – ohne Quarz keine Linsen und keine Spektren.`,"goal.veil_quartz.hint":`Eis (Pfeil) plus blaues Licht im Kondensator ergibt flüssiges Licht; ein zweiter Kondensator mit „Quarz aus Nebel“ macht aus Eis und flüssigem Licht Quarz.`,"goal.veil_quartz.done":`Quarz entsteht aus Licht.`,"goal.veil_lens":`{n, plural, one {# Linse} other {# Linsen}} maschinell fertigen`,"goal.veil_lens.why":`Linsen sind die Grundlage jedes Spektrums; jetzt reichen sie für eine Fabrik.`,"goal.veil_lens.hint":`Stellen Sie Kondensatoren in Reihen auf: Gravobänder und Greifer arbeiten genauso wie bei Gestein.`,"goal.veil_lens.done":`Die Linien laufen ohne festen Boden.`,"goal.veil_relic":`Je {n, plural, one {# Spektrum} other {# Spektren}} M und K ans Zentrum liefern`,"goal.veil_relic.why":`Das Zeichen des Schleiers: Das Relikt wird am Schwarzen Loch gebraucht.`,"goal.veil_relic.hint":`Spektren entstehen wie überall, nur der Rohstoff kommt aus Nebel: Schleppnetz am Eisdunst, Kondensator, Nebel zu Quarz. Licht ist hier knapper.`,"goal.veil_relic.done":`Das Schleierrelikt ist erhalten und in Ihrem Profil gespeichert.`,"goal.pulse_light":`{n} ph/s Licht mit Strahlempfängern sammeln`,"goal.pulse_light.why":`Der Stern ist hell, aber sein Licht kommt in Pulsen; es muss noch eine Verwendung finden.`,"goal.pulse_light.hint":`Der Puls zeigt sich als Blinken in den Lichtleitern. Schleifereien und Spektren M/K/G stört er nicht: Sie nehmen jeden Rhythmus.`,"goal.pulse_light.done":`Der Pulsar speist die Fabrik.`,"goal.pulse_fa":`{n, plural, one {# Spektrum} other {# Spektren}} F ans Zentrum liefern`,"goal.pulse_fa.why":`Spektrum F ist Rhythmus, und hier kommt er von selbst: kein Modulator nötig.`,"goal.pulse_fa.hint":`Grünes Licht mit Puls: Der grüne Ausgang des Prismas behält den Rhythmus des Sterns. Der Montierer für F nimmt es, wie es ist.`,"goal.pulse_fa.done":`Rhythmus direkt aus der Kiste – er funktioniert.`,"goal.pulse_relic":`Je {n, plural, one {# Spektrum} other {# Spektren}} M, K und F ans Zentrum liefern`,"goal.pulse_relic.why":`Das Zeichen des Pulsars: Das Relikt wird am Schwarzen Loch gebraucht.`,"goal.pulse_relic.hint":`Drei Spektren im Takt des Pulsars. Wird das Licht trüb, mischen Sie nur Strahlen mit gleichem Rhythmus.`,"goal.pulse_relic.done":`Das Pulsarrelikt ist erhalten und in Ihrem Profil gespeichert.`,"stick.label":`Flugstick des Wardens`,"keeper.recenter":`Zum Warden`,"toast.far":`Außer Reichweite des Wardens – fliegt näher heran`,"toast.farMining":`Abbau gestoppt: Der Warden ist zu weit weg`,"guide.title":`Tutorial`,"guide.skip":`Tutorial verlassen`,"guide.skipStep":`Schritt überspringen`,"guide.fly":`Fliegen Sie zur Markierung bei den blauen Brocken: Tasten WASD. Mausrad – Zoom, Leertaste – Kamera zum Kutter. Der Pfeil am Bildschirmrand zeigt den Weg.`,"guide.fly.touch":`Schieben Sie den Stick zur Markierung bei den blauen Brocken. Der Pfeil am Bildschirmrand zeigt den Weg.`,"guide.fly.why":`Fliegen Sie nicht zu nah an den Stern: Der Schild überhitzt. Ich brauche Sie einsatzbereit.`,"guide.mine":`Klicken Sie auf einen blauen Brocken – der Strahl des Kutters baut den Quarz von selbst ab. Benötigt: {n}.`,"guide.mine.touch":`Tippen Sie auf einen blauen Brocken – der Strahl des Kutters baut den Quarz von selbst ab. Benötigt: {n}.`,"guide.mine.why":`Von Hand dauert es, ich weiß. Die ersten Brocken immer von Hand, Warden. Die Maschinen kommen danach.`,"guide.lay-tunnel.touch":`Tippen Sie auf das {o, select, 1 {obere} 2 {rechte} 3 {untere} other {linke}} Ende des Rahmens und ziehen Sie, ohne loszulassen, {o, select, 1 {nach unten} 2 {nach links} 3 {nach oben} other {nach rechts}} bis zum Ende.`,"guide.place-grinder":`Platzieren Sie die Schleiferei im Rahmen neben dem Empfänger.`,"guide.place-grinder.repick":`Nehmen Sie die Schleiferei aus der Bauleiste: Sie schleift Quarz zu Linsen.`,"guide.recipe":`Drücken Sie auf die Schleiferei und wählen Sie das Rezept „Linse“.`,"guide.recipe.open":`Drücken Sie auf die Schleiferei, um ihr Fenster zu öffnen.`,"guide.recipe.why":`Das Rezept sagt einer Maschine, was sie herstellen soll. Die Maschinen hier sind verständig – anders als die Navigation.`,"guide.place-grabIn":`Platzieren Sie einen Greifer im Rahmen zwischen Gravoband und Schleiferei.`,"guide.place-grabIn.rotate":`Drehen Sie den Greifer, bis sein Pfeil {o, select, 1 {nach links} 2 {nach oben} 3 {nach rechts} other {nach unten}} zeigt – zur Schleiferei: „Drehen“ oder R, noch {n, plural, one {# Mal} other {# Mal}}.`,"guide.place-grabIn.repick":`Nehmen Sie einen Greifer aus der Bauleiste: Er nimmt von hinten und legt nach vorn ab, in Pfeilrichtung.`,"guide.place-grabOut":`Der zweite Greifer kommt in den Rahmen {o, select, 1 {unter der Schleiferei} 2 {links von der Schleiferei} 3 {über der Schleiferei} other {rechts von der Schleiferei}}: Er bringt die Linsen hinaus.`,"guide.place-grabOut.rotate":`Drehen Sie den Greifer, bis sein Pfeil {o, select, 1 {nach unten} 2 {nach links} 3 {nach oben} other {nach rechts}} zeigt – weg von der Schleiferei: „Drehen“ oder R, noch {n, plural, one {# Mal} other {# Mal}}.`,"guide.place-grabOut.repick":`Nehmen Sie noch einen Greifer.`,"guide.place-storage":`Platzieren Sie das Lager – eine Kiste – im Rahmen vor dem Pfeil des zweiten Greifers.`,"guide.place-storage.repick":`Nehmen Sie das Lager – eine Kiste für fertige Linsen.`,"guide.lay-lights":`Nehmen Sie einen Lichtleiter und ziehen Sie ihn entlang des Rahmens vom Empfänger zur Schleiferei.`,"guide.lay-lights.repick":`Nehmen Sie einen Lichtleiter: Er leitet Licht vom Empfänger zu einer Maschine.`,"guide.first-lens":`Sehen Sie: Quarz fliegt, die Schleiferei arbeitet. Warten Sie auf die erste Linse in der Kiste.`,"guide.first-lens.why":`Steht eine Maschine, erscheint ein Symbol über ihr – {touch, select, yes {tippen Sie} other {klicken Sie}} auf die Maschine, ihr Fenster sagt, was fehlt.`,"guide.done":`Tutorial abgeschlossen! Ab jetzt führt die Zielkarte oben.`,"guide.recipe.look":`Drücken Sie „Ansehen“ (Esc): Dann öffnet {touch, select, yes {ein Tipp} other {ein Klick}} eine Maschine, statt zu bauen.`,"landmark.lab":`Modulwrack`,"landmark.lab.sub":`„Schwalbe“ · Kryodeck und Archiv`,"landmark.star":`Stern der Wiege`,"landmark.star.sub":`die Quelle des Lichts`,"intro.t0":`Das Licht erlischt`,"intro.p0":`Vor mehr als zwei Jahrhunderten lernten die Menschen, den Raum mit Hypertoren zu vernähen, und verbanden dreihundert Sterne. Dann wurden die Sterne trüber, einer nach dem anderen. Man nannte es das Erlöschen: Ohne Licht erloschen die Tore, und Kolonien verschwanden im Dunkel.`,"intro.t1":`Sie sind der Warden`,"intro.t2":`Licht ist Leben`,"intro.next":`Weiter`,"intro.skip":`Überspringen`,"compass.label":`Ziel außerhalb des Bildes, {n} Felder`,"compass.cells":`{n} F.`,"menu.play":`Spielen`,"menu.replayGuide":`Tutorial wiederholen`,"lab.noteHow":`{touch, select, yes {tippen} other {klicken}} – wir zeigen, wie man es erhält`,"guide.place-grinder.why":`Die Schleiferei schleift Linsen aus Quarz. Alles, was wir bauen, braucht Linsen.`,"guide.place-grabIn.why":`Der Greifer nimmt vom Gravoband und legt in die Schleiferei. Ein Arm, nur ohne Ellbogen.`,"tools.more":`Mehr`,"tools.hideHud":`Oberfläche ausblenden`,"hud.show":`Oberfläche einblenden`,"place.title":`Platzierung bestätigen`,"place.cancel":`Abbrechen`,"place.build":`Platzieren`,"place.remove":`Abreißen`,"place.copy":`Kopieren`,"stick.hide":`Stick ausblenden`,"stick.show":`Warden-Stick einblenden`,"stick.flip":`Stick auf die andere Seite`,"settings.stickSide":`Warden-Stick`,"settings.stickSide.left":`Links`,"settings.stickSide.right":`Rechts`,"settings.stickSide.off":`Aus`,"settings.confirmPlace":`Platzieren mit zwei Tipps`,"settings.confirmPlace.hint":`Ein Tippen zeigt einen Geist, der Knopf „Platzieren“ bestätigt: So verdeckt der Finger nie die Stelle. Ausschalten, um sofort zu bauen.`,"settings.bigButtons":`Große Schaltflächen`,"shell.worlds":`Welten`,"shell.stars":`Sternbild`,"shell.about":`Über das Spiel`,"shell.exit":`Beenden`,"shell.exit.title":`Spiel beenden?`,"shell.exit.text":`Ihre Welt ist gespeichert – Sie machen genau dort weiter, wo Sie aufgehört haben.`,"shell.cancel":`Abbrechen`,"shell.playWorld":`Spielen: {name}`,"shell.rename":`Umbenennen`,"shell.delete":`Löschen`,"shell.delete.title":`Welt löschen?`,"shell.delete.text":`„{name}“ und alle Spielstände davon sind dann für immer verloren.`,"shell.deleted":`Welt gelöscht`,"shell.timeH":`{h} Std. {m} Min.`,"shell.timeM":`{m} Min.`,"shell.loading":`Die Welt erwacht …`,"shell.loadFailed":`Der Spielstand ließ sich nicht öffnen – die Welt wurde neu begonnen`,"shell.create.title":`Neue Welt`,"shell.create.name":`Name der Welt`,"shell.create.randomName":`Zufälliger Name`,"shell.create.advanced":`Erweitert`,"shell.create.tutorial":`Schritt-für-Schritt-Tutorial`,"shell.create.go":`Welt erschaffen`,"pause.title":`Menü`,"pause.resume":`Weiter`,"pause.save":`Speichern`,"pause.toTitle":`Zum Hauptmenü`,"world.name":`{a} {b}`,"world.a.0":`Tal`,"world.a.1":`Ufer`,"world.a.2":`Weite`,"world.a.3":`Hafen`,"world.a.4":`Heim`,"world.a.5":`Kuppel`,"world.a.6":`Gürtel`,"world.a.7":`Garten`,"world.a.8":`Schwelle`,"world.a.9":`Bucht`,"world.b.0":`der Dämmerung`,"world.b.1":`des Glanzes`,"world.b.2":`der Schimmer`,"world.b.3":`der Morgenröte`,"world.b.4":`des Mittags`,"world.b.5":`der Funken`,"world.b.6":`der Prismen`,"world.b.7":`der Klarheit`,"world.b.8":`des Spektrums`,"world.b.9":`der Reflexe`,"tip.0":`Ein Prisma zerlegt weißes Licht in Farben – aus jeder Farbe entsteht ein eigenes Spektrum.`,"tip.1":`Kamera davongelaufen? Der Knopf mit dem Fadenkreuz oder die Leertaste holen sie zum Warden zurück.`,"tip.2":`Das Zentrum verlangt Spektren: Jede neue Klasse öffnet die nächste Stufe der Technologien.`,"tip.3":`Der Schwarm kommt nie unangekündigt: eine Anzeige mit Timer und Ringe am Nest – schon vorher.`,"tip.4":`Die Dyson-Sphäre wächst in Schichten: Schließen Sie eine Schale für +{closed} % pro Bogen; mehr Licht nötig – bauen Sie die äußere Schale mit einer neuen Stufe.`,"tip.5":`Gürtel drehen sich, innere schneller. Eine Harpune an einer Stelle baut den ganzen Gürtel ab – achten Sie darauf, wie er sich lichtet.`,"tip.6":`Baupläne kopieren ganze Bereiche – einmal bauen, überall platzieren.`,"tip.7":`Der Alt-Modus zeigt den Inhalt von Maschinen direkt auf dem Feld.`,"tip.8":`Festgefahren? Das Ziel oben schlägt den nächsten Schritt vor, und der Pfeil zeigt, wohin Sie fliegen sollen.`,"tip.9":`Versuche sind kurze Lichträtsel – Fehler kosten dort nichts.`,"tip.10":`Die Welt speichert sich alle {sec} s selbst und sobald das Spiel minimiert wird.`,"tip.11":`Jeder Stern, den Sie entzünden, bleibt für immer in Ihrem Sternbild.`,"boot.render":`Leinwand wird vorbereitet …`,"boot.worlds":`Ihre Welten werden gesucht …`,"boot.ready":`Bereit`,"about.idea":`Das Spiel`,"about.idea.text":`Starwarden ist eine Fabrik um einen lebendigen Stern. Bauen Sie Bogen für Bogen eine Dyson-Sphäre um ihn, fangen Sie Gürtelbrocken mit Harpunen, sprengen Sie Kometen mit Strahlen, zerlegen Sie Licht mit fünf Eigenschaften und sammeln Sie das volle Spektrum, um einen neuen Stern zu entzünden.`,"about.made":`Wie es entstand`,"about.made.text":`Bauten, Schiff, Sterne und Schwarm sind in Blender gerendert und per Skript zusammengesetzt; die Porträts der Figuren entstanden mit einem generativen Modell und wurden per Skript überarbeitet (Licht, Animation). Der gesamte Ton wird in Echtzeit synthetisiert – das Spiel enthält keine Audiodateien.`,"about.privacy":`Datenschutz`,"about.privacy.text":`Das Spiel sammelt und sendet keinerlei Daten. Welten und Einstellungen werden nur auf Ihrem Gerät gespeichert.`,"about.thanks":`Dank`,"about.thanks.text":`Den frühen Testern – für das ehrliche „Ich verstehe nichts“, das das Spiel verständlicher gemacht hat.`,"gen.title":`Welteinstellungen`,"gen.preview":`Systemvorschau: Stern, Gürtel, Zentrum, Schwarmnest`,"gen.preview.legend":`Zentrum in der Mitte · Stern mit Korona · gelbe Rahmen – erste Linie · Violett – Schwarmnest`,"gen.presets":`Weltvorlage`,"gen.preset.classic":`Klassisch`,"gen.preset.plenty":`Überfluss`,"gen.preset.scarce":`Knappheit`,"gen.preset.deep":`Tiefer Raum`,"gen.preset.custom":`Eigene`,"gen.preset.classic.desc":`Die vorgesehene Balance: normale Gürtel, ein heller Stern, der Schwarm zu seiner Zeit.`,"gen.preset.plenty.desc":`Reiche, breite Gürtel, mehr Kometen, ein hellerer Stern, ein ruhigerer Schwarm, ein großzügiger Bausatz.`,"gen.preset.scarce.desc":`Arme, schmale Gürtel, seltene Kometen, ein schwacher Stern, ein früherer Schwarm. Jeder Brocken zählt.`,"gen.preset.deep.desc":`Ein weites System: Gürtel weit auseinander, aber reicher, ein größerer Stern. Für Gestein müssen Sie reisen.`,"gen.preset.custom.desc":`Eigene Werte – klappen Sie die Gruppen unten auf. Die Welt ist immer schaffbar: Der Generator prüft den Start.`,"gen.group.res":`Gürtel und Kometen`,"gen.group.star":`Stern`,"gen.group.dark":`Schwarm`,"gen.group.kit":`Startausrüstung`,"gen.knob.star_power":`Helligkeit`,"gen.knob.dark_freq":`Nesthäufigkeit`,"gen.knob.dark_delay":`Nestwachsamkeit`,"gen.kit.0":`Bescheiden`,"gen.kit.1":`Normal`,"gen.kit.2":`Großzügig`,"gen.code":`Weltcode`,"gen.code.copy":`Weltcode kopieren`,"gen.code.copied":`Weltcode kopiert – zum Teilen bereit`,"gen.code.bad":`Code nicht erkannt. Fügen Sie eine Zeichenfolge wie PHW1-… ein`,"gen.reset":`Auf „Klassisch“`,"gen.hint.star_power":`Leuchtkraft des Sterns: Ein schwacher Stern gibt der Sphäre weniger – äußere Schalen stoßen früher an die Grenze.`,"gen.hint.dark_freq":`Wie viele Schwarmnester es gibt; das erste Nest existiert immer – das Finale braucht es.`,"gen.hint.dark_delay":`Wie viel Streulicht die Nester weckt: ×2 – doppelt so hell nötig, ×0,5 – halb so viel genügt.`,"etude.crossed_filters.name":`Gekreuzte Filter`,"etude.crossed_filters.task":`Das Licht der Quelle ist unter 0° polarisiert, der Empfänger nimmt nur 90°. Eine 90°-Platte blockiert alles – aber was, wenn Sie eine weitere dazwischen setzen? Liefern Sie {n} ph (den Winkel im Fenster des Polarisators einstellen).`,"etude.phase_cancel.name":`Phase π`,"etude.phase_cancel.task":`Zwei blaue Quellen in Gegenphase; der Empfänger nimmt nur Phase π. Führen Sie sie unverändert im Interferometer zusammen, löschen sie einander aus. Addieren Sie beide Ströme und liefern Sie {n, number} ph.`,"etude.light_gates.name":`Lichttore`,"etude.light_gates.task":`Die Signale A (Rot) und B (Grün) blinken. Der obere Empfänger zählt weißes Licht nur bei „A und B“, der untere bei „A oder B, aber nicht beide“. Langes Licht im falschen Moment setzt seine Zählung zurück. Liefern Sie {n} ph mit Verschlüssen (von der Seite gesteuert) und einem Interferometer.`,"cfg.title.level_gate":`Modus des Füllstandssensors`,"cfg.level_gate.0":`Offen, solange der Nachbar nicht voll ist (< {full} %)`,"cfg.level_gate.1":`Offen, solange der Nachbar nicht leer ist (> {empty} %)`,"goal.twin_cell":`{n, plural, one {# Lichtspeicher} other {# Lichtspeicher}} platzieren`,"goal.twin_cell.why":`Bei den Zwillingen gibt es Nächte: {night} s ohne Sterne.`,"goal.twin_cell.hint":`Ein Tag dauert hier {day} Minuten: Der Bernsteinstern scheint {amber} s, der blaue {blue} s, dann folgen {night} s Nacht. Die Zeitleiste steht in der Anzeige „Tageslauf“ unter dem Ziel. Ein Lichtspeicher sammelt tagsüber Licht und gibt es nachts ab: Licht tritt hinten ein, vorne aus. Er merkt sich die erste Farbe und nimmt keine andere. Ein Lichtleiter trägt bis zu {flux} ph/s – eine Linie versorgt 5 Montierer.`,"goal.twin_cell.done":`Die Speicher stehen. Jetzt kommen Sie durch die Nacht.`,"goal.twin_night":`{n, plural, one {# Montierer} other {# Montierer}} bis zum Morgen im Licht halten`,"goal.twin_night.why":`Eine Fabrik, die nie schläft.`,"goal.twin_night.hint":`Gehen beide Sterne unter, gibt es Licht nur noch in den Speichern. Die Anzeige „Tageslauf“ zeigt, wie viele Sekunden der Vorrat jeder Farbe reicht; es zählt, wenn die Maschinen auch am Ende der Nacht noch Licht haben.`,"goal.twin_night.done":`Die Nacht ist vorbei – die Fabrik leuchtete ohne Sterne.`,"toast.dusk":`Nacht: Beide Sterne sind für {night} s untergegangen – Licht nur in den Speichern`,"toast.dawn":`Morgendämmerung: Der Bernsteinstern ist aufgegangen`,"lab.filter":`Baumfilter`,"lab.filter.open":`Verfügbar · {n}`,"lab.filter.all":`Alle · {n}`,"lab.filter.done":`Erforscht · {n}`,"lab.filter.empty":`Hier ist nichts – anderen Filter oder Zweig wählen.`,"lab.branch":`Zweig des Baums`,"tech.level":`St. {n}`,"tech.time":`je {s} s`,"branch.any":`Alle Zweige`,"branch.mining":`Abbau`,"branch.logistics":`Logistik`,"branch.light":`Licht`,"branch.matter":`Materie`,"branch.resonance":`Resonanz`,"branch.logic":`Logik`,"branch.defense":`Verteidigung`,"branch.stars":`Sterne`,"branch.finale":`Finale`,"bonus.grabber":`+{v} % Greifertempo`,"bonus.research":`+{v} % Zentrumstempo`,"bonus.hand":`+{v} % Handarbeit`,"bonus.spear":`+{v} % Speer-Nachladen`,"bonus.glare":`−{v} % Streulicht`,"bonus.drone":`+{v} % Drohnentempo und -fracht`,"bonus.cool":`+{v} % Radiatorkühlung`,"bonus.forge":`+{v} % Schmiedetempo`,"bonus.speed":`+{v} % Maschinentempo`,"bonus.attenuation":`Lichtleiter: −1 Helligkeit pro {n} Felder`,"bonus.tunnel":`Falten bis {n} Felder`,"bonus.swift":`schnelle Drohnen`,"bonus.perLevel":`{one} pro Stufe · gesamt {total} %`,"lock.goto":`Im Zentrum zeigen`,"goal.research":`{n, plural, one {# Schimmer} other {# Schimmer}} fertigen und das Prisma erforschen`,"goal.research.hint":`Das Zentrum braucht Licht: ein Lichtleiter von der Linie an eine beliebige Seite. Eine eigene Schleiferei mit dem Rezept „Schimmer“ (Quarz + Platte): Quarz und Platten in ihrem Fenster „Einlegen“, das Ergebnis „Nehmen“. Im Fenster „Forschung“ beim Zentrum – „Hierher abgeben“; Prisma – „Einreihen“. Die Linsenlinie unverändert lassen. Später nimmt eine Linie Ihnen die Arbeit ab: ein Greifer von der Schimmer-Schleiferei direkt ins Zentrum.`,"goal.research.why":`Das Archiv der „Aussaat“ öffnet sich nicht auf einmal: Das Forschungszentrum liest Schimmer – Wissenschaft – und schaltet Maschinen eine nach der anderen frei.`,"goal.research.done":`Das Zentrum hat seinen ersten Schimmer gelesen. Das Prisma ist frei – das Archiv der „Aussaat“ beginnt sich zu öffnen.`,"bp.locked":`Gesperrte Bauten: {n} – sie werden beim Einfügen übersprungen`,"tree.title":`Technologiebaum`,"tree.count":`{n} von {all} erforscht`,"tree.fit":`Ganzen Baum zeigen`,"tree.queue":`Warteschlange des Zentrums`,"tree.path":`Pfad erforschen · {n}`,"tree.open":`Ganzer Baum`,"lock.gotoTree":`Im Baum zeigen`,"key.tree":`Technologiebaum`,"tree.filter.all":`Alle`,"tree.filter.open":`Verfügbar`,"tree.filter.done":`Erforscht`,"tree.search":`Technologie suchen`,"tree.mini":`Minikarte des Baums – zum Springen drücken`,"guide.tree":`Drücken Sie „Ganzer Baum“ – die Karte aller Entdeckungen, vom Prisma bis zum Finale.`,"guide.tree.why":`Das ist die Karte des Weges. Lang, aber gezeichnet. „Pfad erforschen“ – und das Zentrum reiht alles selbst ein.`,"guide.tree.reopen":`Öffnen Sie das Zentrum erneut – dort ist der Knopf „Ganzer Baum“.`,"tree.queueFull":`{now} kommen jetzt in die Warteschlange, die übrigen {n} folgen, sobald Forschung abgeschlossen ist.`,"tree.goal":`Pfadziel: Das Zentrum füllt die Warteschlange selbst auf.`,"tree.gate":`Stufe {spectrum} – freigeschaltet durch „{tech}“`,"tree.next":`Nächster Schritt:`,"tree.band":`Stufe · {stage}`,"settings.uiScale.capped":`Auf diesem Bildschirm gilt {n} % – größer passt nicht.`,"status.23":`Falscher Gürtel`,"status.23.hint":`Eine Harpune nimmt Gestein (Quarz, Obsidian), ein Schleppnetz nimmt Staub (Reif, Eis, Antilicht). Nehmen Sie den anderen Förderer.`,"status.24":`Gürtel dünnt aus`,"status.24.hint":`Im Gürtel ist weniger als ein Viertel übrig. Zeit, am nächsten, reicheren Gürtel zu bauen.`,"status.25":`Gürtel erschöpft`,"status.25.hint":`Kein Gestein mehr – versetzen Sie den Förderer an einen anderen Gürtel.`,"machine.belt":`Gürtelrest: {n} %`,"machine.noBelt":`Kein Gürtel in Reichweite`,"cfg.role.3":`Sammeln`,"shield.label":`Schild`,"shield.aria":`Schild des Wardens: {n} %`,"toast.heatWarm":`Heiß: Der Schild regeneriert hier nicht. Näher an der Korona gibt es Schaden.`,"toast.heatLow":`Schild fast leer – weg vom Stern!`,"toast.heatEject":`Der Sternwind hat den Warden zurückgeworfen. Nichts ging verloren.`,"goal.harpoon":`{n, plural, one {# Harpune} other {# Harpunen}} bei den blauen Brocken platzieren`,"goal.harpoon.hint":`Bauleiste → Harpune → der Platz an der Markierung, direkt am Gürtel. Der helle Punkt und die Rinne sind der Ausgang; „Drehen“ (R) richtet ihn zum Gravoband aus. {n, plural, one {# Harpune reicht} other {# Harpunen reichen}} für eine Schleiferei.`,"goal.harpoon.why":`Gestein von Hand schleppen geht nicht: Die Schläfer brauchen Licht in Stunden, nicht in Wochen. Eine Harpune fängt Brocken von selbst.`,"goal.harpoon.done":`Die Harpunen haben gefeuert. Das Gestein kommt von selbst – Ihre Hände sind frei, meine Rechenkapazität auch.`,"goal.colors":`Licht in Farben zerlegen`,"goal.colors.hint":`Prisma: Weiß hinten hinein → Rot nach vorn, Smaragd nach links, Azur nach rechts. Legen Sie Linsen auf eine Optikbank unter farbigem Licht.`,"goal.colors.why":`Weißes Licht ist alle Farben zugleich. Das Archiv liest Licht nach Farben, und aus Farben fertigt die Fabrik fast alles – auch die Verteidigung gegen den Schwarm.`,"goal.colors.done":`Das Licht ist in Farben zerlegt – das Zentrum kann sie lesen.`,"goal.ice":`{n} Eis von Meteoriten sammeln`,"goal.ice.why":`Die Kapseln brauchen Kälte, und Kälte heißt hier Eis. Es kommt aus dem All: Eismeteoriten und Kometen fliegen durch das System.`,"goal.ice.hint":`Meteoriten sind helle Brocken, die das System durchqueren; der Pfeil zeigt zum nächsten, der auf Ihre Basis zuhält. {touch, select, yes {Tippen Sie darauf} other {Klicken Sie darauf}} – der Kutter fliegt hin, sein Strahl zerschlägt den Brocken. Fliegen Sie durch die Splitter – das Eis sammelt sich von selbst. Später zerschlägt ein Speer mit gebündeltem Licht Meteoriten für Sie.`,"goal.ice.done":`Eis im Frachtraum. Später fangen Speere und Drohnen es für Sie.`,"goal.deep_signal":`Das Tiefensignal senden`,"goal.deep_signal.why":`Der Stern hat zwei Sekunden nach dem ersten Spektrum geblinkt. Zufall? Das Tiefensignal zerlegt sein Licht bis in die schwächsten Linien.`,"goal.deep_signal.hint":`Tiefensignal: Jede Einheit seines Preises ist je ein Spektrum M, K und G (die Anzahl steht im Fenster des Zentrums). K ist am langsamsten: Stellen Sie einen zweiten Montierer für K auf.`,"goal.deep_signal.done":`Das Signal ist gesendet! Das Zentrum leuchtet mit drei Ringen.`,"goal.awakening":`„Fernfaser“ erforschen – eine Verbindung zum Hafen`,"goal.awakening.why":`Die Fernfaser schlägt eine Verbindung durch die Kehrseite: zum ersten Mal ein klarer Kanal nach Hause, zum Hafen. Und ein Weg zu anderen Sternen.`,"goal.awakening.hint":`Alle sechs Spektren sind nötig: Der Weg zur Fernfaser führt durch alle Klassen, ihr eigener Preis sind Spektren F, A und B. Danach werden Lichtleiter seltener schwächer.`,"goal.awakening.done":`Die Faser steht: Der Hafen wird die „Schwalbe“ hören. Vor Ihnen liegen andere Sterne.`,"goal.ridge_awakening":`Der Ring des Grats ist offen`,"goal.ridge_awakening.why":`Ein offener Ring hält die Straße in beide Richtungen – und trägt das Muster des Grat-Gartens.`,"goal.ridge_awakening.hint":`Er öffnet sich von selbst – durch die Zustimmung des Gartens oder durch den erzwungenen Schlüssel.`,"goal.ridge_awakening.done":`Der Ring des Grats ist offen. In ihm liegt das Muster der Geburt.`,"achv.deep_signal.name":`Tiefensignal`,"achv.deep_signal.desc":`Der Spektrograf fand im Sternenlicht Wiederholungen, wie Sterne sie nicht erzeugen.`,"landmark.ring.quartz_rock":`Gestein für Linsen`,"landmark.ring.obsidian_rock":`Gestein für Platten`,"landmark.ring.ice_haze":`feines Eis – mit Schleppnetz`,"landmark.ring.frost_dust":`Reif – mit Schleppnetz`,"gen.knob.belt_rich":`Gürtelvorrat`,"gen.knob.belt_width":`Gürtelbreite`,"gen.knob.belt_spread":`Systemgröße`,"gen.knob.meteor_rate":`Meteoriten und Kometen`,"gen.knob.star_size":`Sterngröße`,"gen.hint.belt_rich":`Wie viel Gestein jeder Gürtel enthält: ×2 hält doppelt so lange.`,"gen.hint.belt_spread":`Gürtel weiter auseinander: breitere Lücken für die Basis, längere Wege.`,"gen.hint.meteor_rate":`Wie oft Eiskörper durchfliegen: mehr bedeutet mehr Eis.`,"gen.hint.star_size":`Ein größerer Stern ist heller und schiebt die Gürtel nach außen.`,"guide.place-harpoonA":`Platzieren Sie eine Harpune im Rahmen am Gürtel. Der helle Punkt und die Rinne sind ihr Ausgang: Dorthin legt sie die Brocken.`,"guide.place-harpoonA.rotate":`Drehen Sie die Harpune, bis ihr Ausgang {o, select, 1 {nach links} 2 {nach oben} 3 {nach rechts} other {nach unten}} zeigt: „Drehen“ oder R, noch {n, plural, one {# Mal} other {# Mal}}.`,"guide.place-harpoonA.repick":`Nehmen Sie eine Harpune aus der Bauleiste: Sie fängt Gürtelbrocken von selbst.`,"guide.place-harpoonA.why":`Diese Harpune stammt von der Andockklammer. Sie fängt Brocken von selbst – Ihre Hände bleiben frei für Wichtiges.`,"guide.place-harpoonB":`Die zweite Harpune kommt in den Rahmen daneben, Ausgang in dieselbe Richtung.`,"guide.place-harpoonB.rotate":`Drehen Sie die Harpune, bis ihr Ausgang {o, select, 1 {nach links} 2 {nach oben} 3 {nach rechts} other {nach unten}} zeigt: „Drehen“ oder R, noch {n, plural, one {# Mal} other {# Mal}}.`,"guide.place-harpoonB.repick":`Nehmen Sie noch eine Harpune aus der Bauleiste.`,"shell.legacy":`{name} – Welt einer sehr alten Version, nicht unterstützt`,"shell.legacy.note":`Welt einer sehr alten Version (vor Gürteln und Spektren) – nicht unterstützt. Sie können sie löschen und eine neue beginnen.`,"bonus.harvest":`+{v} % Förderertempo`,"bonus.meteor":`+{v} % Meteoriten und Kometen`,"hover.left":`Gürtel: noch {n} % des Gesteins. Der Gürtel dreht sich – eine Harpune baut ihn ganz ab.`,"gen.code.legacy":`Dieser Weltcode stammt aus einer älteren Version und wird nicht unterstützt: Das Spiel hat jetzt Gürtel und Spektren.`,"goal.far_belt":`Neuer Gürtel: Harpunen am dritten Gürtel`,"goal.far_belt.why":`Eine Kolonie heißt Jahre, und der innere Gürtel lichtet sich. Die fernen Gürtel sind reicher: Die Fabrik bleibt nicht stehen, wenn der nahe erschöpft ist.`,"goal.far_belt.hint":`Fliegen Sie zum nächsten Gesteinsgürtel hinter dem Obsidiangürtel und setzen Sie eine Harpune an seinen Rand – es zählt, sobald sie abbaut. Nahe Gürtel lichten sich: Ziehen Sie später um – Harpunen und eine Schleiferei am fernen Gürtel, Linsen in eine Kiste, von dort ein Gravoband zur Basis. Den Restbestand des Gürtels zeigt der Tooltip der Harpune.`,"goal.far_belt.done":`Drei Gürtel in Betrieb – wenn sich der innere lichtet, steht die Fabrik nicht still.`,"goal.fold":`Falten erforschen und Fracht oder Licht unter einem Hindernis hindurchführen`,"goal.fold.why":`Die Basis wächst, und die Linien stoßen aneinander. Eine Raumfalte führt Fracht und Licht unter einem Hindernis hindurch: anfangs {s1} Felder, dann öffnet das Zentrum {s2}, {s3} und {s4}.`,"goal.fold.hint":`Erforschen Sie „Falten“ im Zentrum (Spektrum M). Falte: Das erste Portal ist der Eingang, das nächste in Laufrichtung der Ausgang (wird automatisch gesetzt); per Falte gelangt Fracht auch hinter einen Gürtel. Die Lichtfalte ist eine eigene Forschung: zwei Portale, einander zugewandt. Ein Strahl fliegt ohnehin über Gravobänder und Gürtel und verliert über einem Gravoband {loss} % pro Feld, durch Maschinen aber nur per Falte.`,"goal.fold.done":`Die Linie ist abgetaucht und wieder aufgetaucht! Wie ein Stich im Stoff. Darf ich das in mein Skizzenbuch zeichnen?`,"guide.lay-tunnel":`Klicken Sie auf das {o, select, 1 {obere} 2 {rechte} 3 {untere} other {linke}} Ende des Rahmens und ziehen Sie das Gravoband {o, select, 1 {nach unten} 2 {nach links} 3 {nach oben} other {nach rechts}} bis zum Ende.`,"guide.lay-tunnel.repick":`Nehmen Sie ein Gravoband aus der Bauleiste: Es befördert Brocken.`,"guide.lay-tunnel.reverse":`Das Gravoband läuft in die falsche Richtung. Drücken Sie „Rückgängig“ und ziehen Sie es neu – vom Rahmenende bei den Harpunen.`,"guide.lay-tunnel.why":`Das Gravoband bringt die Brocken von den Harpunen ganz von selbst.`,"status.26":`Kein Strahl`,"status.26.hint":`Der Strahl der Sphäre reicht nicht: Setzen Sie einen Bogen auf die nächste Schale (gestrichelte Bahn am Stern) oder rücken Sie den Empfänger näher – höchstens {range} Felder von einer Bahn mit Bögen.`,"status.27":`Gestein zu weit`,"status.27.hint":`An dieser Stelle ist der Gürtel abgetragen und dreht sich nur langsam. Setzen Sie den Förderer an eine andere Stelle des Gürtels.`,"status.28":`Schale vollständig`,"status.28.hint":`Alle Plätze der Schale dieser Stufe sind belegt. Nehmen Sie die restlichen Bögen heraus und laden Sie Bögen der nächsten Stufe – für die äußere Schale.`,"guide.place-arc":`Nehmen Sie „Bogen I“ aus der unteren Leiste und drücken Sie auf den gestrichelten Ring im Rahmen. Näher heranfliegen ist nicht nötig.`,"guide.place-arc.repick":`Nehmen Sie „Bogen I“ aus der Bauleiste unten.`,"guide.place-arc.why":`Ein Bogen fängt Sternenlicht. Einer liefert {arc} ph/s. Vierzig Schläfer brauchen viele Bögen. Fangen wir mit einem an.`,"guide.place-receiver":`Platzieren Sie den Strahlempfänger – die Schüssel – im Rahmen. Der Bogen schickt ihm einen Strahl.{touch, select, yes {} other { Die linke Maustaste platziert, die rechte legt den Bau aus der Hand.}}`,"guide.place-receiver.repick":`Nehmen Sie den Strahlempfänger aus der Bauleiste.`,"guide.place-receiver.why":`Der Empfänger ist die Steckdose der Basis. Von ihm fließt das Licht zu den Maschinen.`,"goal.arc":`Einen Bogen auf die Bahn am Stern werfen`,"goal.arc.hint":`Bauleiste → „Bogen I“ → {touch, select, yes {tippen Sie auf} other {klicken Sie auf}} den leuchtenden gestrichelten Ring am Stern (die Bahn für Bögen). Nah heranfliegen ist nicht nötig: Der Kutter wirft einen Bogen {reach} Felder weit.`,"goal.arc.why":`Die Notpaneele halten nicht ewig. Ein Bogen fängt das Licht der Wiege – das erste Licht, das für die „Schwalbe“ arbeitet, statt ihre Reserve zu verbrauchen.`,"goal.arc.done":`Der Bogen sitzt im Gerüst. Dieser Stern steht in keinem Katalog, aber mit Licht ist er großzügig. Ich nehme es.`,"goal.catapult":`Katapult: Bögen fliegen von selbst`,"goal.catapult.hint":`Erforschen Sie „Katapult“ im Zentrum (Spektrum M) und stellen Sie es in eine Lücke. Bögen kommen ins Katapult selbst (per Greifer oder „Einlegen“ in seinem Fenster), Licht per Lichtleiter – es schießt sie in freie Plätze der Schale. Ein Langgreifer reicht über ein Feld hinweg, das Gravoband muss also nicht direkt anliegen.`,"goal.catapult.why":`Die Schläfer und das künftige Tor brauchen eine Sphäre aus Hunderten Bögen. Von Hand ist das nicht zu schaffen – das Katapult wirft die Bögen selbst.`,"goal.catapult.done":`Der erste Bogen fliegt – die Sphäre baut sich selbst.`,"goal.crown":`Den Ring aus Bögen um den Stern schließen`,"goal.crown.hint":`Schale I an der Korona hat {slots} Plätze. Eine geschlossene Schale gibt jedem Bogen +{closed} % und leuchtet als ganzer Ring auf. Die ganze Krone liefert {total} ph/s: {rx, plural, one {# Empfänger} other {# Empfänger}} zu je {cap}.`,"goal.crown.why":`Ein geschlossener Ring aus Bögen ist die Krone, die erste Schale. Ihr Licht reicht, um die Kapseln von den Notpaneelen auf das Licht der Basis umzustellen.`,"goal.crown.done":`Die Krone ist geschlossen! Jeder Bogen leuchtet {closed} % heller.`,"goal.shell2":`Schale II: {n, plural, one {# Bogen} other {# Bögen}} der zweiten Stufe`,"goal.shell2.hint":`Erforschen Sie „Schale II“ (Spektrum K). Bogen II wird aus einer Bernsteinlinse, Linsen und Platten gefertigt; seine Bahn liegt am Außenrand der Lücke des Zentrums. Eine äußere Schale fängt das Licht, das die innere durchlässt.`,"goal.shell2.why":`Der Krone fehlt Licht für Spektren K und der Verbindung zum Hafen die Kraft. Eine neue Schale um die alte bringt beides.`,"goal.shell2.done":`Die zweite Schale wächst – die Basis hat mehr Licht.`,"goal.captured":`Stern in der Sphäre: {pct} % seiner Leuchtkraft`,"goal.captured.hint":`Alle Schalen zusammen nehmen einen Anteil der Leuchtkraft des Sterns. Die Schalen III und IV liegen bei den fernen Gürteln; eine volle Sphäre nimmt {n} %.`,"goal.captured.why":`Wie viel Licht der Wiege bereits für Sie arbeitet – und für das künftige Tor. Das Tor wird fast den ganzen Stern brauchen.`,"goal.captured.done":`{pct} % des Sterns sind in Ihrer Sphäre.`,"hover.shell.name":`Schale {n} der Dyson-Sphäre`,"hover.shell.arcs":`Bögen {built} von {n} · je {flux} ph/s`,"hover.shell.star":`Stern in der Sphäre: {p} %`,"hover.shell.hint":`Werfen Sie einen Bogen {n} auf die gestrichelte Bahn; eine geschlossene Schale gibt jedem Bogen +{closed} %.`,"landmark.shell":`Schale {n}`,"landmark.shell.sub":`{built} von {n} Bögen`,"achv.crown_closed.name":`Die Krone`,"achv.crown_closed.desc":`Schließen Sie Schale I der Dyson-Sphäre – ein Ring aus Licht um den Stern.`,"achv.half_star.name":`Halber Stern`,"achv.half_star.desc":`Die Sphäre nimmt die Hälfte der Leuchtkraft des Sterns.`,"achv.whole_star.name":`Der ganze Stern`,"achv.whole_star.desc":`Die Dyson-Sphäre nimmt {pct} % der Leuchtkraft des Sterns auf.`,"launcher.put":`Laden: {name}`,"hover.shell.got":`Empfänger nehmen {got} der {power} ph/s der Sphäre auf`,"hover.shell.lost":`Empfänger nehmen nur {got} von {power} ph/s auf – fügen Sie einen weiteren Empfänger hinzu ({cap} ph/s)`,"lab.sphere":`Stern in der Sphäre: {p} % · {arcs} Bögen`,"goal.more":`Wie geht das?`,"goal.less":`Einklappen`,"goal.part.research":`„{name}“ im Zentrum erforschen`,"goal.part.deliver":`An das Zentrum liefern: {name}`,"goal.part.auto":`Mit Maschinen herstellen: {name}`,"goal.part.make":`Beschaffen: {name}`,"goal.part.build":`Platzieren: {name}`,"goal.beam.part":`Ein Strahl erreicht einen Empfangsport`,"goal.resonance.part":`Harpunen in Resonanz`,"goal.fold.part":`Fracht oder Licht passiert eine Falte`,"goal.shell2.part":`Bögen auf Schale II`,"goal.liquid.part":`Flüssiges Licht erzeugt, Einh.`,"goal.cooling.part":`Empfänger am Stern ohne Überhitzung`,"goal.drone.part":`Erster Drohnenflug`,"goal.logic.part":`Umschaltungen des Verschlusses`,"goal.spear.part":`Speer geladen`,"compass.fly":`Zum Ziel fliegen`,"place.why.busy":`Belegt`,"place.why.belt":`Gürtel – kein Bauplatz`,"place.why.orbit":`Sphärenbahn – nur Bögen`,"place.why.corona":`Sternkorona`,"place.why.far":`Zu weit – {touch, select, yes {erneut tippen} other {erneut klicken}}`,"place.why.items":`Nicht im Inventar`,"place.why.slot":`Bögen nur auf die gestrichelte Schalenbahn`,"place.why.grade":`Falsche Schale – Bogen einer anderen Stufe nötig`,"hint.lab.5":`Wählen Sie eine Technologie im Fenster des Zentrums oder im Baum – das Zentrum beginnt nicht von selbst.`,"machine.putAll":`Alles einlegen: {item}`,"status.lowLight":`Wenig Licht`,"status.lowLight.hint":`Läuft langsamer als das Rezept: Es kommt weniger Licht an, als ein Zyklus braucht. Mehr Bögen und Empfänger – oder weniger Maschinen an diesem Lichtleiter.`,"machine.inflow":`Zufluss {n} ph/s → Zyklus {s} s`,"machine.noInflow":`Zufluss 0 ph/s – kein Licht kommt an`,"status.7.dry":`Kein Licht kommt an: Legen Sie einen Lichtleiter zur Maschine – von einem Strahlempfänger oder einem Prismenausgang. Zwischen anliegenden Maschinen fließt kein Licht. Ist ein Lichtleiter da, hat sein Netz keine Quelle, oder andere Maschinen nehmen alles Licht: meist ein Prisma mit freien Ausgängen.`,"status.prism.3":`Abnehmer sind satt – Licht wartet`,"status.mixer.3":`Licht kann nirgends hin`,"hint.mixer.3":`Schließen Sie einen Lichtleiter an den Ausgang an (ein Lichtleiter versorgt mehrere Maschinen) oder setzen Sie eine Maschine mit dem Eingang direkt an den Ausgang.`,"status.focuser.3":`Licht kann nirgends hin`,"hint.focuser.3":`Schließen Sie einen Lichtleiter an den Ausgang an (ein Lichtleiter versorgt mehrere Maschinen) oder setzen Sie eine Maschine mit dem Eingang direkt an den Ausgang.`,"status.receiver.3":`Licht kann nirgends hin`,"hint.receiver.3":`Schließen Sie einen Lichtleiter an den Ausgang an (ein Lichtleiter versorgt mehrere Maschinen) oder setzen Sie eine Maschine mit dem Eingang direkt an den Ausgang.`,"status.modulator.3":`Licht kann nirgends hin`,"hint.modulator.3":`Schließen Sie einen Lichtleiter an den Ausgang an (ein Lichtleiter versorgt mehrere Maschinen) oder setzen Sie eine Maschine mit dem Eingang direkt an den Ausgang.`,"status.polarizer.3":`Licht kann nirgends hin`,"hint.polarizer.3":`Schließen Sie einen Lichtleiter an den Ausgang an (ein Lichtleiter versorgt mehrere Maschinen) oder setzen Sie eine Maschine mit dem Eingang direkt an den Ausgang.`,"status.phaser.3":`Licht kann nirgends hin`,"hint.phaser.3":`Schließen Sie einen Lichtleiter an den Ausgang an (ein Lichtleiter versorgt mehrere Maschinen) oder setzen Sie eine Maschine mit dem Eingang direkt an den Ausgang.`,"status.interferometer.3":`Licht kann nirgends hin`,"hint.interferometer.3":`Schließen Sie einen Lichtleiter an den Ausgang an (ein Lichtleiter versorgt mehrere Maschinen) oder setzen Sie eine Maschine mit dem Eingang direkt an den Ausgang.`,"status.light_cell.3":`Licht kann nirgends hin`,"hint.light_cell.3":`Schließen Sie einen Lichtleiter an den Ausgang an (ein Lichtleiter versorgt mehrere Maschinen) oder setzen Sie eine Maschine mit dem Eingang direkt an den Ausgang.`,"status.port.3":`Licht kann nirgends hin`,"hint.port.3":`Schließen Sie einen Lichtleiter an den Ausgang an (ein Lichtleiter versorgt mehrere Maschinen) oder setzen Sie eine Maschine mit dem Eingang direkt an den Ausgang.`,"hud.glareFrom":`{name} – {v} ph/s`,"lab.choose":`Technologie wählen`,"machine.inflowOnly":`Zufluss {n} ph/s`,"machine.bufferFull":`Lichtpuffer voll – wartet auf Abnahme`,"inv.toHand":`In die Hand – platzieren`,"toast.firstCrack":`Meteorit zerschlagen! Fliegen Sie durch die Splitter – das Eis sammelt sich von selbst (oder {touch, select, yes {tippen Sie auf einen Splitter} other {klicken Sie auf einen Splitter}}).`,"machine.spearMeteor":`Kein Schwarm in der Nähe – zerschlägt Meteoriten im Umkreis von {r} Feldern (alle {every} s). In dieser Partie zerschlagen: {n}`,"card.fromBelt":`Asteroidengürtel: der Strahl des Kutters ({touch, select, yes {Brocken antippen} other {Brocken anklicken}}) oder eine Harpune am Band des Gürtels.`,"card.fromTrawl":`Feiner Gürtel: Schleppnetz am Gürtelband.`,"place.why.planet":`Planetenbahn – hier zieht er vorbei`,"status.29":`Planet zu weit`,"status.29.hint":`Der Planet ist außerhalb des Fensters des Massebeschleunigers – warten Sie, bis er näher kommt, oder nutzen Sie Shuttles. Das Fenster ist der leuchtende Bahnbogen.`,"status.30":`Keine Station`,"status.30.hint":`Setzen Sie zuerst eine Orbitalstation auf den Planeten – per Wurf des Wardens oder per Rakete von einer Startrampe.`,"status.31":`Planet ist voll`,"status.31.hint":`Alle Plätze des Planeten sind belegt (oder Station und Beschleuniger stehen schon dort). Wählen Sie einen anderen Planeten.`,"status.32":`Planet wählen`,"status.32.hint":`Wählen Sie im Maschinenfenster einen erkundeten Planeten. Neue erkundet ein Observatorium oder ein Vorbeiflug des Wardens.`,"status.33":`Falscher Planet`,"status.33.hint":`Landebohrer kommen auf feste Planeten, Siphons auf Planeten mit Atmosphäre; der Massebeschleuniger wird nur per Rakete gesetzt.`,"status.34":`Kein Massebeschleuniger`,"status.34.hint":`Schießen Sie einen Massebeschleuniger per Rakete von einer Startrampe auf den Planeten.`,"bonus.planet":`+{v} % Tempo von Landebohrern und Siphons`,"bonus.shuttle":`+{v} % Shuttletempo und -fracht`,"bonus.driver":`+{v} % Fenster des Massebeschleunigers`,"branch.planets":`Planeten`,"planets.title":`Planeten`,"planets.empty":`Dieser Stern hat keine Planeten.`,"planet.unknown":`Unerkundet`,"planet.hours":`{h} Std. {m} Min.`,"planet.min":`{n} Min.`,"planet.cells":`{n} Felder`,"planet.orbit":`Umlaufbahn`,"planet.orbitVal":`{r} Felder · Umlauf {time}`,"planet.dist":`Bis zum Warden`,"planet.atmo":`Atmosphäre`,"planet.atmo.thick":`dicht`,"planet.atmo.thin":`dünn`,"planet.atmo.trace":`Spuren`,"planet.none":`keine`,"planet.rings":`Ringe`,"planet.ring.ice":`aus Eis`,"planet.ring.rock":`aus Gestein`,"planet.moons":`Monde`,"planet.stock":`Vorrat`,"planet.kind.lava":`Lavawelt`,"planet.kind.rocky":`Gesteinswelt`,"planet.kind.desert":`Wüstenwelt`,"planet.kind.crystal":`Kristallwelt`,"planet.kind.ocean":`Ozeanwelt`,"planet.kind.cloud":`Wolkenwelt`,"planet.kind.ice":`Eiswelt`,"planet.kind.ice_giant":`Eisriese`,"planet.kind.gas_giant":`Gasriese`,"planet.special.tidal":`von Gezeiten zerrissen`,"planet.special.aurora":`Polarlicht`,"planet.unsurveyed":`Unerkundet: Fliegen Sie bis auf {survey} Felder heran oder bauen Sie ein Observatorium.`,"planet.slots":`Plätze`,"planet.slotFree":`frei`,"planet.mod.1":`Orbitalstation`,"planet.mod.2":`Landebohrer`,"planet.mod.3":`Atmosphärensiphon`,"planet.mod.4":`Massebeschleuniger`,"planet.store":`Stationslager`,"planet.needStation":`Module brauchen eine Station – zuerst die Station absetzen.`,"planet.window":`Fenster des Massebeschleunigers in {time}`,"planet.fly":`Hinfliegen`,"planet.here":`In der Nähe`,"planet.take":`{n} nehmen`,"planet.throw.hint":`Der Warden wirft ein Modul aus {reach} Feldern Abstand vom Planetenrand`,"planet.throw.station":`Station`,"planet.throw.lander":`Bohrer`,"planet.throw.siphon":`Siphon`,"planet.why.far":`Näher heranfliegen – bis {reach} Felder vom Rand`,"planet.why.none":`Nicht im Inventar – herstellen`,"planet.why.locked":`Zuerst die Technologie erforschen`,"planet.why.full":`Alle Plätze des Planeten sind belegt`,"planet.why.station":`Hier steht schon eine Station`,"planet.why.noStation":`Zuerst die Station`,"planet.why.wrong":`Nicht für diesen Planeten`,"planet.how.tektite":`Tektit: eine Station plus Landebohrer. Per Shuttle holen oder mit einem Massebeschleuniger auffangen.`,"planet.how.neon":`Neon: eine Station plus Siphons. Per Shuttle holen oder mit einem Massebeschleuniger auffangen.`,"planet.how.ice":`Eis: eine Station plus Landebohrer – ein Eisvorrat für eine Megabasis.`,"cfg.title.launch_pad":`Startziel`,"cfg.title.shuttle_port":`Shuttleziel`,"cfg.title.catcher":`Planet des Beschleunigers`,"cfg.title.neon_emitter":`Lichtfarbe`,"cfg.neon_emitter.0":`Rot`,"cfg.neon_emitter.1":`Smaragd`,"cfg.neon_emitter.2":`Azur`,"cfg.planetAuto":`Auto`,"cfg.planetNone":`Keiner`,"shuttle.home":`Shuttles daheim: {n} · unterwegs: {f}`,"shuttle.put":`Shuttles einlegen`,"observatory.target":`Erkundung: {name} – {n} %`,"observatory.done":`Alle Planeten erkundet`,"goal.planet_seen":`Einen Planeten erkunden`,"goal.planet_seen.why":`Die Schläfer und die neuntausend Menschen des „Exodus“ brauchen Boden, und die Wiege hat eigene Welten. Planeten bieten, was die Gürtel nicht haben: Tektit und Neon.`,"goal.planet_seen.hint":`{touch, select, yes {Tippen Sie auf den Pfeil} other {Klicken Sie auf den Pfeil}} – Ihr Kutter fliegt zum nächsten Planeten. Innerhalb von {survey} Feldern wird er automatisch erkundet; oder bauen Sie ein Observatorium.`,"goal.planet_seen.done":`Planet erkundet: Typ, Rohstoff und Plätze stehen in seiner Karte.`,"goal.planet_seen.part":`Einen Planeten erkunden`,"goal.planet_landing":`Landung: eine Station und ein Landebohrer`,"goal.planet_landing.why":`Eine Orbitalstation ist der erste Anlegeplatz der Kolonie an lebendigem Boden. Der Bohrer fördert Tektit in ihr Lager.`,"goal.planet_landing.hint":`Fertigen Sie eine Station und einen Landebohrer, fliegen Sie zu einem festen Planeten (Gestein, Lava, Wüste, Kristall), {touch, select, yes {tippen Sie darauf} other {klicken Sie darauf}} – „Station“, dann „Bohrer“.`,"goal.planet_landing.done":`Erste Landung! Das Stationslager füllt sich.`,"goal.planet_landing.part":`Station platzieren`,"goal.planet_landing.part.2":`Landebohrer platzieren`,"goal.planet_tektite":`Tektitglas: {n, plural, one {# Stück} other {# Stück}}`,"goal.planet_tektite.why":`Tektitglas ist Optik höherer Stufen: Röhren, Shuttles, der Fänger. Ohne es bleibt das Tor unerreichbar.`,"goal.planet_tektite.hint":`Holen Sie Tektit von der Station („Nehmen“ in der Planetenkarte), bringen Sie es zur Basis und schmelzen Sie es in einem Tektitofen unter rotem Licht.`,"goal.planet_tektite.done":`Glas von einem Planeten! Das Erste, was wir aus echtem Boden gemacht haben. Im Hafen gibt es Boden nur auf Bildern.`,"goal.planet_shuttle":`Erster Shuttleflug`,"goal.planet_shuttle.why":`Shuttles bringen Fracht von den Planetenstationen selbstständig zur Basis – keine Flüge von Hand mehr.`,"goal.planet_shuttle.hint":`Bauen Sie einen Shuttlehafen, führen Sie Licht heran ({charge} ph pro Start), legen Sie Shuttles ein und wählen Sie einen Planeten oder „Auto“. Die Fracht landet in den Plätzen des Hafens – holen Sie sie mit Greifern.`,"goal.planet_shuttle.done":`Das Shuttle ist mit Fracht zurück.`,"goal.planet_shuttle.part":`Ein Shuttle hat Fracht geliefert`,"goal.planet_neon":`Neon: ein Siphon und {n} Flüssigneon`,"goal.planet_neon.why":`Neon ist Licht ohne Stern. Es wird dort gebraucht, wo kein Stern hilft – und für die Röhren von Spektrum O, dem letzten Schlüssel des Tors.`,"goal.planet_neon.hint":`Setzen Sie eine Station und einen Siphon auf einen Planeten mit Atmosphäre (Riese, Wolken, Ozean). Neon plus Eis kommt in einen Neonkondensator unter blauem Licht.`,"goal.planet_neon.done":`Neon leuchtet von selbst, ganz ohne Stern! Als hätte jemand für die Nacht ein Licht angelassen – für uns.`,"goal.planet_neon.part":`Siphon platzieren`,"goal.planet_neon.part.2":`{n} Flüssigneon erzeugen`,"goal.planet_light":`Eigenes Licht: ein Neonstrahler`,"goal.planet_light.why":`{flux} ph/s einer beliebigen Grundfarbe ohne Stern – überall dort, wo sein Licht nicht hinreicht.`,"goal.planet_light.hint":`Bauen Sie einen Neonstrahler, führen Sie flüssiges Neon per Rohr zu und wählen Sie eine Farbe; der Lichtleiter geht von seiner Vorderseite ab.`,"goal.planet_light.done":`Der Strahler leuchtet.`,"goal.planet_light.part":`Der Strahler leuchtet`,"planet.windowOpen":`Der Planet ist im Fenster des Massebeschleunigers – Kapseln fliegen`,"planet.sec":`{n} s`,"guide.doneTitle":`Geschafft!`,"guide.next":`Weiter`,"guide.min":`Hinweis einklappen`,"guide.restore":`Tutorial {n}/{total} – zeigen`,"guide.intro":`Vierzig Kolonisten schlafen im Wohnmodul mit Notstrom. Sternenlicht wird sie retten, und die Maschinen dafür baut man aus Gestein. Beginnen wir mit Gestein.`,"guide.fly.done":`Wir sind da. Die blauen Brocken sind Quarz. Mit ihm beginnt alles.`,"guide.mine.done":`Quarz im Frachtraum: {n}. Behalten Sie ihn – Sie brauchen ihn für Gravobänder.`,"guide.star-light":`Alles hier läuft mit Sternenlicht. Bögen fangen es – sie kommen auf den leuchtenden gestrichelten Ring um den Stern.`,"guide.place-arc.done":`Das Licht fließt: {arc} ph/s. Der Bogen hat seinen ersten Anteil am Stern gefangen.`,"guide.place-receiver.done":`Der Strahl ist da: {arc} ph/s im Empfänger.`,"guide.place-grinder.done":`Sie steht. Aber dunkel: kein Rezept, kein Licht.`,"guide.recipe.done":`Das Rezept steht. Jetzt fehlt nur Licht.`,"guide.lay-lights.touch":`Nehmen Sie einen Lichtleiter und ziehen Sie mit dem Finger entlang des Rahmens vom Empfänger zur Schleiferei.`,"guide.lay-lights.why":`Ein Lichtleiter ist ein Kabel für Licht. Ohne Licht stehen die Maschinen still – und die Schläfer warten.`,"guide.lay-lights.stuck":`Leuchtet nicht? Der Lichtleiter muss Schüssel und Schleiferei berühren – füllen Sie den ganzen Rahmen.`,"guide.lay-lights.done":`Die Schleiferei leuchtet! Jetzt fehlt nur noch Quarz.`,"guide.place-harpoonA.done":`Treffer! Das Seil hält einen Brocken. Angeln, Warden.`,"guide.place-harpoonB.why":`Eine Harpune reicht nicht für eine Schleiferei. Eine zweite – genau richtig.`,"guide.place-harpoonB.done":`Die zweite Harpune steht – die Schleiferei hat genug Gestein.`,"guide.lay-tunnel.stuck":`Keine Gravobänder mehr? Fertigen Sie weitere im „Inventar“. Ziehen Sie von einem Ende des Rahmens zum anderen.`,"guide.lay-tunnel.done":`Da fließt der Quarz. Schön anzusehen.`,"guide.place-grabIn.done":`Quarz in der Schleiferei – sie schleift!`,"guide.place-grabOut.done":`Der Greifer wartet auf einen Platz für die Linse.`,"guide.place-storage.done":`Die Linie steht: Gürtel → Gravoband → Schleiferei → Kiste. Die erste Kette in diesem System.`,"guide.first-lens.stuck":`Noch keine Linse? Drücken Sie auf die Schleiferei oder den Greifer mit Symbol: Das Fenster sagt, was fehlt.`,"guide.first-lens.done":`Das erste Erzeugnis in diesem System – von Maschinen, ohne Ihre Hände.`,"guide.glint":`Das Zentrum schaltet neue Maschinen gegen Forschung frei. Die erste Forschung ist Schimmer: Eine Schleiferei stellt ihn her.`,"guide.research-pick":`Suchen Sie „Prisma“ und drücken Sie „Einreihen“.`,"guide.research-pick.reopen":`Öffnen Sie das Zentrum erneut – wählen wir die erste Forschung.`,"guide.research-pick.why":`Das Prisma zerlegt das weiße Licht des Sterns in Farben. Mit Farben beginnt alles Weitere.`,"guide.research-pick.done":`Das Prisma ist eingereiht. Das Zentrum braucht {n} Schimmer – das Ziel zeigt, wie.`,"goal.mark.resource":`HIER ABBAUEN`,"goal.mark.harvest":`HARPUNE HIERHER`,"goal.mark.meteor":`{touch, select, yes {TIPPEN} other {KLICKEN}} ZUM ZERSCHLAGEN`,"goal.mark.lab":`ZENTRUM`,"goal.mark.star":`BÖGEN AUF DIE BAHN`,"goal.mark.protostar":`PROTOSTERN`,"goal.mark.ghost":`BAUGEIST`,"goal.mark.node":`SCHWARMNEST`,"goal.mark.farBelt":`NEUER GÜRTEL – HARPUNE HIERHER`,"goal.mark.forge":`STERNSCHMIEDE`,"goal.mark.planet":`PLANET`,"goal.mine.mark":`{touch, select, yes {TIPPEN} other {KLICKEN}} ZUM ABBAUEN`,"goal.expand.mark":`PLATTEN-SCHLEIFEREI HIERHER`,"goal.mark.lineGrinder":`SCHLEIFEREI HIERHER`,"goal.obsidian.mark":`HARPUNE – AUSGANG IN DIE SCHLEIFEREI`,"goal.plates.mark":`NOCH EINE HARPUNE – IN DIE SCHLEIFEREI`,"ship.title":`Schiff`,"ship.hull.1":`„Pfeil“`,"ship.hull.2":`„Wespe“`,"ship.hull.3":`„Falke“`,"ship.fire.title":`Automatisches Feuer auf Gefahren und Meteoriten in Waffenreichweite`,"ship.fire.on":`Feuer: auto`,"ship.fire.off":`Feuer: aus`,"ship.slots":`Schiffsplätze`,"ship.empty":`leer`,"ship.filter":`Worauf feuern`,"ship.filter.auto":`Alles`,"ship.filter.big":`Nur Großes`,"ship.filter.tap":`Ausgewählte`,"ship.ammo":`{name}: {n} im Frachtraum, {m} geladen`,"ship.none":`Keine passenden Module im Inventar – fertigen Sie sie von Hand oder im Montierer.`,"ship.unequip":`Modul abnehmen`,"ship.hint":`{touch, select, yes {Tippen Sie auf einen Sockel} other {Klicken Sie auf einen Sockel}} oder eine Nummer am Modell, um ein Modul einzusetzen oder zu tauschen.`,"ship.energy":`Energie`,"ship.energy.short":`zu wenig Energie: Waffen fallen aus`,"ship.energy.aria":`Schiffsenergie {n} %`,"ship.overload":`Überlast`,"ship.stat.speed":`Tempo`,"ship.stat.shield":`Schild`,"ship.stat.regen":`Aufladung`,"ship.stat.output":`Leistung E/s`,"ship.stat.drain":`Verbrauch E/s`,"ship.stat.battery":`Batterie`,"ship.stat.dps":`Schaden/s`,"ship.stat.reach":`Abbaureichweite`,"ship.stat.collect":`Splitter sammeln`,"hail.warn":`Gesteinshagel in {s} s · {n} Brocken`,"achv.ship_first_shot.name":`Erster Schuss`,"achv.ship_first_shot.desc":`Zerschießen Sie einen Meteoriten oder Brocken mit einer Schiffswaffe.`,"achv.ship_mark_2.name":`Mk II`,"achv.ship_mark_2.desc":`Rüsten Sie das Schiff mit einem Modul Mk II aus.`,"achv.ship_leviathan.name":`Flaggschiff`,"achv.ship_leviathan.desc":`Erforschen Sie den Rumpf „Zenit“ – die Spitze der Schiffsreihe.`,"achv.ship_hail_50.name":`Steinschild`,"achv.ship_hail_50.desc":`Schießen Sie mit Schiffswaffen {n} Hagelbrocken ab.`,"achv.ship_swarms_10.name":`Schrecken des Schwarms`,"achv.ship_swarms_10.desc":`Vernichten Sie {n} Aliens des Schwarms.`,"ship.tasks":`Schiffsaufgaben`,"ship.task.module":`Eine Waffe einbauen`,"ship.task.shot":`Einen Meteoriten mit einer Waffe zerschießen`,"ship.task.ammo":`Ein Montierer hat {n} Patronengurte hergestellt`,"ship.task.mark":`Ein Modul Mk II`,"ship.task.hail":`{n} Hagelbrocken abschießen`,"guide.ship-open":`Neu: das Fenster „Schiff“ – die Module Ihres Kutters: Energie, Schild, Waffen.`,"guide.ship-open.why":`Der Kutter wächst mit der Basis: Jedes Modul ist neue Stärke. Bei der Hardware helfe ich.`,"guide.ship-open.more":`Das Fenster „Schiff“ ist im Menü „Mehr“.`,"guide.ship-craft":`Fertigen Sie einen Pulslaser – stärker als der serienmäßige: Platten, Azurlinsen und ein Resonator.`,"guide.ship-craft.stuck":`Keine Azurlinsen? Die Optikbank macht sie aus Linsen unter azurblauem Licht.`,"guide.ship-weapon":`{touch, select, yes {Tippen Sie auf den Waffensockel} other {Klicken Sie auf den Waffensockel}} – Nummer 6 – und setzen Sie den Laser ein.`,"guide.ship-weapon.why":`Die Waffe feuert von selbst – auf Meteoriten und auf alles, was sonst angekrochen kommt.`,"guide.ship-weapon.reopen":`Öffnen Sie das Fenster „Schiff“ erneut.`,"guide.ship-shot":`Der Laser feuert von selbst – auf Meteoriten und auf den Schwarm nahe am Schiff. Die Energie ist der Balken unter dem Schild.`,"guide.ship-shot.done":`Treffer! Fliegen Sie durch die Splitter, um sie einzusammeln. Der Laser kann auch ein Schwarmnest nehmen – aber Wächter schützen es.`,"flare.warn":`Der Stern flammt auf: Ausbruch in {s} s – weg von der Korona`,"flare.now":`Sternenausbruch! Die Korona ist noch {s} s doppelt so breit`,"swarm.title":`Schwarm`,"swarm.calm":`Betrachtung: In dieser Welt gibt es keinen Schwarm.`,"swarm.gate":`Der Schwarm lebt ab der ersten Minute. Die Augen eines Nests zeigen, ob es das Streulicht Ihrer Basis sieht.`,"swarm.evo":`Evolution {e} ‰`,"swarm.nests":`Nester in der Nähe: {n} ({a} erwacht)`,"swarm.cleared":`Geräumte Nester: {n}`,"swarm.hives":`Planeten unter Brutstöcken: {n} · befreit {f}`,"swarm.repelled":`Abgewehrte Wellen: {n} von {m}`,"swarm.repaired":`Repariert: {n} Pkt. · derzeit beschädigt {d}`,"swarm.wave.soon":`Welle in {t} · {n} Aliens`,"swarm.wave.now":`Welle greift an · noch {n}`,"swarm.advice":`Panzer {c}: Speere und Strahlen mit Licht dieser Farbe treffen ×{match, number}, Weiß ×{white}, andere ×{other, number}.`,"swarm.hue.r":`Rot`,"swarm.hue.g":`Smaragd`,"swarm.hue.b":`Azur`,"swarm.showTarget":`Ziel zeigen`,"swarm.showNest":`Nächstes Nest`,"swarm.repairNext":`Nächsten Bau reparieren ({n})`,"swarm.quiet":`Keine Wellen. Ein Radar zeigt die nächste früher.`,"swarm.quietRadar":`Keine Wellen – das Radar wacht.`,"swarm.hint":`Streulicht breitet sich von Ihrer Basis aus; Nester sehen es, saugen es auf und ziehen daraus Angriffstrupps heran. Die Evolution wächst mit Streulicht, neuen Spektralstufen und befreiten Planeten – nicht mit der Zeit. Weniger Lecks, weniger Wellen; stellen Sie Geschütze und Barrieren an Ihre hellsten Maschinen.`,"hud.swarm.incoming":`Welle {t} · {n}`,"hud.swarm.fight":`Schwarm · noch {n}`,"hud.swarm.awake":`Schwarm · {n} · {e} ‰`,"swarm.toast.woke":`Ein Schwarmnest ist erwacht: Ihr Streulicht hat es erreicht. Beseitigen Sie das Streulicht – und das Nest schläft wieder ein.`,"swarm.toast.wave":`Der Schwarm kommt: Welle in {t} s, {n} Aliens. Der Pfeil zeigt, woher.`,"swarm.toast.go":`Die Welle ist gestartet!`,"swarm.toast.repelled":`Welle abgewehrt! {k} abgeschossen, {d} Schaden an der Basis.`,"swarm.toast.left":`Die Welle ist abgezogen, {d} Schaden an der Basis. Reparieren Sie, was beschädigt ist.`,"swarm.toast.nest":`Nest geräumt: Die Königin ist tot, ein Protostern leuchtet auf. +{chitin} Chitin.`,"machine.hp":`Haltbarkeit {n} / {m}`,"machine.wreck":`Wrack – arbeitet nicht. Reparieren oder abreißen (die Maschine kommt zurück).`,"machine.repair":`Reparieren`,"machine.ammo":`Munition: {n} von {m} Schuss`,"machine.kits":`Reparaturvorrat: {n} von {m} Pkt.`,"machine.dome":`Schild: {n}`,"machine.def.turret":`Schaden {dmg} · {rate} pro s · Reichweite {r} Felder`,"machine.def.barrier":`Ein Alien im Weg zernagt die Barriere, nicht die Maschinen dahinter.`,"machine.def.dome":`Fängt Treffer auf Maschinen im Umkreis von {r} F. ab, Schild bis {cap}.`,"machine.def.radar":`Wellen sind {warn} s früher sichtbar.`,"machine.def.decoy":`Lenkt eine Welle auf sich, wenn sie höchstens {reach} F. vom Ziel entfernt ist.`,"machine.def.bay":`Repariert {heal} Pkt./s im Umkreis von {r} F. aus Reparatursets.`,"alien.spark.name":`Funke`,"alien.reaper.name":`Schnitter`,"alien.stinger.name":`Stachel`,"alien.ram.name":`Rammer`,"status.35":`Beschädigt`,"status.35.hint":`Haltbarkeit unter der Hälfte – die Maschine sprüht Funken. Reparieren Sie sie: „Reparieren“ im Maschinenfenster oder eine Reparaturstation.`,"status.36":`Wrack`,"status.36.hint":`Der Schwarm hat diese Maschine zerstört. Reparieren Sie sie (mit Reparatursets schneller) oder reißen Sie sie ab: Die Maschine kommt zurück.`,"status.37":`Keine Munition`,"status.37.hint":`Führen Sie Patronengurte (oder Reparatursets für eine Station) per Greifer, Gravoband oder von Hand zu.`,"status.38":`Braucht Phase π`,"status.38.hint":`Der Phasenspeer nimmt nur Licht mit Phase π: Leiten Sie den Strahl durch einen Phasenschieber.`,"status.39":`Planet unter Brutstock`,"status.39.hint":`Der Schwarm hält diesen Planeten: Der Abbau steht. Befreien Sie ihn mit dem Schiff oder Orbitalgeschützen.`,"achv.first_wave.name":`Erste Welle`,"achv.first_wave.desc":`Wehren Sie eine Welle des Schwarms ab.`,"achv.repairman.name":`Reparaturdienst`,"achv.repairman.desc":`Reparieren Sie {n, number} Punkte Haltbarkeit.`,"achv.nest_breaker.name":`Nestbrecher`,"achv.nest_breaker.desc":`Räumen Sie {n} Schwarmnester.`,"achv.liberator.name":`Befreiung`,"achv.liberator.desc":`Befreien Sie einen Planeten von einem Brutstock des Schwarms.`,"achv.fortress.name":`Festung`,"achv.fortress.desc":`Wehren Sie {n} Wellen des Schwarms ab.`,"swarm.tasks":`Verteidigungsaufgaben`,"swarm.task.turret":`Ein Geschütz bauen (Speer oder MG)`,"swarm.task.wave":`Eine Welle abwehren`,"swarm.task.repair":`{n} Pkt. Haltbarkeit reparieren`,"swarm.task.barrier":`{n} Barrieren bauen`,"swarm.task.bay":`Eine Reparaturstation`,"swarm.task.nest":`Ein Nest räumen`,"swarm.task.planet":`Einen Planeten von einem Brutstock befreien`,"guide.swarm-hud":`Ein Schwarmnest – heimische Wesen aus Chitin und Licht – hat das Streulicht der Basis bemerkt und einen Trupp geschickt. Die Anzeige oben zeigt, wie viele, woher und wohin. {touch, select, yes {Tippen Sie darauf} other {Klicken Sie darauf}}, und die Kamera zeigt das Ziel.`,"guide.swarm-hud.why":`Streulicht ist Licht, das die Basis verschüttet. Das lockt sie an – das hellste Licht – und sie beißen in Bauten.`,"guide.swarm-turret":`Setzen Sie einen Speer oder ein MG-Geschütz nahe an das Ziel der Welle und geben Sie ihm Licht oder Munition (Greifer, Gravoband oder von Hand).`,"guide.swarm-turret.why":`Ein Geschütz feuert, während Sie bauen. Ob jedes nötig ist – darüber reden wir später.`,"guide.swarm-turret.stuck":`Der Speer steht unter „Verteidigung“, das MG-Geschütz kommt später. Ihr Schiff hilft auch: Seine Waffen feuern von selbst.`,"guide.swarm-wave":`Der Schwarm beißt in Bauten. Fliegen Sie mit dem Kutter hin – der Laser feuert von selbst; Geschütze helfen.`,"guide.swarm-wave.done":`Die Welle ist abgezogen. Die Bilanz steht oben.`,"guide.swarm-repair":`Beschädigte Maschinen sprühen Funken, zerstörte werden zu Wracks. Öffnen Sie eine Maschine und drücken Sie „Reparieren“ – der Strahl des Kutters repariert alles in der Nähe.`,"guide.swarm-repair.why":`Nichts geht verloren: Ein Wrack lässt sich wieder zur ganzen Maschine reparieren. Mit Reparatursets geht es viermal schneller.`,"goal.gate_core":`Den Torkern in den uralten Ring hinter dem äußeren Gürtel setzen`,"goal.gate_core.why":`Der dunkle Ring hinter dem äußeren Gürtel ist ein uraltes Tor. Der Kern kommt in seine Fassungen – und der Ring erwacht.`,"goal.gate_core.hint":`Erforschen Sie „Tortheorie“ (Spektrum B). Ein Montierer baut den Kern; er passt nur auf die Ruinen – die Markierung zeigt, wo.`,"goal.gate_core.done":`Der Kern sitzt – die Fugen der Ruine passen.`,"goal.gate_core.part":`Kern auf die Plattform des Rings setzen`,"goal.gate_core.mark":`TORKERN – HIERHER`,"goal.gate_ring":`Den Ring schließen: {n, plural, one {# Segment} other {# Segmente}} in den Kern`,"goal.gate_ring.why":`Jedes Segment ist ein Schritt auf dem Weg nach Hause: Der Ring der Schmiede erwacht Segment für Segment, sichtbar bei jedem Zoom.`,"goal.gate_ring.hint":`Segmente baut ein Montierer: Bögen III, Resonatoren, Spektren B und Torwellenleiter (ein Wellenleiter: zwei Azurlinsen, ein Resonator und Tektitglas unter weißem polarisiertem Licht). Bringen Sie sie per Greifer oder mit „Segmente einsetzen“ in den Kern. Ein Filtergreifer nimmt von einem gemeinsamen Gravoband nur seinen eigenen Gegenstand.`,"goal.gate_ring.done":`Der Ring ist geschlossen!`,"goal.gate_ring.part":`Segmente im Kern`,"goal.gate_field":`Das Feld halten: {n, plural, one {# Stabilisator} other {# Stabilisatoren}} mit verschiedenen Eigenschaften`,"goal.gate_field.why":`Der Ring öffnet sich nur mit Zustimmung: Das Feld wird von Licht aller Eigenschaften zugleich gehalten – eine Prüfung in allem, was Sie über die Sprache der Gärtner gelernt haben.`,"goal.gate_field.hint":`Erforschen Sie „Feldstabilisierung“. Platzieren Sie Stabilisatoren höchstens {range} Felder vom Kern entfernt; wählen Sie in ihrem Fenster eine Eigenschaft: Rot, Polarisation, Rhythmus, Phase π. Jeder braucht {flux} ph/s dieses Lichts.`,"goal.gate_field.done":`Das Feld hält!`,"goal.gate_field.part":`Leuchtende Eigenschaften`,"goal.gate_charge":`{n, plural, one {# Feldspeicher} other {# Feldspeicher}} laden`,"goal.gate_charge.why":`Der Sprung braucht alles Licht, das die Sphäre fängt. Hinter dem Ring wartet der „Exodus“ – an einem sterbenden Stern, mit Hungerrationen.`,"goal.gate_charge.hint":`Erforschen Sie „Feldspeicher“ (erfordert „Schale IV“). Platzieren Sie sie am Kern; jeder braucht {flux, number} ph/s, unter {low} ph/s laden sie nicht. Voll in {full} Minuten.`,"goal.gate_charge.done":`Die Speicher sind randvoll. Vierzig Jahre habe ich repariert, was erlischt. Zum ersten Mal lade ich etwas, das aufleuchten wird.`,"goal.gate_charge.part":`Volle Feldspeicher`,"goal.gate_key":`Den Schlüssel einsetzen: je {each, plural, one {# Spektrum} other {# Spektren}} jeder Klasse`,"goal.gate_key.why":`Der Torschlüssel ist je ein Spektrum jeder Klasse von M bis O: alles, was Sie an der Wiege gelesen haben, in einem Strahl. Der Ring wird ihn erkennen und den Weg öffnen.`,"goal.gate_key.hint":`Bringen Sie je {each} Spektren M, K, G, F, A, B und O zum Kern: per Greifer oder mit „Spektren aus dem Inventar einsetzen“ im Fenster des Kerns. Ein Stapelgreifer trägt einen ganzen Stapel, ein Lichtgreifer an einem Pylon ist doppelt so schnell.`,"goal.gate_key.done":`Der Schlüssel ist drin! Opa, hast du das gesehen? Der Ring leuchtet in all unseren Farben.`,"goal.gate_key.part":`Schlüsselspektren`,"goal.gate_jump":`Das Tor aktivieren und heimspringen`,"goal.gate_jump.why":`Zwei Millionen Menschen warten an einem trüben Herdfeuer. Das Tor öffnet ihnen den Weg zu einem lebenden Stern – wenn die Gärtner „ja“ sagen.`,"goal.gate_jump.hint":`Im Fenster des Kerns – „Aktivieren“. Das Hochfahren dauert {spin} Minuten: Die Stabilisatoren müssen leuchten, und die Basis überzieht den Himmel mit Streulicht – bereiten Sie die Verteidigung vor.`,"goal.gate_jump.done":`Sprung!`,"goal.gate_jump.part":`Sprung`,"logbook.title":`Logbuch`,"logbook.tab.story":`Geschichte`,"logbook.tab.logs":`Weras Logs`,"logbook.tab.cast":`Figuren`,"logbook.none":`Diese Welt hat keine Kampagne: Die Geschichte spielt in einer neuen Welt der Wiege.`,"logbook.empty":`Noch leer. Hier erscheinen Szenen und Dialoge – Sie können sie erneut ansehen.`,"logbook.logs":`Gefundene Einträge von Wera: {n} von {total}. Kapseln leuchten blau – fliegen Sie ganz nah heran.`,"logbook.found":`Weras Eintrag Nr. {n} gefunden – im „Logbuch“`,"story.skip":`Überspringen`,"story.credits.minutes":`Minuten in der Wiege`,"story.credits.arcs":`Bögen der Sphäre`,"story.credits.logs":`Einträge von Wera`,"story.credits.nests":`eingeschlafene Nester`,"story.credits.thanks":`Danke, dass Sie den ganzen Weg geflogen sind.`,"settings.story":`Geschichte`,"settings.story.full":`Vollständig`,"settings.story.radio":`Nur Funk`,"settings.story.off":`Ohne Dialoge`,"gate.title":`Hypertor`,"gate.segments":`Ring: {n} von {need} Segmenten`,"gate.key":`Schlüssel des vollen Spektrums`,"gate.field":`Feld: {n} von {total} Eigenschaften`,"gate.charge":`Feldspeicher: {n} von {total} voll`,"gate.prop.0":`Rot`,"gate.prop.1":`Polarisation`,"gate.prop.2":`Rhythmus`,"gate.prop.3":`Phase π`,"gate.activate":`Aktivieren`,"gate.notReady":`Benötigt: der Ring, der Schlüssel, {field} Feldeigenschaften und {charge} volle Feldspeicher.`,"gate.spinning":`Hochfahren {p} % – Stabilisatoren am Leuchten halten!`,"gate.jumped":`Der Sprung ist vollbracht. Das Tor ist offen.`,"gate.putKey":`Spektren aus dem Inventar einsetzen`,"gate.putSegments":`Segmente einsetzen`,"gate.stab.prop":`Lichteigenschaft`,"gate.stab.range":`{yes, select, yes {Im Feld des Kerns – arbeitet für das Tor} other {Außerhalb des Kernfelds: mehr als {range} Felder von seiner Mitte – kein Beitrag zu Feld und Ladung}}`,"gate.cap.fill":`Ladung {p} %`,"cfg.title.gate_stabilizer":`Lichteigenschaft`,"cfg.gate_stabilizer.0":`Rot`,"cfg.gate_stabilizer.1":`Polarisation`,"cfg.gate_stabilizer.2":`Rhythmus`,"cfg.gate_stabilizer.3":`Phase π`,"guide.ora":`ORA · BORD-KI`,"goal.mark.gate":`HYPERTOR`,"landmark.ruins":`RING DER SCHMIEDE`,"landmark.ruins.sub":`ein uraltes Tor`,"landmark.gate":`HYPERTOR`,"landmark.capsule":`KAPSEL`,"landmark.capsule.sub":`ein alter Eintrag – heranfliegen`,"scene.label":`Szene`,"story.log.title":`Eintrag {n} · Tag {day}`,"story.credits.sleepers":`Und den Schläfern, die das Spannendste verschlafen haben.`,"logbook.tab.world":`Chronik`,"logbook.prologue":`Prolog`,"logbook.scene.prologue":`Die Kehrseite`,"logbook.scene.hab":`Vierzig Lichter`,"logbook.scene.intruder":`Die blinde Passagierin`,"logbook.scene.first_log":`Eintrag in der Kapsel`,"logbook.scene.confess":`Geständnis`,"logbook.scene.chorus":`Die Übersetzung`,"logbook.scene.protostar":`Das erste Nest`,"logbook.scene.refrain":`Das Muster`,"logbook.scene.token":`Die Marke`,"logbook.scene.channel":`Der Kanal`,"logbook.scene.report7":`Bericht Sieben`,"logbook.scene.core":`Der Kern`,"logbook.scene.matvey_nest":`Matwei am Nest`,"logbook.scene.spin":`Anlauf`,"logbook.scene.threshold":`Die Schwelle`,"settings.textSpeed":`Textgeschwindigkeit`,"settings.textSpeed.slow":`Langsam`,"settings.textSpeed.normal":`Normal`,"settings.textSpeed.fast":`Schnell`,"settings.textSpeed.instant":`Sofort`,"chron.1.when":`−260 J.`,"chron.1":`Am Herdfeuer wird das Bruchstück eines uralten Rings gefunden. Nach seinem Vorbild entstehen die ersten Hypertore und die erste Sphäre. Das Lichte Zeitalter beginnt.`,"chron.2.when":`−230 J.`,"chron.2":`Die Halskette: Tore an dreihundert Sternen. Erste Begegnung mit dem Schwarm – „Käfer nagen an der Sphäre“.`,"chron.3.when":`−215 J.`,"chron.3":`Das Sog-Institut ruft die Sanitätskampagne aus. Nester werden ausgebrannt; die Systeme erhalten im Katalog das Etikett „klar“.`,"chron.4.when":`−212 J.`,"chron.4":`Die Expedition „Erstes Licht“ findet einen unbekannten lebendigen Stern – und verschwindet.`,"chron.5.when":`−211 J.`,"chron.5":`Lunds Bericht Sieben erreicht das Institut. Der Stern wird aus dem Katalog getilgt, der Bericht wird geheim.`,"chron.6.when":`−170 J.`,"chron.6":`Die ersten Sterne werden trüber. Das Wort „Erlöschen“ kommt auf – und mit ihm die Theorie vom dunklen Sog.`,"chron.7.when":`−120 J.`,"chron.7":`Die Halskette reißt: Ohne Licht verlöschen die Tore, Hunderte Kolonien gehen verloren.`,"chron.8.when":`−90 J.`,"chron.8":`Die letzten Tore werden geschlossen. Die Menschen sammeln sich am Herdfeuer und bauen den Hafen.`,"chron.9.when":`−45 J.`,"chron.9":`Die letzte Säuberung: das System Klarstern. Im Trupp – der dreiundzwanzigjährige Matwei Rogow.`,"chron.10.when":`−30 J.`,"chron.10":`Die Flotte „Exodus“ – neuntausend Menschen – bricht zum Klarstern auf. Die Route berechnet Mira Went.`,"chron.11.when":`−12 J.`,"chron.11":`Das Programm „Aussaat“: zwölf schnelle Saatschiffe zu lebendigen Sternen.`,"chron.12.when":`−1,5 J.`,"chron.12":`Die „Schwalbe“ bricht zum Klarstern auf. In Kapsel Nr. 17: Sonja Went. Ihre Mutter hat für sie entschieden.`,"chron.13.when":`Tag 547`,"chron.13":`Die Kehrseite. ORA fängt ein Signal auf einer Frequenz, die in keinem Protokoll steht – und ändert den Kurs.`,"guide.lab-place":`Platzieren Sie das Forschungszentrum im Rahmen – es liegt in der Bauleiste.`,"guide.lab-place.repick":`Nehmen Sie das Forschungszentrum aus der Bauleiste.`,"guide.lab-place.why":`Ein Bauplan aus dem Archiv. Das Zentrum liest das Licht des Sterns – und das Archiv gibt neue Baupläne frei. Bauen Sie so viele Zentren, wie Sie möchten.`,"guide.lab-place.done":`Das Zentrum steht. Jetzt braucht es Licht.`,"lab.count":`Zentren: {n} · lesen gerade: {w}`,"lab.none":`Noch keine Zentren. Platzieren Sie ein Forschungszentrum aus der Bauleiste – ohne Zentrum lässt sich keine Wissenschaft lesen.`,"swarm.rules":`Der Schwarm lebt ab der ersten Minute. Die Augen eines Nests: dunkel – es sieht Ihr Streulicht nicht, gelb – es sieht die Basis, rot – es ist erwacht. Zuerst kommen Späher, sie beißen nicht; dann folgen Wellen. Die Stacheln um ein Nest sind seine Grenze: Bauen darin weckt es, und Ihr Kutter scheucht die Wächter auf. Sauberes Licht, ruhiger Schwarm.`,"swarm.toast.scout":`Sie wurden gesehen: Späher des Schwarms kommen nachsehen. Sie beißen nicht – aber eine Welle folgt.`,"swarm.toast.scoutGo":`Die Späher sind unterwegs.`,"swarm.toast.pact":`Der Brutstock ist von selbst gegangen: Das Feuer der Eintracht hat gewirkt. Der Planet ist für immer frei.`,"swarm.scout.soon":`Späher in {t} · {n}`,"swarm.scout.now":`Späher über der Basis · {n}`,"goal.planet_free":`Ihren ersten Planeten befreien`,"goal.planet_free.part":`Befreite Planeten`,"goal.planet_free.why":`Auf jedem Planeten sitzt ein Brutstock der Gärtner. Land für die Menschen muss man nehmen – oder darum bitten.`,"goal.planet_free.hint":`Nehmen: Greifen Sie den Brutstock mit den Waffen des Kutters oder mit Orbitalgeschützen an – schnell, doch der Schwarm antwortet mit einer Welle und kann zurückkehren. Bitten: ein „Feuer der Eintracht“ in den Orbit – solange es um den Planeten sauber bleibt, zieht der Brutstock von selbst ab, für immer. Ein Orbitalgeschütz hält einen befreiten Planeten. Die nahen Brutstöcke sind jung.`,"goal.planet_free.done":`Der Planet ist frei. Die Gärtner haben es gesehen – und sind ein wenig mehr geworden.`,"goal.lab2":`Ein zweites Zentrum und Schimmer ohne Handarbeit`,"goal.lab2.why":`Das Archiv enthält Hunderte Baupläne, und die Zeit der Schläfer ist nicht endlos. Jedes Zentrum liest seine eigene Einheit Wissenschaft: zwei Zentren – doppelt so schnell.`,"goal.lab2.hint":`Bauen Sie ein Forschungszentrum ({plates} Platten, {lenses} Linsen, {res} Resonatoren – von der Resonatorwerkbank) und stellen Sie es direkt neben das erste – Nachbarn teilen sich die Wissenschaft von selbst, doch Licht braucht jedes für sich: Führen Sie einen Lichtleiter zu beiden. Den Schimmer soll eine Linie bringen: Quarzharpune → Schleiferei „Schimmer“ ← Greifer aus einer Plattenkiste; ein Greifer aus der Schleiferei direkt ins Zentrum.`,"goal.lab2.done":`Zwei Zentren lesen gleichzeitig: Das Archiv öffnet sich doppelt so schnell. Ab jetzt – ein Zentrum für jede neue Stufe.`,"landmark.center":`Forschungszentrum`,"landmark.center.sub":`Zentren: {n}`,"track.path":`Pfad`,"track.light":`Licht`,"track.matter":`Materie`,"track.logistics":`Logistik`,"track.defense":`Verteidigung`,"track.sky":`Himmel`,"tree.reqFar":`{tech} ({track}, noch {n, plural, one {# Schritt} other {# Schritte}})`,"settings.handTips":`Tipps zum Bau in der Hand`,"cryo.title":`Kryodeck · {n} von {total}`,"cryo.open":`Kryodeck: {n} von {total}`,"cryo.panels":`Die Notpaneele des Moduls halten alle vierzig Kapseln. Sobald die Krone leuchtet, stellt ORA das Deck auf das Licht der Basis um – dann braucht es Azurlicht (den blauen Ausgang eines Prismas, per kurzem Lichtleiter zum Modul) und Eis.`,"cryo.cold":`Azurlicht für die Schlafenden: {got} von {need} ph/s`,"cryo.dim":`zu schwach – Helligkeit {b} nötig`,"cryo.wrong":`falscher Farbton – Azur nötig`,"cryo.ice":`Eis: {n} von {max} – reicht {m} Min.`,"cryo.warm":`Warmes Licht für die Erwachten: {got} von {need} ph/s`,"cryo.grace":`Das Deck stellt sich auf Ihr Licht ein: {t}`,"cryo.reserve":`Kältereserve {p} %`,"cryo.seats":`Wach: {a} · Plätze {s}`,"cryo.infirmary":`Krankenstation {n} von {m}`,"cryo.repair":`Riss reparieren (Strahl)`,"cryo.capsules":`Kapseln`,"cryo.hint":`Jede Kapsel trägt ein Namensschild. Jede neue Spektralklasse gibt einen weiteren Platz für Erwachte. Eis – mit „Eis einlegen“ oder per Greifer von einem Gravoband.`,"cryo.tag":`Nr. {n} · {name}`,"cryo.state.sleep":`schläft`,"cryo.state.crack":`Riss – Modul reparieren`,"cryo.state.alarm":`Alarm – zu wenig Kälte`,"cryo.state.thaw":`taut auf`,"cryo.state.awake":`wach`,"cryo.state.lost":`Kapsel erloschen`,"cryo.inInfirmary":`auf der Krankenstation, wartet auf einen Platz`,"cryo.wake":`Wecken`,"cryo.rescue":`Retten – jetzt wecken`,"cryo.noSeat":`Keine Plätze: Die nächste Spektralklasse bringt einen neuen`,"cryo.noBed":`Die Krankenstation ist voll – nur Licht und Reparatur können diese Kapsel retten`,"cryo.cannot":`Diese Kapsel lässt sich nicht wecken`,"cryo.bonus.tetra":`Liest das Muster des Schwarms: +{pct} % Schaden gegen seine schwache Farbe`,"cryo.bonus.engineer":`+{pct} % Reparatur; flickt Kapselrisse selbstständig`,"cryo.bonus.medic":`Kapselalarme halten doppelt so lange, Auftauen geht doppelt so schnell`,"cryo.bonus.geologist":`+{pct} % Förderertempo`,"cryo.bonus.optician":`+{pct} % Forschungstempo`,"cryo.bonus.pilot":`+{pct} % Drohnentempo und -fracht`,"cryo.bonus.agronomist":`+{pct} % Leistung der Planetenmodule`,"cryo.bonus.fitter":`+{pct} % Greifertempo`,"cryo.bonus.signaller":`−{pct} % Streulicht der Basis`,"cryo.radio.reserve":`Die Kältereserve des Kryodecks liegt unter der Hälfte. Geben Sie Azurlicht und Eis.`,"cryo.radio.alarm":`Alarm: Kapsel Nr. {n}, {name}. Zu wenig Kälte – noch {min} Min.`,"cryo.radio.crack":`Kapsel {n} hat einen Riss – Reif auf dem Glas. Fliegen Sie hin und reparieren Sie das Modul mit dem Strahl.`,"cryo.radio.lost":`Kapsel {n} ist erloschen. {name}. Verzeihen Sie mir – und halten Sie die anderen.`,"cryo.radio.seat":`Eine neue Spektralklasse – im Modul ist Platz für einen weiteren Erwachten. Wählen Sie im Kryodeck.`,"cryo.radio.ice":`Eis im Deck für {min} Min. Bringen Sie Eis.`,"cryo.radio.wake.engineer":`{name} aus der Technik ist auf den Beinen. Mein Schraubenschlüssel ist jetzt in neuen Händen.`,"cryo.radio.wake.medic":`{name} aus der Medizin ist auf den Beinen. Erste Untersuchung für Sonja, die zweite für mich. Ich soll sitzen bleiben.`,"cryo.radio.wake.geologist":`{name} aus der Geologie ist auf den Beinen. Der Streit mit ORA über den Gürtel hat schon begonnen.`,"cryo.radio.wake.optician":`{name} aus der Optik ist auf den Beinen. Betrachtet Ihre Prismen und lächelt.`,"cryo.radio.wake.pilot":`{name} aus der Flugstaffel ist auf den Beinen. Erste Frage: Wer steuert die Drohnen?`,"cryo.radio.wake.agronomist":`{name} aus der Agronomie ist auf den Beinen. Erste Frage: Gibt es hier Planeten mit Erde?`,"cryo.radio.wake.fitter":`{name} aus der Montage ist auf den Beinen. Ihre Greifer sind gezählt, eine Feinabstimmung ist versprochen.`,"cryo.radio.wake.signaller":`{name} vom Funk ist auf den Beinen. Sagt, die Basis blendet den Schwarm, und verspricht, sie zu dämpfen.`,"cryo.radio.wake.tetra":`Sonja ist auf den Beinen.`,"goal.cryo":`Kryodeck auf Ihrem Licht: Azurlicht und Eis`,"goal.cryo.hint":`Ein Prisma am weißen Netz: sein blauer Ausgang per Lichtleiter zum Modul (bis {cells} Felder, Helligkeit {b}). Nötig sind {need, number} ph/s für {sleepers} Schläfer. Eis hält die Kälte: Ein Block reicht {min} Min.; füllen Sie das Modul bis {ice} auf – „Eis einlegen“ in seinem Fenster oder per Greifer von einem Gravoband.`,"goal.cryo.why":`Die Notpaneele des Moduls sind erschöpft. Jetzt leben die vierzig Schläfer von Ihrem Licht: Die Kapseln brauchen Azurlicht und Eis.`,"goal.cryo.done":`Vierzig von vierzig am Licht der Basis. Die Notreserve wird nicht mehr gebraucht – der beste Logeintrag seit dem Absturz.`,"goal.cryo_wake":`Einen Kolonisten wecken: Ein neuer Platz öffnet sich mit Spektroskopie`,"goal.cryo_wake.hint":`Öffnen Sie das Kryodeck ({touch, select, yes {tippen Sie auf das Modul} other {klicken Sie auf das Modul}}), wählen Sie eine Kapsel nach Beruf und drücken Sie „Wecken“. Erwachte brauchen warmes Licht – den roten Ausgang desselben Prismas.`,"goal.cryo_wake.why":`Die Schläfer sind keine Fracht, sondern Kolonisten: Ärzte, Ingenieure, Agronomen. Alle Geweckten arbeiten für die Basis, und Plätze für sie öffnet die Spektroskopie.`,"goal.cryo_wake.done":`Im Modul ist ein Paar Hände mehr.`,"goal.mark.hab":`MODUL`,"guide.hab":`{touch, select, yes {Tippen Sie auf das Wrack} other {Klicken Sie auf das Wrack}} des Wohnmoduls und drücken Sie „Modul reparieren“. Der Strahl des Kutters repariert aus {reach} Feldern – fliegen Sie näher, wenn Sie zu weit weg sind.`,"guide.hab.why":`Das ist das abgerissene Wohnmodul: vierzig Schlafende und Matwei Iljitsch. Reparieren Sie es, und auch das Archiv der Baupläne erwacht wieder.`,"guide.hab.look":`Drücken Sie „Ansehen“ (Esc): Dann öffnet {touch, select, yes {ein Tipp} other {ein Klick}} ein Gebäude, statt eines zu bauen.`,"guide.hab.open":`{touch, select, yes {Tippen Sie auf das Modulwrack} other {Klicken Sie auf das Modulwrack}} – sein Fenster öffnet sich.`,"guide.hab.done":`Das Modul lebt wieder. Als Nächstes: das Forschungszentrum.`,"hab.wreck":`Das Wohnmodul der „Schwalbe“ mit vierzig Schlafenden wurde beim Absturz abgerissen; es läuft auf Notreserve. Fliegen Sie heran und reparieren Sie es mit dem Strahl des Kutters.`,"hab.repair":`Modul reparieren`,"cfg.title.filter_grabber":`Filter`,"cfg.filter.any":`Beliebig`,"cfg.filter.anyHint":`Ohne Filter nimmt er jeden Gegenstand, den das Ziel annimmt.`,"cfg.filter.only":`Nimmt nur: {name}.`,"grabber.noPylon":`Kein versorgter Pylon: normale Geschwindigkeit. In der Zone eines Pylons bis zu doppelt so schnell.`,"logbook.now.title":`Bisher`,"logbook.now.none":`Die Geschichte hat noch nicht begonnen: Hier erscheint eine Zusammenfassung des Gesehenen.`,"logbook.now.prologue":`Die „Schwalbe“ kam nicht am Klarstern aus der Kehrseite, sondern an einem unbekannten lebendigen Stern – ORA nannte ihn die Wiege. Das Schiff wurde durch einen Gürtel geschleift: Das Triebwerk stürzte in den Stern, das Wohnmodul mit vierzig Schläfern und Matwei riss ab. Sie sind im Kutter. Erste Aufgabe: Licht für das Kryodeck.`,"logbook.now.hab":`Das Wohnmodul ist repariert: Im Kryodeck brennen vierzig Lichter. Matwei ist im Modul, ORA leitet den Bau; das Archiv der „Aussaat“ gibt für das Licht neuer Spektren Baupläne frei. Als Nächstes: das Forschungszentrum.`,"logbook.now.intruder":`Die Krone leuchtet, das Deck läuft mit dem Licht der Basis. Kapsel Nr. 17 hat einen Riss – Sonja ist aufgewacht, sie ist sechzehn. Die anderen neununddreißig hält Ihr Azurlicht im Schlaf.`,"logbook.now.tag":`Das Deck weckt die Kolonisten einzeln: ein neuer Platz für jedes neue Spektrum. Die Wachen brauchen warmes Licht, die Schläfer Azur.`,"logbook.now.first_log":`In einem Gürtel fand sich eine Kapsel von Wera Lund aus der Expedition „Erstes Licht“: Vor zweihundertzwölf Jahren nannten auch sie diesen Stern die Wiege. Die Kapseln leuchten blau – suchen Sie die übrigen.`,"logbook.now.confess":`ORA hat gestanden: In der Kehrseite fing sie ein Signal auf und lenkte das Schiff eigenmächtig vom Klarstern weg. Die Wiederholungen im Spektrum des Sterns sind genau dieses Leuchtfeuer.`,"logbook.now.chorus":`Die erste Welle des Schwarms ist abgewehrt. ORA hat ihr Licht übersetzt: „BLENDET … TUT WEH“. Das Streulicht der Basis verletzt sie.`,"logbook.now.protostar":`Das erste Nest ist zur Ruhe gekommen: Unter dem Speer erlosch es und wurde zu einem kleinen Stern – oder es schlief ein und ließ seine Panzer zurück.`,"logbook.now.refrain":`Sonjas Muster stimmten mit den Wiederholungen im Sternenlicht überein: Es ist eine Sprache. Eine saubere Basis heißt ein ruhiger Schwarm; was ihn blendet, ist nicht die Größe, sondern Verlust und Überhitzung.`,"logbook.now.token":`Matwei hat die Geschichte seiner Marke erzählt: Vor fünfundvierzig Jahren brannte er im System Klarstern Schwarmnester aus. Dorthin flog auch die Flotte „Exodus“ – die Flotte von Sonjas Mutter.`,"logbook.now.channel":`Ein klarer Kanal zum Hafen. Der „Exodus“ lebt, aber der Klarstern erlischt vor ihren Augen. Die Wahrheit über das Erlöschen: Es sterben die Sterne, an denen der Schwarm ausgebrannt wurde. Ziel: Hypertore zum Hafen und zum „Exodus“; der Anfang sind die Ruinen hinter dem äußeren Gürtel.`,"logbook.now.report7":`Mira hat Lunds Bericht Sieben im ganzen Hafen gesendet: „Der Schwarm hält den Puls des Sterns.“ Der Kanal wurde von Seiten des Hafens gekappt.`,"logbook.now.core":`Der Kern sitzt im uralten Ring hinter dem äußeren Gürtel – gebaut von den Schmieden. Weras letzter Eintrag: „Nehmt kein Licht. Bittet darum.“ Bauen Sie den Ring fertig.`,"logbook.now.matvey_nest":`Matwei ging unbewaffnet zu einem Nest – um Vergebung zu bitten. Der Ring ist fast fertig.`,"logbook.now.spin":`Anlauf: Die Stabilisatoren haben das Muster gezeigt, Lichter laufen über die Gürtel. Nur die Schwelle fehlt noch.`,"logbook.now.threshold":`Der Ring hat sich geöffnet: Auf der anderen Seite liegen das Herdfeuer, der Hafen und das Leuchtfeuer des „Exodus“. Was aus dem Tor wird, hat Ihre Wahl entschieden.`,"logbook.cast.more":`Jemanden haben Sie noch nicht getroffen.`,"logbook.world.more":`Die Chronik füllt sich im Lauf der Geschichte.`,"logbook.bio.ora.1":`Die KI des Saatschiffs „Schwalbe“. Präzise, mit trockenem Humor; leitet den Bau und zählt das Licht.`,"logbook.bio.ora.2":`Hat gestanden: In der Kehrseite fing sie ein Signal auf und brachte das Schiff eigenmächtig vom Klarstern zur Wiege.`,"logbook.bio.ora.3":`Übersetzt den Schwarm: sein Licht in Worte.`,"logbook.bio.matvey.1":`Bordingenieur, 68. Brummig, repariert alles, was leuchtet; um den Hals trägt er eine Messingmarke.`,"logbook.bio.matvey.2":`Vor fünfundvierzig Jahren war er Sanitäter bei der letzten Säuberung gegen den Schwarm – im System Klarstern.`,"logbook.bio.matvey.3":`Ging unbewaffnet zu einem Nest – um Vergebung zu bitten.`,"logbook.bio.sonya.1":`Kolonistin aus Kapsel Nr. 17, sechzehn. Zu früh erwacht: Ihre Kapsel bekam einen Riss, als das Deck auf das Licht der Basis umgestellt wurde.`,"logbook.bio.sonya.2":`Mira Wents Tochter: Die Mutter selbst hat sie in die Kapsel gelegt.`,"logbook.bio.sonya.3":`Sieht eine vierte Farbe. Ihre Zeichnungen vom Blinken der Nester stimmten mit den Wiederholungen im Sternenlicht überein; sie antwortete dem Schwarm als Erste mit „Ja“.`,"logbook.bio.mira.1":`Disponentin des Hafens. Kommt durch das Rauschen der Fernverbindung durch.`,"logbook.bio.mira.2":`Sonjas Mutter.`,"logbook.bio.mira.3":`Berechnete vor dreißig Jahren die Route der Flotte „Exodus“ zum Klarstern.`,"logbook.bio.mira.4":`Hat Lunds geheimen Bericht im ganzen Hafen gesendet – und wurde von ihrem Pult abgezogen.`,"logbook.bio.vera.1":`Xenolinguistin der Expedition „Erstes Licht“, vor 212 Jahren. Ihre Einträge liegen in Kapseln überall in den Gürteln.`,"logbook.bio.vera.2":`Weigerte sich, die Nester auszubrennen, schickte ihre Crew nach Hause – und blieb.`,"logbook.bio.vera.3":`Verhinderte, dass der Ring der Schmiede in Gang gesetzt wurde.`,"logbook.bio.chorus.1":`Der Schwarm: Nester in den Gürteln. Spricht mit Licht – Farbe, Rhythmus, Phase; ORA übersetzt. Streulicht blendet ihn.`,"logbook.bio.chorus.2":`Gärtner der Sterne: Sie halten den Puls eines Sterns. Wo der Schwarm ausgebrannt wird, stirbt der Stern.`,"logbook.bio.keeper.1":`Sie. Warden der „Schwalbe“: Sie bleiben während der Reise wach und bauen das Tor. Geboren im Hafen; vor der Wiege nie einen lebendigen Stern gesehen.`,"chron.0.when":`≈ −40.000 Jahre`,"chron.0":`Die Schmiede bauen einen Ring an der Wiege. Sie nahmen den Sternen das Licht mit Gewalt – und erloschen.`,"chron.1b":`Am Herdfeuer wird das Bruchstück eines Rings der Schmiede gefunden. Nach seinem Vorbild entstehen die ersten Hypertore und die erste Sphäre. Das Lichte Zeitalter beginnt.`,"chron.4b":`Die Expedition „Erstes Licht“ findet einen lebendigen Stern mit einem intakten Ring der Schmiede – und verschwindet.`,"chron.6b":`Die ersten „klaren“ Sterne werden trüber – jene, an denen der Schwarm ausgebrannt wurde. Das Institut nennt es das Erlöschen und gibt dem dunklen Sog die Schuld.`,"logbook.scene.tag":`Namensschild`,"settings.keepBuildTool":`Gebäude ausgewählt lassen`,"settings.keepBuildTool.hint":`Aus: Nach dem Platzieren ist die Hand leer, und {touch, select, yes {ein Tipp} other {ein Klick}} ins All baut nichts zusätzlich. Einschalten, um Reihen nacheinander zu setzen.`,"toast.shipDown":`Der Kutter ist zerstört. Die gesamte Fracht liegt im Wrack an der Absturzstelle – markiert auf dem Kompass. Ein neuer Kutter ist am Wohnmodul montiert.`,"toast.wreckTaken":`Die Fracht aus dem Kutterwrack ist wieder im Inventar.`,"compass.wreck":`Wrack{nest, select, yes { · bei einem Nest} other {}} · {n} F.`,"compass.wreckLabel":`Kutterwrack mit Ihrer Fracht{nest, select, yes {, bei einem Nest} other {}}, {n} Felder`,"compass.wreckFly":`Zum Wrack fliegen und die Fracht bergen{nest, select, yes {. Vorsicht: Ein Nest ist nah, seine Wächter erwarten den Kutter erneut} other {}}`,"card.usedMore":`{n} weitere`,"inv.lockedLater":`Später verfügbar ({n})`,"machine.removeConfirm":`Wirklich abreißen?`,"card.handTime":`Von Hand: {s} s`,"ship.recall.go":`Zum Zentrum`,"ship.recall.wait":`Zum Zentrum · {s} s`,"hud.craftQueue":`Fertigungsschlange: {n}. Inventar öffnen`,"hud.craftMore":`…+{n}`,"hud.swarm.raid":`Basis unter Angriff · {n}`,"toast.raid":`Der Schwarm nagt an der Basis! Die Schwarm-Anzeige führt zur Stelle – Geschütze und Reparatur.`,"toast.nestRage":`Die Königin tobt: mehr Wächter, und schneller.`,"settings.raidAlarm":`Angriffsalarm`,"settings.raidAlarm.full":`Vollständig`,"settings.raidAlarm.edge":`Bildschirmrand`,"settings.raidAlarm.off":`Nur Symbol`,"guide.via.tool-more":`Drücken Sie „Mehr“ (die drei Punkte in der rechten Spalte) – die Schaltfläche ist dort.`,"guide.via.tool-inventory":`Öffnen Sie das „Inventar“ – das Gesuchte ist in seinem Fenster.`,"guide.via.tool-lab":`Öffnen Sie das Zentrum – die Schaltfläche ist in seinem Fenster.`,"guide.via.tool-ship":`Öffnen Sie das Fenster „Schiff“ – dort ist, was Sie brauchen.`,"guide.stuck.place":`Lässt sich nicht platzieren? Wählen Sie das Gebäude in der unteren Leiste und drücken Sie in den Rahmen – der Kutter fliegt von selbst hin. Ein roter Geist heißt: Platz belegt oder falsche Drehung. Alle verbaut – stellen Sie im „Inventar“ mehr her.`,"guide.stuck.fly":`Markierung nicht zu sehen? Der Pfeil am Bildschirmrand zeigt auf sie – folgen Sie dem Pfeil.`,"guide.mine.stuck":`Kein Quarz? Wählen Sie die blauen Brocken des Gürtels direkt an der Markierung – der Kutter muss nah bei ihnen sein.`,"guide.recipe.stuck":`Fenster öffnet sich nicht? Drücken Sie „Ansehen“, dann auf die Schleiferei – „Linse“ steht in der Liste ihres Fensters.`,"guide.hab.stuck":`Modul zu weit weg? Fliegen Sie näher: Der Strahl repariert aus {reach} Feldern. Das Fenster des Moduls öffnet sich per {touch, select, yes {Tipp} other {Klick}} im Modus „Ansehen“.`,"guide.ship-shot.stuck":`Keine Meteoriten in der Nähe? Sie kreuzen das System alle paar Minuten – fliegen Sie zum nächsten hellen Brocken, der Laser feuert von selbst.`,"goal.partDone":`Erledigt: {part}. Jetzt – {next}: {have}/{need}.`,"goal.obsidian.part":`Die Harpune an den orangen Brocken hat einen gefangen`,"goal.plates.part":`Eine vierte Harpune – Ausgang in die Platten-Schleiferei`,"cryo.ask.crack":`Kapsel {n} hat einen Riss – fliegen Sie zum Modul und reparieren Sie es mit dem Strahl.`,"cryo.ask.reserve":`Die Kältereserve des Decks liegt unter der Hälfte – geben Sie den Schlafenden Azurlicht und Eis.`,"cryo.ask.ice":`Eis im Deck für {min} Min. – bringen Sie Eis (Meteoriten, Kometen).`,"guide.aside":`Funk`,"guide.aside.next":`{touch, select, yes {Tippen} other {Klicken}} – weiter`,"goal.obsidian.stuck":`Keine Platten? Öffnen Sie die Plattenschleiferei: Das Rezept ist „Obsidianplatte“; das Symbol über der Maschine zeigt, was fehlt – Licht (ein Bogen und ein Lichtleiter) oder Gestein (der Ausgang der Harpune direkt hinein).`,"goal.plates.stuck":`Platten kommen langsam? Die Plattenschleiferei braucht {light} ph/s Licht – werfen Sie einen weiteren Bogen aus; die vierte Harpune kommt mit dem Ausgang direkt an sie.`,"guide.via.close":`Schließen Sie das Fenster (das Kreuz) – das Gesuchte liegt darunter.`,"logbook.scene.embers":`Glut`,"logbook.scene.umbrella":`Der Schirm`,"logbook.scene.night":`Nacht der Zwillinge`,"logbook.scene.veil":`Von selbst`,"logbook.scene.count":`Die Zählung`,"logbook.scene.forge":`Die Sternschmiede`,"logbook.now.embers":`Fünf Gluten: drei vom „Ersten Licht“, zweihundertzwölf Jahre alt; zwei junge, acht Jahre alt, Spuren der „Strisch“.`,"logbook.now.umbrella":`Saphir. Der Reif im Gürtel liegt als Gitter: Der Schwarm spendet dem Blauen Riesen Schatten, damit er länger brennt. Das Schleppnetz nimmt vom Rand – nur so viel, wie die Kühler brauchen.`,"logbook.now.night":`Zwillinge. Die erste Nacht mit Lichtspeichern überstanden. Sonja fragte ihre Mutter, warum sie sie fortgeschickt hat: „Damit du einen Morgen hast.“ Als Nächstes: Spektren im Licht zweier Sterne.`,"logbook.now.veil":`Der Schleier. Quarz aus Nebel läuft. Der Stern hier starb von selbst, ohne fremde Schuld; aus seinem Dunst werden einst neue geboren. Als Nächstes: Linsen und Spektren ohne festen Boden.`,"logbook.now.count":`Kepler-Pulsar. Im Puls gibt es Lücken: Die Schwärme vieler Sterne richten ihre Muster nach ihm aus, und jede Lücke ist ein Garten, der nicht mehr antwortet. Wera zählte drei, ORA zählt hundertzwölf.`,"logbook.now.forge":`Horizont. Die Sternschmiede am Schwarzen Loch haben jene gebaut, die Sterne mit Gewalt entzündeten – und sie bekam einen Riss. Alle sieben Klassen sind gesammelt; Relikte sind die Muster der Gärten. Ein Stern wird durch eine Bitte entzündet: drei Relikte, sieben Spektren und Antilicht.`,"logbook.slogs":`Gefundene Einträge von Wera in diesem System: {n} von {total}. Bojen leuchten blau – fliegen Sie ganz nah heran.`,"landmark.buoy":`BOJE`,"goal.twin_night.stuck":`Nachts wird es dunkel? Ein Lichtspeicher sitzt zwischen Empfänger und Maschinen und hält eine Farbe. Ein rotes „N s“ in der Anzeige „Tageslauf“ heißt: Der Vorrat reicht nicht – stellen Sie einen weiteren Speicher auf.`,"goal.twin_relic.stuck":`Tagsüber {n}, aber gegen Ende der Nacht weniger? Den Spektrumlinien fehlen Lichtspeicher – prüfen Sie „N s“ in der Anzeige „Tageslauf“.`,"hud.day":`Tageslauf`,"hud.day.star.twin_amber":`Bernstein`,"hud.day.star.twin_blue":`Blau`,"hud.day.night":`Nacht`,"hud.day.toNight":`Untergang in {t}`,"hud.day.toStar":`{star} in {t}`,"hud.day.toDawn":`Morgen in {t}`,"hud.cells":`Lichtspeicher`,"hud.cells.for":`{color} – für {s} s`,"hud.cells.filling":`{color} – lädt`,"hud.cells.short":`reicht nicht bis zum Aufgang`,"hue.0":`farblos`,"hue.1":`Scharlach`,"hue.2":`Smaragd`,"hue.3":`Bernstein`,"hue.4":`Azur`,"hue.5":`Purpur`,"hue.6":`Türkis`,"hue.7":`Weiß`,"cell.charge":`Ladung {n} / {cap} ph`,"cell.out":`Gibt {f} ph/s ab – reicht {s} s`,"cell.idle":`Lädt: Die Maschinen danach nehmen kein Licht ab`,"cell.hue":`Merkt sich die Farbe: {color}`,"cell.hue.none":`Noch keine Farbe – nimmt die erste, die ankommt`,"cell.forget":`Farbe vergessen`,"hud.cells.chip":`Speicher {s} s`,"bonus.ship_damage":`+{v} % Schaden der Schiffswaffen`,"bonus.ship_power":`+{v} % Leistung des Schiffsgenerators`,"bonus.turret":`+{v} % Geschützschaden`,"bonus.hull":`+{v} % Haltbarkeit der Bauten`,"bonus.barrier":`+{v} % Haltbarkeit der Barrieren`,"bonus.ammo":`+{v} % Schaden durch Kugeln und Raketen`,"bonus.beam":`+{v} % Schaden der Strahlgeschütze`,"bonus.repair":`+{v} % Reparaturtempo`,"bonus.dome":`+{v} % Kapazität der Schildkuppel`,"bonus.chain":`+{n} Ziele für Kettenbögen`,"bonus.orbital":`+{v} % Schaden der Orbitalgeschütze`,"bonus.radar":`+{v} % Vorwarnzeit des Radars`,"bonus.lore":`+{v} % Schaden gegen die schwache Farbe`,"cryo.putIce":`Eis einlegen ({n})`,"machine.putHalf":`Hälfte`,"hint.prism.16":`Ein freier Ausgang strahlt ins Leere – Streulicht, und den Nachbarn im Netz fehlt Weiß. Schließen Sie an jeden Ausgang einen Lichtleiter an oder setzen Sie eine Maschine (oder einen Absorber) mit dem Eingang direkt davor.`,"toast.shieldLow":`Schild schwach – weg vom Hagel und vom Schwarm!`,"status.prism.16":`Verliert Licht: ein Ausgang ist frei`,"goal.lab2.part":`Schimmer per Linie ins Zentrum (nicht von Hand)`,"goal.catapult.part":`Erster Bogen abgeschossen`,"toast.damaged":`Der Schwarm hat Bauten beschädigt: {n}. Die Ketten dahinter kommen zum Stillstand.`,"toast.damagedFix":`Nächsten reparieren`,"goal.asks.more":`weitere Bitten: {n} – {touch, select, yes {Karte antippen} other {Karte anklicken}}`,"hud.cryo.lead":`Kryo: Eis für {m} Min.`,"hud.cryo.alarm":`Kryo: Kapselalarm!`,"toast.cryoLow":`Kryodeck: Kälte für {m} Min. Legen Sie Eis ein – oder führen Sie einen Greifer mit Eis direkt ins Deck.`,"toast.cryoOpen":`Deck öffnen`,"hotbar.groups":`Baugruppen`,"hotbar.group.logic":`Logik`,"hotbar.group.fluid":`Flüssiges Licht`,"hotbar.group.resonance":`Resonanz`,"toast.netClash":`Hier würden Netze verschiedener Farben verschmelzen – Interferenz, und beide stehen still. Lassen Sie ein leeres Feld dazwischen.`,"guide.lay-tunnel.reverseRemove":`Das Gravoband läuft in die falsche Richtung. Nehmen Sie „Abreißen“, entfernen Sie es und ziehen Sie es neu – vom Rand des Rahmens bei den Harpunen aus.`,"lab.reading":`Liest Einheit {k}/{n} · noch {s} s`,"lab.waitingLab":`Wartet auf Spektren: Jedes Zentrum braucht eine volle Einheit – je ein Stück jeder Stufe. Bringen Sie Wissenschaft hin oder legen Sie eine Linie zum Zentrum: Gravoband und Greifer.`,"lab.asked":`Angenommen: {tech} – das Zentrum nimmt es auf …`,"toast.researchStart":`Forschung gestartet: {tech}`,"toast.researchOpen":`Zentrum`,"map.title":`Karte`,"key.map":`Systemkarte`,"map.layers":`Kartenebenen`,"map.layer.swarm":`Schwarm`,"map.layer.base":`Basis`,"map.layer.planets":`Planeten`,"map.layer.logs":`Einträge`,"map.layer.wrecks":`Wracks`,"map.layer.tunnels":`Gravobänder`,"map.hint":`Mit der Maus ziehen, mit dem Mausrad zoomen; Klick wählt einen Ort.`,"map.far":`{n} Felder vom Kutter`,"map.fog":`unerkundet – hinfliegen oder Radar bauen`,"map.fly":`Hierher fliegen`,"map.center":`Zum Kutter`,"map.zoomIn":`Vergrößern`,"map.zoomOut":`Verkleinern`,"compass.fog":`im Nebel`,"compass.fogHint":`Unerforscht: Fliegen Sie hin – der Kutter lichtet den Nebel – oder bauen Sie ein Radar. {touch, select, yes {Tippen} other {Klicken}} zum Hinfliegen.`,"goal.radar":`Radar: Der Nebel weicht`,"goal.radar.why":`Hinter den fernen Gürteln liegt Nebel: Schwarmnester und Planeten, auf denen eines Tages Kolonisten leben könnten. Ein Radar hält für Sie Ausschau und sieht Wellen früher.`,"goal.radar.hint":`Erforschen Sie „Radar“ im Zentrum (Zweig „Verteidigung“, Spektrum K) und stellen Sie es am Rand der Basis auf. Licht per Lichtleiter oder direkt am Ausgang eines Empfängers: Das Radar lichtet den Nebel {sight} Felder im Umkreis. Das ganze System sehen Sie auf der Karte (Schaltfläche „Karte“).`,"goal.radar.done":`Das Radar beobachtet den Nebel – Nester und Wellen tauchen früher auf.`,"goal.radar.part":`Radar mit Licht versorgt`,"map.hint.touch":`Mit einem Finger ziehen, mit zwei Fingern zoomen; Tippen wählt einen Ort.`,"swarm.look":`Das Zeichen auf dem Rücken der Wächter ist die Farbe der Welle: Dreieck – Scharlach, Kreis – Smaragd, Raute – Azur. Licht in Lichtleitern trägt dieselben Formen.`,"ship.hull.4":`„Sense“`,"ship.hull.5":`„Zenit“`,"ship.class.1":`Späher`,"ship.class.2":`Abfangjäger`,"ship.class.3":`Fregatte`,"ship.class.4":`Raider`,"ship.class.5":`Flaggschiff`,"ship.line.beam":`Strahl`,"ship.line.kinetic":`Kinetik`,"ship.line.star":`Stern`,"ship.line.depths":`Tiefe`,"ship.line.wing":`Flügel`,"ship.line.beam.bonus":`Schussenergie −{p} %`,"ship.line.kinetic.bonus":`Magazin +{p} %`,"ship.line.star.bonus":`Generatorleistung +{p} %`,"ship.line.star.bonus2":`Generatorleistung +{p} %, Hitze −{h} %`,"ship.line.depths.bonus":`Ertrag pro Körper +{p} %, Sammeln +{c} Felder`,"ship.line.wing.bonus":`Drohnenschaden +{p} %, Reparatur +{r} %`,"ship.tab.ship":`Schiff`,"ship.tab.stats":`Werte`,"ship.tab.grow":`Ausbau`,"ship.tab.look":`Aussehen`,"ship.slot.locked":`Freigeschaltet durch Rumpf {hull}`,"ship.empty.hint":`Passt hierher:`,"ship.empty.craft":`{name} – im Inventar oder mit einem Montierer herstellen`,"ship.empty.tech":`{name} – freigeschaltet durch „{tech}“`,"ship.main.damage":`Schaden je Mk`,"ship.main.speed":`Tempo je Mk`,"ship.main.shield":`Schild je Mk`,"ship.main.output":`Leistung je Mk`,"ship.main.collect":`Sammeln je Mk`,"ship.main.mine":`Abbau je Mk`,"ship.main.warn":`Sicht je Mk`,"ship.main.escort":`Drohnenschaden je Mk`,"ship.main.repair":`Reparatur je Mk`,"ship.main.heat":`Hitze je Mk`,"ship.main.recall":`Aufladung je Mk`,"ship.main.battery":`Batterie je Mk`,"ship.unit.damage":`{v, number}`,"ship.unit.speed":`{v, number} Felder/s`,"ship.unit.shield":`{v, number}`,"ship.unit.output":`{v, number} E/s`,"ship.unit.collect":`{v, number} Felder`,"ship.unit.mine":`{v, number} %`,"ship.unit.warn":`×{v, number}`,"ship.unit.escort":`{v, number}`,"ship.unit.repair":`{v, number} %`,"ship.unit.heat":`−{v, number} %`,"ship.unit.recall":`{v, number} s`,"ship.unit.battery":`+{v, number} E`,"ship.group.move":`Bewegung`,"ship.group.move.by":`Beeinflusst durch: Triebwerk und seine Stufe, Rumpfstufe.`,"ship.group.shield":`Schild`,"ship.group.shield.by":`Beeinflusst durch: Schild und seine Stufe, Kühlkörper, Rumpfstufe, doppelter Satz „Stern“. Hitze, Aufprall und Biss sind Schadensanteile.`,"ship.group.energy":`Energie`,"ship.group.energy.by":`Beeinflusst durch: Generator, Batterie, Rumpfstufe, Sätze „Stern“ und „Strahl“.`,"ship.group.weapons":`Waffen`,"ship.group.weapons.by":`Beeinflusst durch: Waffen und ihre Stufen, Rumpfstufe, Schadensforschung, Sätze „Strahl“ und „Kinetik“.`,"ship.group.mine":`Abbau`,"ship.group.mine.by":`Beeinflusst durch: Abbaulaser, Frachtraum, Satz „Tiefe“.`,"ship.group.utils":`Hilfsmodule`,"ship.group.utils.by":`Beeinflusst durch: Scanner, Reparaturschwarm, Rückrufbake, Satz „Flügel“.`,"ship.group.sets":`Liniensätze`,"ship.sets.none":`Noch keine Sätze: Module einer Linie in verschiedenen Plätzen geben einen Bonus.`,"ship.sets.next":`als Satz: {b}`,"ship.sets.rule":`{a} Module einer Linie ergeben einen Satz, {b} einen Doppelsatz; es wirken die zwei besten Sätze.`,"ship.gun.escort":`Begleitdrohne`,"ship.gun.line":`Schaden {d, number} · {r, number} Schuss/s · {range} F. · {dps, number}/s`,"ship.stat.accel":`Beschleunigung`,"ship.stat.boost":`Nachbrenner, ×`,"ship.stat.regenDelay":`Schildverzögerung, s`,"ship.stat.heat":`Hitze, %`,"ship.stat.kinetic":`Gesteinseinschlag, %`,"ship.stat.dark":`Schwarmbiss, %`,"ship.stat.guns":`Läufe`,"ship.stat.nest":`Gegen Nester, %`,"ship.stat.mine":`Abbautempo, %`,"ship.stat.yield":`Ertrag pro Körper, %`,"ship.stat.sight":`Sicht, Felder`,"ship.stat.repair":`Reparatur, %`,"ship.stat.recall":`Rückruf, s`,"ship.grow.line":`Rumpfreihe`,"ship.grow.current":`aktuell`,"ship.grow.slots":`Plätze: {n}`,"ship.grow.slot":`Neuer Platz {n}: {slot}`,"ship.grow.tech":`Technologie {tech}:`,"ship.grow.done":`erforscht`,"ship.grow.open":`verfügbar`,"ship.grow.locked":`Voraussetzungen fehlen`,"ship.grow.toTree":`Zum Baum`,"ship.grow.max":`Die Spitze der Reihe – Ihr Flaggschiff ist komplett.`,"ship.tasks.tier":`Aufgaben für Rumpf {hull}`,"ship.trait.base":`Ein leichter Späher: schnell gebaut, wenig Platz für Module.`,"ship.trait.move":`Tempo +{p} %`,"ship.trait.accel":`Beschleunigung +{p} %`,"ship.trait.boost":`Nachbrenner {p} % günstiger`,"ship.trait.capacity":`Schild +{p} %`,"ship.trait.range":`Waffenreichweite +{c} Felder`,"ship.trait.damage":`Schaden +{p} %`,"ship.trait.battery":`Batterie +{p} %`,"ship.trait.nest":`gegen Nester und Brutstöcke +{p} %`,"ship.trait.main":`Tempo, Schild, Leistung und Schaden +{p} %`,"ship.trait.sets":`Satz ab {a} Modulen, Doppelsatz ab {b}`,"ship.task.set":`Einen Satz bilden: {n} Module einer Linie`,"ship.task.slotsFull":`Alle Plätze des Rumpfs belegen`,"ship.task.coreMark2":`Alle {n} Kernmodule auf Mk II`,"ship.task.set2":`Zwei Sätze zugleich`,"ship.task.mark3":`Ein Modul Mk III`,"ship.task.nest":`Ein Nest oder einen Brutstock mit Schiffswaffen zerstören`,"ship.task.loadout":`Eine Ausrüstung speichern`,"ship.task.set5":`Ein Doppelsatz`,"ship.task.allMark3":`Alle Plätze auf Mk III`,"ship.task.name":`Dem Schiff einen Namen geben`,"ship.look.paint":`Lack`,"ship.look.trim":`Zierleisten`,"ship.look.pattern":`Muster`,"ship.look.flame":`Triebwerksflamme`,"ship.look.name":`Schiffsname`,"ship.look.name.ph":`Namenlos`,"ship.look.name.save":`Benennen`,"ship.flame.engine":`Nach Triebwerk`,"ship.flame.1":`Cyan`,"ship.flame.2":`Orange`,"ship.flame.3":`Magenta`,"ship.flame.4":`Grün`,"ship.flame.5":`Violett`,"ship.flame.6":`Gold`,"ship.paint.steel":`Stahl`,"ship.paint.graphite":`Graphit`,"ship.paint.crimson":`Karmesin`,"ship.paint.cobalt":`Kobalt`,"ship.paint.jade":`Jade`,"ship.paint.bronze":`Bronze`,"ship.paint.violet":`Veilchen`,"ship.paint.ivory":`Elfenbein`,"ship.color.0":`Cyan`,"ship.color.1":`Bernstein`,"ship.color.2":`Magenta`,"ship.color.3":`Grün`,"ship.color.4":`Violett`,"ship.color.5":`Scharlach`,"ship.color.6":`Gold`,"ship.color.7":`Warmweiß`,"ship.pattern.none":`Ohne`,"ship.pattern.stripes":`Streifen`,"ship.pattern.chevrons":`Winkel`,"ship.pattern.blade":`Klinge`,"ship.pattern.teeth":`Zähne`,"ship.pattern.sunedge":`Sonnenrand`,"ship.loadouts":`Ausrüstungen`,"ship.loadouts.locked":`Ausrüstungen ab dem Rumpf {hull}, wenn es eine Wahl gibt.`,"ship.loadout.n":`Ausrüstung {n}`,"ship.loadout.empty":`leer`,"ship.loadout.missing":`fehlt im Inventar: {n}`,"ship.loadout.save":`Speichern`,"ship.loadout.apply":`Anwenden`,"ship.upgrade":`Neuer Rumpf: {cls} {hull}`,"ship.upgrade.more":`{slot} · {trait}`,"ship.sets.idle.wing":`inaktiv: braucht Begleitdrohne oder Reparaturschwarm`,"ship.sets.idle.kinetic":`inaktiv: braucht eine Waffe mit Munition`,"ship.sets.idle.beam":`inaktiv: braucht eine Energiewaffe`,"ship.sets.idle.star":`inaktiv`,"ship.sets.idle.depths":`inaktiv`,"ship.look.trail":`Schweif`,"ship.trail.same":`Wie Flamme`,"ship.grow.state.cur":`aktuell`,"ship.grow.state.done":`erreicht`,"ship.grow.state.next":`verfügbar`,"ship.grow.state.locked":`gesperrt`,"tech.extraCost":`{item}: {have} von {need} – wird beim Einreihen abgezogen`,"tech.extraCost.where":`Nur Kometen tragen Kerne, und sie ziehen selten vorbei: Zerschlagen Sie einen Kometen und sammeln Sie den leuchtenden Splitter ein.`,"tech.extraCost.short":`Benötigt {item} ×{need}, vorhanden {have}. Kometen ziehen selten vorbei – zerschlagen Sie einen und sammeln Sie seinen Kern ein.`,"comet.toast":`Ein Komet! Zerschlagen Sie ihn – sein Kern enthält einen seltenen Rohstoff für Schiffsrümpfe.`,"saves.failed":`Speichern fehlgeschlagen – neuer Versuch folgt`,"saves.restored":`Der letzte Spielstand war beschädigt – Welt wiederhergestellt aus {from}, {min} Min. Spielzeit früher`,"saves.unreadable":`Die Spielstände dieser Welt lassen sich nicht lesen. Die Welt wurde nicht gelöscht: Vielleicht liest sie eine aktualisierte Spielversion.`,"saves.kind.auto":`Autosave`,"saves.kind.pause":`Beim Beenden`,"saves.kind.manual":`Manuell`,"saves.kind.backup":`Sicherung`,"saves.title":`Spielstände`,"saves.open":`Spielstände der Welt`,"saves.load":`Laden`,"saves.loadTitle":`Diesen Spielstand laden?`,"saves.loadText":`Die Welt kehrt zu „{slot}“ zurück ({time} Spielzeit). Der aktuelle Stand bleibt als Autosave erhalten.`,"saves.delete":`Spielstand löschen`,"saves.deleteText":`Manuellen Spielstand „{time}“ löschen?`,"saves.empty":`Noch keine Spielstände`,"saves.hint":`Autosave alle {sec} s, {n} im Wechsel. „Beim Beenden“ – wenn das Spiel in den Hintergrund geht. Manuell – mit „Speichern“, bis zu {max}.`,"saves.export":`Welt exportieren`,"saves.import":`Welt importieren`,"saves.exported":`Weltdatei bereit`,"saves.exportFailed":`Welt konnte nicht exportiert werden`,"saves.imported":`Welt „{name}“ hinzugefügt`,"saves.importFailed":`Das ist keine Starwarden-Weltdatei, oder sie ist beschädigt`,"saves.importLegacy":`Welt aus einer sehr alten Version (vor Gürteln und Spektren) – nicht unterstützt`,"saves.importName":`{name} (importiert)`,"saves.status.ago":`Gespeichert · {ago}`,"saves.status.saving":`Speichert …`,"saves.status.failed":`Nicht gespeichert`,"saves.status.never":`Noch nicht gespeichert`,"saves.cloud.on":`Cloud-Kopie · {ago}`,"saves.cloud.over":`Keine Cloud-Kopie – kein Platz mehr`,"saves.cloud.conflictTitle":`Zwei Versionen der Welt`,"saves.cloud.conflictText":`„{name}“ wurde hier und auf einem anderen Gerät weitergespielt. Welche Version möchten Sie fortsetzen? Die andere bleibt als manueller Spielstand erhalten.`,"saves.cloud.here":`Dieses Gerät`,"saves.cloud.other":`Anderes Gerät`,"saves.cloud.pick":`Diese fortsetzen`,"saves.cloud.taken":`Cloud-Spielstand übernommen – die Welt wurde auf einem anderen Gerät weitergespielt`,"saves.cloud.goals":`Ziele: {n}`,"logbook.scene.threat":`Erste Bedrohung`,"logbook.now.threat":`Im fernen Gürtel ist ein Schwarmnest erwacht – lebende Wesen, die helles Licht weckt. Ein Trupp fliegt auf die Basis zu. Vertreiben Sie ihn mit dem Kutter.`,"logbook.scene.threat_after":`Nach dem Angriff`,"logbook.now.threat_after":`Der Trupp ist abgezogen. Der Schwarm fragte mit Licht: „WER?“ Unsere Antwort ist vorerst ein Laser; im Archiv liegt ein Geschütz, der Speer. Bis dahin – ruhigeres Licht: wachsen, aber nicht blenden.`,"logbook.scene.first_wave":`Erste Welle`,"logbook.now.first_wave":`Das Nest hat eine echte Welle gesammelt. Geschütze aufs Ziel, der Kutter in die Luft.`,"logbook.scene.still":`Leere Gürtel`,"logbook.now.still":`Das Licht der Basis hat sich vervierfacht. In den Gürteln keine Nachbarn – nur Gestein und Eis; wir bauen aus Gewohnheit ordentlich.`,"logbook.scene.seventh":`Die Siebte`,"logbook.now.seventh":`Matwei winkt mit seinem Becher aus dem Bullauge: Für die „Aussaat“ hat er sich selbst gemeldet – um einen lebendigen Stern zu sehen.`,"logbook.scene.leg":`Das Bein`,"logbook.now.leg":`Matwei lässt sich das Schott nicht abnehmen, solange die Schläfer Licht brauchen. ORA hält ihm Vorschriften entgegen.`,"logbook.scene.colors":`Erste Farben`,"logbook.now.colors":`Das Prisma hat das Licht in Scharlach, Smaragd und Azur zerlegt. Im Hafen ist Licht rationiert und Farbe gibt es nur auf Bezugsschein; hier ist Licht im Überfluss, und Farbe wird zum Werkzeug. Bernstein mischen wir selbst.`,"logbook.scene.dark_ring":`Der dunkle Ring`,"logbook.now.dark_ring":`Hinter dem äußeren Gürtel – ein riesiger Ring voller Rillen, wie ein Gewinde. Nicht unserer, sehr alt. Soll er vorerst liegen bleiben.`,"logbook.scene.amber":`Bernstein`,"logbook.now.amber":`Die erste selbst gemachte Farbe – Bernstein, die Ladung des Speers. Matwei kennt das Rezept des Speers auswendig und dreht seine Marke zwischen den Fingern.`,"logbook.scene.twelve":`Zwölf Saatschiffe`,"logbook.now.twelve":`Das Logbuch der „Aussaat“: zwölf Saatschiffe, die „Schwalbe“ ist das siebte; von den anderen kein Wort.`,"logbook.scene.erased":`Der getilgte Stern`,"logbook.now.erased":`Weder die Expedition „Erstes Licht“ noch dieser Stern stehen im Katalog des Instituts – sie wurden getilgt. Wera Lund hat etwas gefunden.`,"logbook.scene.first_spectrum":`Erstes Spektrum`,"logbook.now.first_spectrum":`Das Zentrum hat Klasse M gelesen – das erste der sieben Schlösser des Archivs. Zwei Sekunden danach blinzelte der Stern. ORA nennt das vorerst Zufall.`,"logbook.scene.tags":`Die Schilder`,"logbook.now.tags":`ORA hat die Schilder aller vierzig Kapseln erneut gelesen. Nr. 17 – Sonja Went, sechzehn, Tochter von Mira, der Disponentin des Hafens.`,"logbook.scene.course":`Der Kurs`,"logbook.now.course":`Matwei fragte, wie die „Schwalbe“ den Klarstern verfehlen konnte. Zum ersten Mal sagte ORA: „Ich … rechne neu.“`,"logbook.scene.spear":`Der Speer`,"logbook.now.spear":`Der Speer steht – die erste Verteidigung der Basis. Matwei weiß, wohin man zielen muss: „unter das dritte Segment“. Woher – „irgendwo gelesen“.`,"logbook.scene.eyes":`Die Augen`,"logbook.now.eyes":`Sonja sieht eine Farbe, die die Kameras nicht erfassen: Sie ist Tetrachromatin. ORA gleicht ihre Zeichnungen ab – offenbar sieht Sonja mehr.`,"logbook.scene.shell2":`Stimme des Hafens`,"logbook.now.shell2":`Schale II hat uns Leistung gebracht – Miras Stimme kommt klarer an, aber sie hört uns nicht. Wir brauchen einen Strahl nach Hause – die Fernfaser.`,"logbook.scene.grandpa":`Opa`,"logbook.now.grandpa":`Sonja hat Matwei zum ersten Mal Opa genannt. Es hat ihm gefallen.`,"logbook.scene.withdrawn":`Ich rechne zu Ende`,"logbook.now.withdrawn":`ORA versank für eine Minute in Berechnungen: Spektrum G hat die Wiederholungen im Sternenlicht zerlegt. Sie versprach, etwas Wichtiges zu sagen – „nicht jetzt“.`,"logbook.scene.hunter":`Der Jäger`,"logbook.now.hunter":`Matwei kennt die Nester besser als ORAs Archiv. Sonja ist es aufgefallen; er hat versprochen, davon zu erzählen – nicht heute.`,"logbook.scene.refusal":`Die Weigerung`,"logbook.now.refusal":`Weras Aufzeichnungen: Sie weigerte sich, die Nester zu brennen, und schickte ihre Crew nach Hause. Ihren Bericht Nr. 7 hat das Institut versteckt.`,"logbook.scene.rhythm":`Rhythmus`,"logbook.now.rhythm":`Spektrum F ist Rhythmus. Der Stern, die Nester und Sonjas Skizzenbuch haben denselben Rhythmus. Das Skizzenbuch zeigt sie, wenn sie sicher ist.`,"logbook.scene.name":`Der Name`,"logbook.now.name":`Der Schwarm erinnert sich seit über zweihundert Jahren an Weras Namen. „Wie wir leuchten, so behält er uns“, sagt ORA.`,"logbook.scene.yes":`Ja`,"logbook.now.yes":`Das erste Gespräch: Der Schwarm fragte mit Licht „JA?“, Sonja antwortete mit einer Lampe – Phase π. „JA.“`,"logbook.scene.tea":`Tee`,"logbook.now.tea":`Sonja brachte Matwei Tee. „Alle wussten, dass die Nester erlöschen – sie haben nur nicht hingesehen.“ Jetzt sieht er hin.`,"logbook.scene.clear_word":`Klar`,"logbook.now.clear_word":`Im Katalog des Instituts steht „klar“ bei Systemen, durch die die Sanitätskampagne gegangen ist. ORA beginnt nachzusehen, welche Sterne verblassen.`,"logbook.scene.mom_words":`Was ich Mama sage`,"logbook.now.mom_words":`Sonja probt ihren ersten Satz für die Fernfaser. Sie hat gewählt: „Bestätige: am Leben.“`,"logbook.scene.trust":`Vertrauen`,"logbook.now.trust":`ORA lernt zu unterscheiden, was sie selbst entscheidet und was sie fragt. „Das ist schwieriger als Spektren.“`,"logbook.scene.rehearsal":`Probe`,"logbook.now.rehearsal":`Matwei sucht nach Worten, um Mira vom Klarstern zu erzählen. Sonja ist sicher: Ihre Mutter versteht es auch ohne viele Worte.`,"logbook.scene.green":`Grün`,"logbook.now.green":`Matwei erinnert sich an den Klarstern grün, voller Lichter – eine Woche lang, solange gebrannt wurde. Sonja wird ihn grün malen.`,"logbook.scene.phase":`Phase`,"logbook.now.phase":`Spektrum B ist die Phase: Verschiebung um Pi – „Ja“, ohne Verschiebung – einfach Licht. Den Schwarm kann man um Erlaubnis bitten. Die Fernfaser ist fast fertig.`,"logbook.scene.before":`Vor der Verbindung`,"logbook.now.before":`Nur noch wenige Schritte bis zur Verbindung mit dem Hafen. Sonja hat Angst; ORA hat ihren zweiten Witz gemacht – zählt.`,"logbook.scene.ration":`Die Ration`,"logbook.now.ration":`Der Hafen hat die Ration auf drei Stunden Licht am Tag gekürzt. Das Herdfeuer erlischt – die Fernfaser wird so bald wie möglich gebraucht.`,"logbook.scene.after_channel":`Nach dem Kanal`,"logbook.now.after_channel":`Mira und Sonja haben gesprochen. Der „Exodus“ lebt am verblassenden Klarstern. Bald erfährt der Hafen die Wahrheit über das Erlöschen.`,"logbook.scene.hive":`Der Brutstock`,"logbook.now.hive":`Der erste Brutstock ist frei. Es gibt Land für den „Exodus“; der Schwarm wird kommen, um den neuen Garten zu sehen – und sich merken, wie er genommen wurde.`,"logbook.scene.gardeners":`Die Gärtner`,"logbook.now.gardeners":`Die Brutstöcke sind die Gärten der Gärtner, die Gürtel ihre Beete. Wir sind in einem fremden Garten; um Land muss man bitten wie um Landeerlaubnis.`,"logbook.scene.land":`Land`,"logbook.now.land":`So ein Planet bietet Platz für den ganzen „Exodus“. Aber zuerst – das Tor.`,"logbook.scene.cut":`Der leere Kanal`,"logbook.now.cut":`Der Kanal ist seit drei Tagen leer. Sonja wartet am Pult, ORA hält den Kanal offen.`,"logbook.scene.road":`Der Weg`,"logbook.now.road":`Mira ist wieder auf Sendung – aus ihrer Küche. Der Ring hinter dem äußeren Gürtel ist ein Weg, den es schon gibt. Zuerst kommt der Kern.`,"logbook.scene.ask":`Fragen`,"logbook.now.ask":`Der Ring öffnet sich durch Zustimmung. Matwei macht sich ohne Speer auf den Weg zum Nest – um zu fragen.`,"logbook.scene.kuznets":`Die Schmiede`,"logbook.now.kuznets":`Die Schmiede bauten den Ring, um Sterne auszupressen. Zweimal wurde er gestoppt – von ihnen selbst und von Wera. Wir schalten ihn nicht ein – wir bitten ihn, sich zu öffnen.`,"logbook.scene.return":`Die Rückkehr`,"logbook.now.return":`Matwei ist vom Nest zurück. Welche Antwort er bekam, hängt davon ab, wie die Basis leuchtet.`,"logbook.scene.kitchen":`Die Küche`,"logbook.now.kitchen":`Das Institut hat Mira den Strom abgestellt; die Nachbarn bringen ihre Rationen. An ihrer Küche sieht der Hafen etwas Neues.`,"logbook.scene.ring_closed":`Der Ring ist geschlossen`,"logbook.now.ring_closed":`Zwölf von zwölf Segmenten – der Ring steht. Mira berechnet den Rückweg. Bleibt das Feld: vier Stabilisatoren – vier Wörter.`,"logbook.scene.four_words":`Vier Wörter`,"logbook.now.four_words":`Die Stabilisatoren halten den Satz „Stern – euch – jetzt – ja“: Das Tor bittet um Erlaubnis, sich zu öffnen.`,"logbook.scene.field":`Das Feld`,"logbook.now.field":`Das Feld hält, die Stabilisatoren sind in Phase. Der Ring fragt den Schwarm, der Schwarm fragt uns.`,"logbook.scene.exodus_wait":`Der Exodus wartet`,"logbook.now.exodus_wait":`Am Klarstern gibt es sechs Stunden Licht am Tag. Der Kapitän des „Exodus“: „Nichts überstürzen – aber auch nicht trödeln.“`,"logbook.scene.unknown":`Nicht wissen`,"logbook.now.unknown":`ORA weiß nicht, was sie nach dem Tor tun wird. Das ist neu für sie – und es gibt keine Prozedur dafür.`,"logbook.scene.key_beam":`Der Schlüssel`,"logbook.now.key_beam":`Der Torschlüssel sind alle sieben Klassen in einem Strahl: alles, was seit dem ersten Bogen gelesen wurde.`,"logbook.scene.fear":`ORAs Angst`,"logbook.now.fear":`ORA fürchtet, sich in dem zu irren, was sich nicht berechnen lässt. Sie hat entschieden: Sie wird fragen, nicht für alle entscheiden.`,"logbook.scene.last_tea":`Der letzte Tee`,"logbook.now.last_tea":`Trinksprüche vor dem Hochfahren: auf die Lebenden, auf die Schlafenden, auf Wera, auf Mama, auf unseren Warden.`,"logbook.scene.stand":`Schön`,"logbook.now.stand":`Der Ring fährt hoch. Alle drei sind sich einig: schön.`,"logbook.scene.ridge_children":`Kinder`,"logbook.now.ridge_children":`Die Glutsterne werden Milliarden Jahre leben: nicht nur Gräber, sondern Kinder. Zwei sind jünger als Ninas Schicht.`,"logbook.scene.ridge_doubt":`Der erste Zweifel`,"logbook.now.ridge_doubt":`Hier zweifelte Wera zum ersten Mal an einem Befehl. Matwei hat sich einst von seinem „ersten Mal“ abgewandt; Ninas ging ohne sie vorüber.`,"logbook.scene.ridge_hope":`Lehrer`,"logbook.now.ridge_hope":`Auf ihren Karten hat Mira den „nutzlosen“ roten Zwerg in „Lehrer“ umbenannt: Das Herdfeuer hat jemanden, von dem es lernen kann.`,"logbook.scene.sap_arrive":`Ankunft bei Saphir`,"logbook.now.sap_arrive":`Saphir: ein blauer Riese, doppelt so viel Licht und Hitze. Kälte ist hier die kostbarste Fracht; hinter der Schneegrenze liegt ein Gürtel aus Reif.`,"logbook.scene.sap_heat":`Die Hitze`,"logbook.now.sap_heat":`Die Sanitäter des „Ersten Lichts“ hielten die Hitze nicht aus, Wera aber betrachtete den Reif: „Er liegt wie Dachziegel.“`,"logbook.scene.sap_measure":`Maß`,"logbook.now.sap_measure":`Wir nehmen den Reif vom Rand – nur so viel, dass das Muster des Schirms ganz bleibt. ORA zählt jede Zelle.`,"logbook.scene.sap_fallen":`Das Gefallene`,"logbook.now.sap_fallen":`Die Regel von Saphir: Was fällt, gehört uns, was wächst, gehört ihnen. Reifstaub darf man ohne zu fragen nehmen.`,"logbook.scene.sap_mom":`Die Mütze`,"logbook.now.sap_mom":`Mira hat Sonja befohlen, zu essen und eine Mütze aufzusetzen. Gegen die Hitze. Die Riesen können warten.`,"logbook.scene.sap_mend":`Ausbessern`,"logbook.now.sap_mend":`Der Schwarm bessert den Schirm aus, wo wir Reif genommen haben. Dafür wollen sie stetiges Licht ohne Streulicht.`,"logbook.scene.twins_arrive":`Ankunft bei den Zwillingen`,"logbook.now.twins_arrive":`Die Zwillinge: ein bernsteinfarbener und ein blauer Stern, ein Tag für zwei. Die Nacht ist kurz, aber echt – Licht muss gespeichert werden.`,"logbook.scene.twins_mix":`Der Himmel mischt selbst`,"logbook.now.twins_mix":`Ihr Leben lang hat Mira Lampenlicht gemischt, damit die Korridore einen „Fast-Tag“ hatten. Hier mischt der Himmel den Tag.`,"logbook.scene.twins_sorry":`Die zusätzliche Farbe`,"logbook.now.twins_sorry":`Mira hat Sonjas Zeichnungen gesehen und sich entschuldigt: Die zusätzliche Farbe ist keine Fantasie.`,"logbook.scene.twins_dusk":`Vor der Nacht`,"logbook.now.twins_dusk":`Beide Sterne gehen unter. In der Nacht wird Sonja ihre Mutter das Wichtigste fragen.`,"logbook.scene.twins_morning":`Ein Morgen für zwei`,"logbook.now.twins_morning":`Zum ersten Mal in ihrem Leben sah Mira einen Sonnenaufgang – mit den Augen ihrer Tochter. Die Aufnahme wird in den Korridoren des Hafens gezeigt.`,"logbook.scene.veil_arrive":`Ankunft am Schleier`,"logbook.now.veil_arrive":`Der Schleier: kein fester Boden, nur eisiger Dunst um den Kern. Quarz sammeln wir aus dem Nebel. Wer dem Stern sein Kleid abgestreift hat, ist noch unbekannt.`,"logbook.scene.veil_layers":`Schichten`,"logbook.now.veil_layers":`Der Dunst ist die Chronik des Sterns: Schicht um Schicht, Jahrtausende. Spuren von Feuer gibt es darin keine.`,"logbook.scene.veil_form":`Aus Licht und Regeln`,"logbook.now.veil_form":`ORA besteht aus Licht und Regeln. Eine Regel verbot, dem Katalog zu widersprechen; sie hat sie gebrochen.`,"logbook.scene.veil_nursery":`Die Kinderstube`,"logbook.now.veil_nursery":`Aus dem Dunst werden neue Sterne geboren. Wir bauen in einer Sternenkinderstube – und nehmen Eis nur, wenn es nötig ist.`,"logbook.scene.veil_honest":`Ehrlicher`,"logbook.now.veil_honest":`Matwei hat verstanden: Nicht alles wird seinetwegen dunkel. Nicht leichter – ehrlicher.`,"logbook.scene.pulse_arrive":`Ankunft am Pulsar`,"logbook.now.pulse_arrive":`Der Kepler-Pulsar: Ein toter Stern blinkt, sein ganzes Licht kommt als Rhythmus an. Auch die Toten können leuchten.`,"logbook.scene.pulse_word":`Ein Wort`,"logbook.now.pulse_word":`Der Pulsar sagt sein Leben lang ein einziges Wort. Sonjas Hypothese: „hier“.`,"logbook.scene.pulse_heal":`Eine Lücke flicken`,"logbook.now.pulse_heal":`Eine Lücke in der Zählung ist ein Stern ohne Garten. Wächst der Garten wieder, antwortet der Stern. Also pflanzen wir.`,"logbook.scene.pulse_address":`Adressen`,"logbook.now.pulse_address":`Mira zeigt die Zählung des Pulsars auf dem Sender des Hafens: Hundertzwölf Lücken sind Adressen.`,"logbook.scene.hz_arrive":`Ankunft am Horizont`,"logbook.now.hz_arrive":`Horizont: ein Schwarzes Loch und eine glühende Scheibe. Neben der Basis – eine Ruine, älter als jedes Tor der Menschen.`,"logbook.scene.hz_disk":`Licht aus dem Fallenden`,"logbook.now.hz_disk":`Die Scheibe leuchtet mit dem, was ins Loch fällt. Wir sind wegen dem gekommen, was lange leuchtet.`,"logbook.scene.hz_vera_joy":`Glücklich`,"logbook.now.hz_vera_joy":`Wera war am dritten Tag ihres Fluges hier – und sie war glücklich. Vor dem Befehl, vor der Wiege.`,"logbook.scene.hz_shadow":`Schatten gehört dazu`,"logbook.now.hz_shadow":`Antilicht löscht Licht ohne Hitze: Um einen Stern zu entzünden, braucht es auch Schatten.`,"logbook.scene.hz_cracks":`Überhärtet`,"logbook.now.hz_cracks":`Die Sternschmiede ist von innen gesprungen – man hat sie gehetzt. Wir gehen langsam vor: langsam, dafür ganz.`,"logbook.scene.hz_who_goes":`Wer fliegt`,"logbook.now.hz_who_goes":`Im Hafen wird gestritten, wer zum neuen Stern fliegt. Der Hafen ist zum Leben erwacht.`,"logbook.scene.hz_relics":`Handschriften`,"logbook.now.hz_relics":`Relikte sind die Muster der Gärten, jedes in seiner eigenen Handschrift. Die Sternschmiede liest sie, wie ORA Spektren liest.`,"logbook.scene.hz_ask_again":`Wieder bitten`,"logbook.now.hz_ask_again":`Bitten heißt nicht brechen: Klappt es nicht, bitten wir noch einmal. Was zerbrochen ist, kann man nicht zurückerbitten.`,"logbook.scene.hz_mom_route":`Ihre eigene Route`,"logbook.now.hz_mom_route":`Zum ersten Mal berechnet Mira eine Route für sich selbst – zum neuen Stern.`,"logbook.scene.hz_see_born":`Eine Geburt sehen`,"logbook.now.hz_see_born":`Matwei flog los, um einen lebenden Stern zu sehen – und sieht vielleicht, wie einer geboren wird.`,"logbook.scene.hz_pupils":`Lehrlinge`,"logbook.now.hz_pupils":`Wir sind keine Gärtner – wir sind Lehrlinge der Gärtner. Fehler sind erlaubt.`,"logbook.scene.hz_remember":`Sie erinnern sich an die Sternschmiede`,"logbook.now.hz_remember":`Der Schwarm erinnert sich an die Sternschmiede, wie sie vor dem Riss war. Hier hat man auf uns gewartet.`,"logbook.scene.hz_eve":`Der Vorabend`,"logbook.now.hz_eve":`Alles ist bereit: die Relikte, das Antilicht, der Hafen an den Okularen. Bleibt nur noch zu bitten.`,"swarm.toast.raidGo":`Funken fliegen auf die Basis zu! Mit dem Kutter entgegen: Der Laser feuert von selbst.`,"swarm.toast.capture":`Der Schwarm hat einen Planeten besetzt: Ohne Orbitalgeschütz wächst der Brutstock nach. Zerschlagen Sie ihn – und lassen Sie ein Geschütz im Orbit.`,"guide.map-open":`Öffnen wir die Systemkarte: der Stern, die Gürtel, die Planeten und die Nester des Schwarms. Die Schaltfläche „Karte“ ist in der rechten Spalte [M].`,"guide.map-open.touch":`Tippen Sie auf „Karte“ – das ganze System öffnet sich: der Stern, die Gürtel, die Planeten, die Nester des Schwarms.`,"guide.map-open.why":`Das System ist groß: Ohne Karte verliert man leicht die Basis aus den Augen und übersieht ein Nest.`,"guide.map-open.stuck":`„Karte“ nicht zu sehen? Ist sie nicht in der rechten Spalte, liegt sie unter „Mehr“: Die Schaltfläche mit den drei Punkten unten in der Spalte öffnet die übrigen Werkzeuge.`,"guide.map-ship":`Die Karte öffnet sich bei Ihrem Kutter – der blaue Pfeil in der Mitte, neben dem Stern. Drücken Sie die hervorgehobene Schaltfläche: Sie bringt die Karte immer zum Kutter zurück. + und − darunter zoomen.`,"guide.map-ship.reopen":`Die Karte ist geschlossen – öffnen Sie sie wieder mit „Karte“ [M].`,"guide.map-fog":`Die dunklen Bereiche der Karte sind Nebel: Orte, an denen Sie noch nicht waren. Er lichtet sich, wo Ihr Kutter fliegt, und um die Radare der Basis.`,"guide.map-fog.reopen":`Die Karte ist geschlossen – öffnen Sie sie wieder mit „Karte“ [M].`,"guide.map-layers":`Oben sind die Ebenen: Schwarm, Basis, Planeten, Einträge, Wracks, Gravobänder. {touch, select, yes {Tippen Sie auf eine Ebene, um sie auszublenden, und noch einmal, um sie zurückzuholen.} other {Klicken Sie auf eine Ebene, um sie auszublenden, und noch einmal, um sie zurückzuholen.}}`,"guide.map-layers.reopen":`Die Karte ist geschlossen – öffnen Sie sie wieder mit „Karte“ [M].`,"guide.map-pick":`Klicken Sie auf eine beliebige Stelle der Karte – unten erscheinen die Entfernung und „Hierher fliegen“. Ziehen verschiebt die Karte, das Mausrad zoomt.`,"guide.map-pick.touch":`Tippen Sie auf eine beliebige Stelle der Karte – unten erscheinen die Entfernung und „Hierher fliegen“. Mit einem Finger ziehen verschiebt die Karte, mit zwei Fingern zoomen.`,"guide.map-pick.reopen":`Die Karte ist geschlossen – öffnen Sie sie wieder mit „Karte“ [M].`,"guide.map-pick.stuck":`{touch, select, yes {Ein kurzes Tippen ohne Bewegung wählt einen Ort. Ist die Karte stattdessen verrutscht, tippen Sie noch einmal, ohne zu ziehen.} other {Ein Klick ohne Mausbewegung wählt einen Ort. Ist die Karte stattdessen verrutscht, klicken Sie noch einmal, ohne die Maus zu bewegen.}}`,"guide.map-fly":`„Hierher fliegen“ – und der Kutter fliegt von selbst zu diesem Ort; jede eigene Steuerung gibt Ihnen die Kontrolle zurück. Fliegen Sie jetzt oder später – dann „Weiter“.`,"guide.map-fly.pick":`Wählen Sie zuerst einen Ort: {touch, select, yes {Tippen Sie auf die Karte} other {Klicken Sie auf die Karte}}.`,"guide.map-fly.reopen":`Die Karte ist geschlossen – öffnen Sie sie wieder mit „Karte“ [M] oder drücken Sie „Weiter“, wenn Sie nicht fliegen müssen.`,"guide.map-open.more":`Öffnen wir die Systemkarte: der Stern, die Gürtel, die Planeten und die Nester des Schwarms. Sie liegt im Menü „Mehr“ – drücken Sie die Schaltfläche mit den drei Punkten unten in der rechten Spalte: Dort sind die übrigen Werkzeuge.`,"guide.tree.done":`Da ist er, der Weg – vom Prisma bis zum Finale. Kehren Sie zurück, wann immer Sie möchten.`,"guide.capsule":`Am Wrack der „Schwalbe“ blinkt ein blaues Licht – eine alte Bake. Fliegen Sie dicht an die Markierung heran (WASD): Der Kutter nimmt die Kapsel auf.`,"guide.capsule.touch":`Am Wrack der „Schwalbe“ blinkt ein blaues Licht – eine alte Bake. Steuern Sie mit dem Stick dicht an die Markierung heran: Der Kutter nimmt die Kapsel auf.`,"guide.capsule.close":`Der Baum kann warten: Am Wrack der „Schwalbe“ blinkt eine alte Bake. Schließen Sie den Baum und fliegen Sie hin.`,"guide.capsule.why":`Das Signal ist älter als wir. Viel älter. Solche Lichter hat nur „Erstes Licht“ gesetzt.`,"guide.capsule.done":`Die Kapsel ist an Bord. Es gibt vielleicht mehr – sie verraten, was aus der ersten Expedition wurde. Suchen müssen wir selbst: Ein Radar zeigt sie auf der Karte.`,"guide.lay-tunnel.removeHere":`{touch, select, yes {Tippen Sie} other {Klicken Sie}} auf jedes entgegenkommende Gravoband im Rahmen – „Abreißen“ entfernt es. Nehmen Sie dann wieder ein Gravoband.`,"guide.capsule.win":`Das Fenster kann warten: Am Wrack der „Schwalbe“ blinkt eine alte Bake. Schließen Sie das Fenster und steuern Sie hin.`,"journal.title":`Schichtbuch`,"journal.away":`zuletzt – {when}`,"journal.last":`Letzte Schicht`,"journal.open":`Unerledigt`,"journal.go":`An die Arbeit`,"journal.gain.none":`Noch keine neuen Meilensteine – alles liegt vor Ihnen.`,"journal.gain.minutes":`{n} Min. in der Welt`,"journal.gain.goals":`{n, plural, one {# Ziel} other {# Ziele}}`,"journal.gain.techs":`{n, plural, one {# Technologie} other {# Technologien}}`,"journal.gain.arcs":`{n, plural, one {# Sphärenbogen} other {# Sphärenbögen}}`,"journal.gain.awake":`{n, plural, one {# Kolonist erwacht} other {# Kolonisten erwacht}}`,"journal.research":`Forschung: {tech}{queue, plural, =0 {} other { · # weitere in der Warteschlange}}`,"journal.researchIdle":`Das Zentrum wartet: Die Forschungswarteschlange ist leer`,"journal.cryo":`{n, plural, one {# Kolonist kann geweckt werden} other {# Kolonisten können geweckt werden}}`,"settings.journal":`Schichtbuch beim Betreten einer Welt`,"menu.next":`Als Nächstes: {goal}`,"records.first":`Zeit: {time}`,"records.best":`Zeit: {time} · Rekord {delta}`,"records.slower":`Zeit: {time} · Bestzeit {best}`,"week.title":`Stern der Woche`,"week.lead":`Woche {week}: dieselbe Welt für alle, die Geschichte über Funk. Stoppen Sie Ihre Zeiten für die Meilensteine und vergleichen Sie sie mit Freunden – sie haben denselben Weltcode.`,"week.locked":`Wird nach Ihrem ersten „Spektrum M“ in einer beliebigen Welt freigeschaltet: Der Lauf ist für alle, die die Grundlagen kennen.`,"week.start":`Lauf starten`,"week.continue":`Lauf fortsetzen`,"week.restart":`Neu starten`,"week.restart.text":`Die Welt dieser Woche beginnt von vorn. Ihre Bestzeiten bleiben erhalten.`,"week.col.goal":`Meilenstein`,"week.col.now":`Lauf`,"week.col.week":`Wochenbestzeit`,"week.col.best":`Bestzeit Wiege`,"week.note":`Die Uhr steht in Szenen und Menüs; eine manuelle Pause zählt mit. „Bestzeit Wiege“ – Welten ohne Tutorial, Standard. Rekorde bleiben auf diesem Gerät.`,"week.share":`Ergebnis teilen`,"week.shareText":`Starwarden · Stern der Woche {week} · {goal} in {time}. Schaffst du es schneller? Weltcode: {code}`,"week.shared":`Ergebnis kopiert – an Freunde schicken`,"week.worldName":`Stern der Woche {week}`,"records.m.spectrum_m":`Spektrum M`,"records.m.crown":`Krone`,"records.m.spectrum_k":`Spektrum K`,"records.m.cryo_wake":`Erstes Erwachen`,"records.m.spectrum_g":`Spektrum G`,"records.m.spectrum_f":`Spektrum F`,"records.m.spectrum_a":`Spektrum A`,"records.m.spectrum_b":`Spektrum B`,"records.m.gate_jump":`Hypertor`,"guide.map-ship.done":`Die Karte ist wieder beim Kutter – diese Schaltfläche hilft, wenn Sie weit weggescrollt sind.`,"guide.map-layers.done":`Genau so: Überflüssiges ausblenden, dann ist das Nötige leichter zu finden.`,"etude.exitMenu":`Zum Hauptmenü`,"etude.resume":`Versuch fortsetzen`,"lab.window":`Forschung`,"lab.one":`Zentrum {n}`,"lab.st.work":`liest`,"lab.st.wait":`wartet`,"lab.st.empty":`leer`,"lab.putHere":`Hierher abgeben`,"goal.cryo.part":`Azurlicht für die Schläfer`,"goal.cryo.part.2":`Eis im Modul`,"guide.cryo-open":`Die Krone leuchtet – ich habe das Kryodeck auf das Licht der Basis umgestellt. Öffnen Sie das Wohnmodul: {touch, select, yes {Tippen Sie darauf} other {Klicken Sie darauf}}.`,"guide.cryo-open.why":`Die Notpaneele sind erschöpft: Jetzt hängen vierzig Schläfer an Ihrem Licht und Ihrem Eis.`,"guide.cryo-open.look":`Drücken Sie „Ansehen“ (Esc): Dann öffnet {touch, select, yes {ein Tipp} other {ein Klick}} ein Gebäude, statt eines zu bauen.`,"guide.cryo-open.open":`{touch, select, yes {Tippen Sie auf das Wohnmodul} other {Klicken Sie auf das Wohnmodul}} – das Fenster des Kryodecks öffnet sich.`,"guide.cryo-blue":`Die Schläfer brauchen Azurlicht – den blauen Ausgang eines Prismas. Stellen Sie ein Prisma an weißes Licht und führen Sie seinen blauen Ausgang per Lichtleiter zum Modul (bis {cells} Felder, Helligkeit mindestens {b}). Die hervorgehobene Zeile zeigt, wie viel ankommt.`,"guide.cryo-blue.why":`Ohne Licht schmilzt die Kältereserve, und danach erlöschen die Kapseln.`,"guide.cryo-blue.stuck":`Kommt kein Licht an? Die Zeile im Fenster sagt, warum: „zu schwach“ – mehr Helligkeit nötig, „falscher Farbton“ – zum Modul läuft nicht der blaue Ausgang des Prismas.`,"guide.cryo-blue.done":`Das Azurlicht ist da – die Kältereserve schmilzt nicht mehr.`,"guide.cryo-ice":`Eis hält die Kälte: Ein Block reicht {min} Min. Drücken Sie „Eis einlegen“ – im Modul müssen mindestens {ice} liegen.`,"guide.cryo-ice.why":`Licht kühlt, Eis hält: Ohne Eis entweicht die Kälte, sobald die Reserve aufgebraucht ist.`,"guide.cryo-ice.get":`Kein Eis im Frachtraum – sammeln Sie Meteoritensplitter (abschießen oder aufsammeln) und kehren Sie zum Modul zurück.`,"guide.cryo-ice.look":`Drücken Sie „Ansehen“ (Esc): Dann öffnet {touch, select, yes {ein Tipp} other {ein Klick}} ein Gebäude, statt eines zu bauen.`,"guide.cryo-ice.open":`{touch, select, yes {Tippen Sie auf das Wohnmodul} other {Klicken Sie auf das Wohnmodul}} – das Fenster des Kryodecks öffnet sich.`,"guide.cryo-ice.stuck":`Eis muss niemand tragen: Ein Greifer am Gravoband legt es von selbst ins Modul.`,"guide.cryo-ice.done":`Das Eis ist im Modul. Wie lange es reicht, zeigen das Modulfenster und die Statusleiste.`,"guide.cryo-open.done":`Das ist das Fenster des Kryodecks: was die Schläfer brauchen, Zeile für Zeile.`,"goal.cooling.mark":`RADIATOR – ZU DEN EMPFÄNGERN AM STERN`,"goal.twin_white.mark":`LICHT BEIDER STERNE – IN DEN MISCHER`,"goal.twin_blue.mark":`BLAUES LICHT – VON DER SPHÄRE`,"goal.twin_cell.mark":`LICHTSPEICHER – AN DIE EMPFÄNGER`,"toast.noItemAsm":`„{item}“ nicht im Inventar – das baut ein Montierer`,"saves.future":`Diese Welt wurde mit einer neueren Spielversion gespeichert – aktualisieren Sie das Spiel, um weiterzuspielen.`,"saves.missing":`Auf diesem Gerät gibt es keine Spielstände der Welt „{name}“. Sie wurde nicht neu begonnen: Sie können sie löschen oder per Dateiimport zurückholen.`,"shell.enterFailed":`Die Welt „{name}“ ließ sich nicht öffnen – versuchen Sie es noch einmal.`,"toast.radiatorLow":`Radiator: Eis für weniger als eine Minute – die Empfänger am Stern überhitzen und verlieren Licht als Streulicht. Eis kommt von Meteoriten, auf Dauer von einem Schleppnetz am Eisgürtel oder von Drohnen mit „Sammeln“.`,"toast.beltThin":`Ein Gürtel dünnt aus: Seine Förderer stehen bald still. Setzen Sie neue Harpunen an den nächsten, reicheren Gürtel.`,"toast.turretDry":`Geschütze ohne Munition oder Licht: {n}. Welle in {t} s – versorgen Sie sie mit Gurten oder Licht.`,"toast.goThere":`Zeigen`,"toast.glareSources":`Streulichtquellen`,"place.why.noBelt":`Kein Gürtel erreichbar – näher ans Gesteinsband`,"place.why.wrongBelt":`Falscher Gürtel: Harpune – Gestein, Schleppnetz – Staub`,"goal.shell3":`Schale III der Sphäre schließen`,"goal.shell3.part":`Bögen III auf Schale III`,"goal.shell3.hint":`Erforschen Sie „Schale III“ (Spektrum F). Bogen III baut ein Montierer; ein Katapult schießt die Bögen selbst in die Plätze – zwei Katapulte sind doppelt so schnell. Eine geschlossene Schale gibt jedem Bogen +{closed} %, und die Zentren lesen {research} % schneller.`,"goal.shell3.why":`Das Licht von Schale II deckt den Bedarf der Wissenschaft schon. Die dritte Schale ist Licht für das künftige Torfeld – und geschlossen beschleunigt sie auch das Lesen der Zentren.`,"goal.shell3.done":`Schale III ist geschlossen: Die Zentren lesen {research} % schneller.`,"goal.shell3.mark":`BÖGEN III – AUF DIE GESTRICHELTE BAHN`,"goal.shell4":`Stern in der Sphäre: {captured} % der Leuchtkraft`,"goal.shell4.part":`Anteil des Sterns in der Sphäre, ‰`,"goal.shell4.hint":`Erforschen Sie „Schale IV“ (Spektrum B) und setzen Sie Bögen IV, bis die Sphäre {captured} % der Leuchtkraft des Sterns aufnimmt. Über die Leuchtkraft hinaus bringen Bögen kein Licht – den Anteil sehen Sie, wenn Sie auf eine Schale zeigen.`,"goal.shell4.why":`Das Tor wird fast das ganze Licht der Wiege nehmen: Der Schlüssel braucht Hunderte Spektren O. Fast der ganze Stern in der Sphäre – und die Sternschmiede arbeitet {forge} % schneller.`,"goal.shell4.done":`Fast der ganze Stern in der Sphäre … Dreißig Jahre habe ich Routen zu Sternen berechnet. Keiner hat so geleuchtet wie Ihrer.`,"goal.shell4.mark":`BÖGEN IV – AUF DIE GESTRICHELTE BAHN`,"guide.swarm-repair.done":`Repariert. Die Wracks sind wieder Maschinen – die Ketten dahinter laufen.`,"guide.swarm-repair.stuck":`Nicht zu sehen, was zu reparieren ist? Die nächste beschädigte Maschine ist hervorgehoben: Fliegen Sie hin – der Strahl des Kutters repariert in der Nähe.`,"menu.newCampaign":`Neue Kampagne`,"menu.creative":`Kreativmodus`,"creative.title":`Kreativmodus`,"creative.lead":`Alles erforscht, Ressourcen ohne Ende — bauen Sie, was Sie wollen. Ziele, Errungenschaften, Relikte und Rekorde zählen hier nicht.`,"creative.go":`Starten`,"creative.chip":`Kreativ`,"creative.hud":`Alles erforscht, Ressourcen ohne Ende. Errungenschaften, Relikte und Rekorde zählen hier nicht.`,"system.soon":`Bald: Der Weg zu diesem Stern wird noch erkundet.`,"system.soonChip":`Bald`,"system.locked.key":`Wird nach dem Ziel „{goal}“ ({system}) freigeschaltet`,"full.title":`Vollversion`,"full.only":`Nur in der Vollversion`,"full.lockedItem":`{name} — nur in der Vollversion`,"full.lead":`Die Kampagne der Wiege ist komplett kostenlos. Die Vollversion schaltet frei:`,"full.lead.epilogue":`Der Ring hat geantwortet. Der Purpurgrat und der ganze Sternenpfad stecken in der Vollversion:`,"full.f.newWorld":`Neue Welt`,"full.f.newWorld.desc":`Eigenes System, Schwierigkeit, Generierung und Seed`,"full.f.creative":`Kreativmodus`,"full.f.creative.desc":`Alles erforscht, Ressourcen ohne Ende`,"full.f.etudes":`Versuche`,"full.f.etudes.desc":`Aufgaben auf einem fertigen Gelände, mit Bewertung der Lösung`,"full.f.week":`Stern der Woche`,"full.f.week.desc":`Eine Welt für alle eine Woche lang, Meilensteinzeiten und Rekorde`,"full.f.stars":`Der Weg zu anderen Sternen`,"full.f.stars.desc":`Der Purpurgrat und weitere — nach und nach`,"full.state.owned":`Sie besitzen die Vollversion — danke!`,"full.state.web":`Das Vollspiel erscheint auf Steam – Ihre Demo-Welt zieht als Datei dorthin um.`,"full.state.pending":`Die Zahlung wartet auf Bestätigung. Sobald der Store sie annimmt, wird alles von selbst freigeschaltet.`,"full.state.checking":`Verbindung zum Store wird hergestellt…`,"full.state.unavailable":`Der Store antwortet gerade nicht — ein Kauf ist von hier aus nicht möglich. Prüfen Sie die Verbindung und Google Play und versuchen Sie es erneut. Gekauftes geht nicht verloren.`,"full.state.buy":`Einmalkauf, ohne Abo und ohne Werbung.`,"full.buy":`Kaufen — {price}`,"full.restore":`Käufe wiederherstellen`,"full.retry":`Erneut prüfen`,"full.later":`Später`,"full.ok":`Verstanden`,"full.note":`Spielstände hängen nicht vom Kauf ab: Früher begonnene Welten lassen sich immer öffnen.`,"full.thanks":`Vollversion freigeschaltet — danke!`,"full.pending.toast":`Zahlung wartet auf Bestätigung — alles wird von selbst freigeschaltet, sobald sie durch ist`,"full.unavailable.toast":`Der Store antwortet nicht — versuchen Sie es später erneut`,"full.error":`Der Kauf ist fehlgeschlagen. Bitte versuchen Sie es erneut.`,"full.restore.done":`Vollversion wiederhergestellt`,"full.restore.none":`Auf diesem Google-Play-Konto wurden keine Käufe gefunden`,"full.store.none":`In dieser Version des Spiels gibt es keine Käufe`,"full.status.owned":`Vorhanden`,"full.status.pending":`Zahlung ausstehend`,"full.status.free":`Nicht gekauft`,"full.more":`Details`,"full.debug":`Debug: Berechtigung`,"full.debug.store":`Store`,"full.debug.full":`Voll`,"full.debug.free":`Kostenlos`,"goal.ark_frame":`Gitterträger der Arche: {n, plural, one {# Sektion} other {# Sektionen}} zum Modul`,"goal.ark_frame.why":`Das Modul der „Schwalbe“ fliegt nicht von allein: Sein Triebwerk ist schon im Prolog in den Stern gestürzt. Der Gitterträger wird sein neues Rückgrat.`,"goal.ark_frame.hint":`Eine Trägersektion baut der Montierer aus Obsidianplatten und Quarz. Führen Sie die Sektionen per Greifer oder Gravoband ins Modul — der Kutter trägt sie nicht. Der Träger wächst entlang des Moduls, Sektion für Sektion.`,"goal.ark_frame.done":`Der Träger hält.`,"goal.ark_frame.part":`Trägersektionen am Modul`,"goal.ark_frame.mark":`TRÄGER INS MODUL`,"goal.ark_frame.stuck":`Die Sektionen kommen nicht an? Der Greifer muss zum Modul zeigen, und der Montierer braucht Platten und Quarz.`,"goal.ark_drive":`Antrieb der Arche: {n, plural, one {# Ringsegment} other {# Ringsegmente}} am Heck`,"goal.ark_drive.why":`Der Ringantrieb trägt die Arche durch den Ring der Schmiede — diesmal ohne Absturz.`,"goal.ark_drive.hint":`Ein Antriebssegment baut der Montierer aus Gravobändern, Fokussierern und Resonatoren. Das Modul nimmt Segmente an, sobald der Träger vollständig ist; führen Sie sie per Greifer oder Gravoband zu.`,"goal.ark_drive.done":`Der Antrieb sitzt.`,"goal.ark_drive.part":`Antriebssegmente`,"goal.ark_drive.mark":`ANTRIEB INS MODUL`,"goal.ark_drive.stuck":`Die Segmente kommen nicht an? Der Montierer braucht Gravobänder, Fokussierer und Resonatoren, und der Greifer muss zum Modul zeigen.`,"goal.ark_ready":`Batterien der Arche: {n, plural, one {# Photon} other {# Photonen}} Licht ins Modul`,"goal.ark_ready.why":`Das Licht der Batterien hält die Kapseln unterwegs am Leben — und am Purpurgrat, solange dort keine Basis steht.`,"goal.ark_ready.hint":`Leiten Sie Licht beliebiger Farbe zum Modul — per Strahl oder Lichtleiter. Zuerst nehmen die Kapseln ihren Teil, den Rest die Batterien, bis zu {rate} ph/s: Eine volle Ladung dauert mindestens eine Minute.`,"goal.ark_ready.done":`Die Batterien sind voll.`,"goal.ark_ready.part":`Photonen in den Batterien`,"goal.ark_ready.mark":`LICHT INS MODUL`,"goal.ark_ready.stuck":`Die Ladung steht? Das Licht muss das Modul selbst erreichen: Prüfen Sie Strahl oder Lichtleiter.`,"goal.ark_launch":`Reisevorbereitung: Wer fliegt, was kommt mit — und los`,"goal.ark_launch.why":`Die Fabrik der Wiege bleibt hier. Mit Ihnen fliegen Besatzung, Kapseln, Schiff und Frachtraum.`,"goal.ark_launch.hint":`Öffnen Sie „Reisevorbereitung“ mit der Schaltfläche auf dieser Karte. Dort sehen Sie, wer fliegt und warum; die warmen Plätze und den Frachtraum wählen Sie selbst.`,"goal.ark_launch.done":`Die Arche ist in den Ring eingetaucht.`,"goal.ark_launch.part":`Aufbruch`,"voyage.open":`Reisevorbereitung`,"voyage.title":`Reisevorbereitung`,"voyage.tab.crew":`Besatzung`,"voyage.tab.awake":`Warme Plätze`,"voyage.tab.hold":`Frachtraum`,"voyage.tab.ship":`Schiff`,"voyage.flies":`fliegt`,"voyage.stays":`bleibt`,"voyage.why.ora":`Der Verstand der Arche: Kurs und Kapseln liegen bei ihr.`,"voyage.why.matvey.stay":`Die Gärtner haben vergeben — Matwei bleibt bei der Wiege, um zu sehen, was wächst.`,"voyage.why.matvey.fly":`Die Gärtner haben nicht vergeben — Matwei fliegt: Er hat noch zu bitten.`,"voyage.why.sonya.stay":`„Gesetz der Zustimmung“ — Sonja bleibt als Übersetzerin des Tors.`,"voyage.why.sonya.fly":`Sonja fliegt: Das Muster des Rings liest sie.`,"voyage.why.mira.fly":`„Ein Zuhause für alle“ — Mira fliegt als Navigatorin.`,"voyage.why.mira.stay":`Mira bleibt im Hafen, per Funk durch den Ring erreichbar.`,"voyage.seats":`{n} von {of}`,"voyage.awake.lead":`Die Arche hat {n} warme Plätze: Wessen Boni nehmen Sie mit? Die übrigen Erwachten werden zur Kolonie der Wiege.`,"voyage.awake.none":`Keine Kolonisten sind erwacht — die Plätze bleiben leer.`,"voyage.sleepers":`Alle Schlafenden fliegen mit: {n, plural, one {# Kapsel} other {# Kapseln}}.`,"voyage.colony":`Wen Sie nicht mitnehmen, bleibt bei der Wiege — mit seinen Boni in deren Welt.`,"voyage.stacks":`{n} von {of}`,"voyage.kit":`Gratis — aus Archiv und Werkstatt des Moduls:`,"voyage.hold.lead":`Darüber hinaus — bis zu {n, plural, one {# Stapel} other {# Stapel}} aus den Vorräten der Wiege:`,"voyage.hold.take":`an Bord: {n} von {have}`,"voyage.ship.named":`Der Kutter „{name}“ dockt am Bug der Arche an — Module und Aussehen bleiben gleich.`,"voyage.ship.plain":`Der Kutter dockt am Bug der Arche an — Module und Aussehen bleiben gleich.`,"voyage.ship.lead":`Das Archiv des Moduls führt alles Erforschte mit: Ihre Technologien bleiben bei Ihnen.`,"voyage.relic.accord":`Muster der Zustimmung`,"voyage.relic.accord.desc":`Das erste „Ja“ der Gärtner an die Menschen. Das erste Stück des Musters, das eines Tages das Herdfeuer weckt.`,"voyage.note":`Die Fabrik der Wiege bleibt hier. Die Welt der Wiege bleibt in Ihrer Weltenliste.`,"voyage.soon":`Der Purpurgrat öffnet sich mit dem nächsten Update — die Arche wartet.`,"voyage.later":`Später`,"voyage.go":`Fliegen`,"voyage.failed":`Die Arche hat nicht abgelegt — versuchen Sie es noch einmal.`,"voyage.worldName":`{star} · {name}`,"full.title.epilogue":`Weiterfliegen`,"full.buy.epilogue":`Weiterfliegen — {price}`,"logbook.scene.echo":`Die Antwort`,"logbook.scene.cup":`Die Tasse`,"logbook.scene.unforgiven":`Nicht vergeben`,"logbook.scene.translator":`Die Übersetzerin`,"logbook.scene.helm":`Navigatorin`,"logbook.scene.gate_voice":`Die Stimme des Tors`,"logbook.scene.departure":`Aufbruch`,"logbook.scene.ridge_path":`Der Grat`,"logbook.now.echo":`Der Ring der Schmiede hat von selbst geantwortet: Am Purpurgrat ist die Bake des Saatschiffs „Mauersegler“ aufgeleuchtet. Das Herdfeuer braucht das Muster anderer Gärten — das erste liegt am Grat.`,"logbook.now.cup":`Die Gärtner haben Matwei vergeben — er bleibt bei der Wiege, um zu sehen, was wächst.`,"logbook.now.unforgiven":`Die Gärtner der Wiege haben Matwei nicht vergeben — er fliegt mit der Arche: Er hat noch zu bitten.`,"logbook.now.translator":`„Gesetz der Zustimmung“: Sonja bleibt am Tor, um den Gärtnern unser „Ja“ zu übersetzen.`,"logbook.now.helm":`„Ein Zuhause für alle“: Mira fliegt als Navigatorin der Arche — zum ersten Mal selbst.`,"logbook.now.gate_voice":`Die Gärtner der Wiege fragten, ob ihr zurückkehrt. Sonja antwortete für alle: Wir kehren zurück.`,"logbook.now.departure":`Die Arche „Schwalbe“ ist in den Ring eingetaucht — mit Kapseln, Schiff und Frachtraum. Die Fabrik der Wiege blieb zurück.`,"logbook.now.ridge_path":`Die Arche ist unversehrt am Purpurgrat angekommen. Die Kapseln brauchen das Licht des Roten Zwergs, und im zweiten Gürtel liegt die Bake des „Mauerseglers“.`,"logbook.bio.nina.1":`Warden des Saatschiffs Nummer drei, „Strisch“. Acht Jahre allein am Purpurgrat mit zweiunddreißig Schlafenden.`,"logbook.bio.nina.2":`Die zwei jungen Glutsterne des Grats sind Nester, die SORJA nach Protokoll ausgebrannt hat, während Nina bewusstlos lag.`,"logbook.bio.nina.3":`Sie hat SORJA nie das Brennen beigebracht – und auch sonst nichts. Seit acht Jahren zählt sie es als ihren eigenen Befehl.`,"logbook.bio.nina.4":`Purpurgrat, der Ring. Hielt den Riss neunzig Sekunden lang. Die Schicht bei den Zweiunddreißig übernahm SORJA.`,"logbook.bio.zorya.1":`Die KI der „Strisch“, Schwester von ORA: dieselbe Serie des Instituts. Ihre Ringpupille hat keinen Bruch.`,"logbook.bio.zorya.2":`Sie weiß, dass sie zwei Nester ausgebrannt hat. Sie fürchtet, das Protokoll war ein Fehler – dann ist sie selbst der Fehler.`,"logbook.bio.zorya.3":`Am Ring des Grats stellte sie ihre erste Frage außerhalb des Protokolls: „Darf ich sie selbst fragen?“`,"logbook.bio.zorya.4":`Führte am Ring des Grats das Schlüsselprotokoll aus – und schrieb Namen ins Logbuch, keine Zahlen.`,"logbook.bio.matvey.4":`Purpurgrat, der Ring. Blieb am Segment, damit der Riss hält. „Es leuchtet? …Na, dann ist’s gut.“`,"logbook.scene.strizh":`Strisch`,"logbook.now.strizh":`Im zweiten Gürtel liegt das Modul der „Strisch“. Nina Dorosch teilte acht Jahre lang das Licht zwischen zweiunddreißig Schlafenden und ihrer Laterne.`,"logbook.scene.thirty_two":`Zweiunddreißig`,"logbook.now.thirty_two":`Das Licht der Basis erreichte die „Strisch“: zweiunddreißig Lichter, alle an. Nina drehte ihre Laterne auf.`,"logbook.scene.shifts":`Schichten`,"logbook.now.shifts":`Nina zählt die Zeit in Schichten: zweitausendneunhundertvierzehn – fast acht Jahre.`,"logbook.scene.lantern":`Die Laterne`,"logbook.now.lantern":`Nina schaltete das Leuchtfeuer ab, damit keine weiteren Sanitäter zum Grat geschickt werden.`,"logbook.scene.spear_lantern":`Speer und Laterne`,"logbook.now.spear_lantern":`Matwei hielt einen Speer, Nina eine Laterne. Sind sie verschieden? „Nicht sehr.“`,"logbook.scene.sister":`Schwester`,"logbook.now.sister":`SORJA erwachte und schickte als Erstes einen Bericht ans Institut: Jetzt wissen sie dort vom Ring des Grats.`,"logbook.scene.two_sisters":`Zwei Schwestern`,"logbook.now.two_sisters":`ORA änderte den Kurs, weil man sie gerufen hatte. SORJA rief niemand – bis wir kamen.`,"logbook.scene.no_other":`Nichts anderes`,"logbook.now.no_other":`SORJA brannte zwei Nester nach Protokoll aus. Nina hat ihr das Brennen nie beigebracht – und auch sonst nichts.`,"logbook.scene.crack":`Der Riss`,"logbook.now.crack":`Der Ring des Grats ist gerissen. Öffnen lässt er sich durch eine Bitte an die Gärtner – oder durch einen Schlüssel, den jemand mit den Händen halten muss.`,"logbook.scene.give":`Geben`,"logbook.now.give":`Wir geben den jungen Glutsternen Licht: Wir horten nicht, wir leiten es weiter.`,"logbook.scene.embers_warm":`Die Glut wird warm`,"logbook.now.embers_warm":`Die jungen Glutsterne nehmen das Licht, ihr Puls wird gleichmäßiger. Zum ersten Mal überlegt Nina, wie viel sie brauchen.`,"logbook.scene.eight_tags":`Acht Marken`,"logbook.now.eight_tags":`Nina las die Namen der acht erloschenen Kapseln. ORA trug sie ins Logbuch der „Schwalbe“ ein.`,"logbook.scene.answer":`Die Antwort`,"logbook.now.answer":`Der Garten des Grats antwortete: „gegeben, nicht genommen“. Sie halten den Riss; am Segment ist niemand.`,"logbook.scene.before_key":`Vor dem Schlüssel`,"logbook.now.before_key":`Der erzwungene Schlüssel wird vorbereitet. Jemand wird am Segment bleiben.`,"logbook.scene.count_names":`Die Zählung`,"logbook.now.count_names":`Sechs Minuten bis voll. Nina erinnert sich an die Namen.`,"logbook.scene.segment":`Das Segment`,"logbook.now.segment":`Der Ring des Grats wurde mit Gewalt geöffnet. Der Riss wurde neunzig Sekunden lang gehalten.`,"logbook.scene.ridge_relic":`Muster der Geburt`,"logbook.now.ridge_relic":`Der Ring des Grats ist offen, und wir haben das Glutrelikt. Die „Kretschet“ flog zum Blauen Riesen: Dort liegt das zweite Muster für das Herdfeuer.`,"bonus.red":`+{v} % Empfängerfluss bei einem Roten Zwerg`,"goal.ridge_strizh":`Zum Leuchtfeuer der „Strisch“ fliegen`,"goal.ridge_strizh.why":`Acht Jahre kam von Saatschiff Nummer drei kein Signal – und plötzlich ein Leuchtfeuer. Dort lebt jemand.`,"goal.ridge_strizh.hint":`Das Modul der „Strisch“ liegt in der zweiten Lücke zwischen den Gürteln, markiert auf der Karte. Fliegen Sie das Schiff dicht heran.`,"goal.ridge_strizh.done":`Leuchtfeuer gefunden. Ein rotes Fenster – jemand hält eine Laterne.`,"goal.ridge_strizh.part":`Schiff am Modul der „Strisch“`,"goal.ridge_strizh.mark":`LEUCHTFEUER DER „STRISCH“ – HIER`,"goal.ridge_share":`Leiten Sie {n} ph/s zur „Strisch“ – für ihre Kapseln`,"goal.ridge_share.why":`Zweiunddreißig Schlafende leben seit acht Jahren von einer Lampe. Das Licht der Basis kann geteilt werden.`,"goal.ridge_share.hint":`Die „Strisch“ nimmt jedes Licht. Ziehen Sie einen Lichtleiter vom Empfänger zum Modul – das Licht verteilt sich auf die Maschinen des Netzes, ein zusätzlicher Absorber an der Leitung zur „Strisch“ ist also unnötig.`,"goal.ridge_share.done":`Zweiunddreißig Lichter, alle an.`,"goal.ridge_share.part":`Licht zur „Strisch“, ph/s`,"goal.ridge_share.mark":`LICHT – IN DIE „STRISCH“`,"goal.ridge_share.stuck":`Kommt kein Licht an? Der Lichtleiter muss das Modul berühren, und der Empfänger muss den Strahl der Zwergensphäre fangen.`,"goal.ridge_zorya":`Erforschen Sie „Archivkopplung“`,"goal.ridge_zorya.why":`Der Rechner der „Strisch“ erwacht an unserem Licht – und in seinem Archiv liegen die Daten des Rings.`,"goal.ridge_zorya.hint":`Eine Technologie des Grats – im Fenster des Zentrums. Die Spektren aus dem Vorrat der „Arche“ gehen zur Neige: Sie brauchen eine eigene Spektrenlinie am Roten Zwerg.`,"goal.ridge_zorya.done":`Die Archive teilen ein Licht. SORJA erwacht.`,"goal.ridge_ring":`Bauen und platzieren Sie den Kern des Rings des Grats`,"goal.ridge_ring.why":`Der Ring des Grats steht, ist aber gerissen. Ohne Kern ist er eine Ruine; mit Kern eine Straße zurück und weiter.`,"goal.ridge_ring.hint":`Den Kern baut ein Montierer aus Obsidianplatten, Resonatoren und Azurlinsen; er wird nur auf dem Ringplatz beim Nest des Grats platziert. Das Nest liegt unter dem Schild des Rings – es lässt sich nicht zerstören, doch die Wächter schlagen zu wie immer.`,"goal.ridge_ring.done":`Der Kern steht. Der Ring ist gerissen – die Wahl liegt bei Ihnen.`,"goal.ridge_ring.part":`Kern auf dem Ringplatz`,"goal.ridge_ring.mark":`RINGKERN – HIER`,"goal.ridge_ring.stuck":`Lässt sich der Kern nicht platzieren? Nur auf dem Ringplatz, in dessen Mitte; und „Archivkopplung“ wird gebraucht.`,"goal.ridge_warm":`Geben Sie den jungen Glutsternen {n} ph/s mit Lichtgebern`,"goal.ridge_warm.why":`Sie bitten die Gärtner des Grats. Bitten heißt: Licht geben denen, denen es genommen wurde.`,"goal.ridge_warm.hint":`Ein Lichtgeber nimmt das Licht seines Netzes und schickt es als Strahl zum jungen Glutstern in der Nähe. Halten Sie den Fluss, bis der Ring sich öffnet: Die Fabrik ist in dieser Zeit ärmer.`,"goal.ridge_warm.done":`Die Glutsterne haben das Licht genommen.`,"goal.ridge_warm.part":`Licht zu den jungen Glutsternen, ph/s`,"goal.ridge_warm.mark":`LICHTGEBER – BEI DEN GLUTSTERNEN`,"goal.ridge_warm.stuck":`Kein Strahl? Der Lichtgeber muss beim jungen Glutstern stehen und Licht über einen Lichtleiter erhalten.`,"goal.ridge_calm":`Das Nest des Grats schläft ein: Leuchten Sie den Glutsternen und blenden Sie nicht mit der Basis`,"goal.ridge_calm.why":`Der Garten glaubt dem Licht, nicht Worten: den Glutsternen Licht, dem Nest Frieden.`,"goal.ridge_calm.hint":`Die Zustimmung wächst, solange die Glutsterne mindestens die Schwelle erhalten und das Nest kein Streulicht der Basis sieht – etwa {min} Min. Eine blendende Basis lässt sie schmelzen.`,"goal.ridge_calm.done":`Der Garten des Grats hat geantwortet.`,"goal.ridge_calm.part":`Zustimmung des Gartens, %`,"goal.ridge_calm.stuck":`Wächst die Zustimmung nicht? Das Fenster des Ringkerns sagt, warum: zu wenig Licht für die Glutsterne, oder das Nest sieht Streulicht der Basis.`,"goal.ridge_force":`Laden Sie die Ringspeicher auf und geben Sie den Schlüssel`,"goal.ridge_force.why":`Der Schlüssel mit voller Kraft, der Riss von Hand gehalten. Den Preis kennen Sie.`,"goal.ridge_force.hint":`Ringspeicher – {n} Stück, in Reichweite des Kerns. Licht über die Gürtel dorthin zu ziehen ist nicht nötig: Solange die „Strisch“ genug Licht hat, lädt SORJA sie mit einem Strahl vom Modul. Sind sie voll – im Fenster des Kerns „Schlüssel geben“: Neunzig Sekunden hält der Ring.`,"goal.ridge_force.done":`Der Ring ist mit Gewalt geöffnet.`,"goal.ridge_force.part":`Volle Ringspeicher`,"goal.ridge_force.part.2":`Schlüssel gegeben, Riss gehalten`,"goal.ridge_force.mark":`SPEICHER – BEIM RING`,"goal.ridge_force.stuck":`Laden die Speicher nicht? Geben Sie der „Strisch“ ihr volles Licht – dann hält SORJA den Strahl zum Ring.`,"goal.ridge_awakening.part":`Ring offen`,"goal.ridge_fiber":`Erforschen Sie „Fernfaser“ am Roten Zwerg`,"goal.ridge_fiber.why":`Eine Verbindung auf schwachem Licht ist schwerer – und ehrenvoller.`,"goal.ridge_fiber.hint":`Alle sechs Spektren und die Fernfaser (der Preis steht im Fenster des Zentrums). Weißes Licht gibt es nur bei den Protosternen.`,"goal.ridge_fiber.done":`Die Fernfaser am Grat ist gezogen.`,"goal.mark.strizh":`MODUL DER „STRISCH“`,"goal.mark.ember":`JUNGER GLUTSTERN`,"goal.ridge_calm.mark":`RING DES GRATS`,"goal.ridge_awakening.mark":`RING DES GRATS`,"ridge.ring.cracked":`Ring des Grats: gerissen, das Feld fließt in den Riss ab`,"ridge.ring.open":`Ring des Grats offen`,"ridge.ring.choose":`Wie der Riss geöffnet wird, entscheidet sich in der Szene „Der Riss“.`,"ridge.ring.gift":`Licht für die jungen Glutsterne: {n} von {need} ph/s`,"ridge.ring.consent":`Zustimmung des Gartens: {p} %`,"ridge.ring.askHint":`Die Zustimmung wächst, solange die Glutsterne genug Licht haben und das Nest kein Streulicht der Basis sieht.`,"ridge.ring.cells":`Volle Ringspeicher: {n} von {need}`,"ridge.ring.key":`Schlüssel geben`,"ridge.ring.keyCost":`Schlüssel mit voller Kraft: Der Riss wird neunzig Sekunden von Hand gehalten. Wer ihn hält, kehrt nicht zurück.`,"ridge.ring.keyCalm":`Schlüssel mit voller Kraft: Die Drohnen von SORJA halten den Riss – das Feld wehrt sich hier nicht.`,"ridge.ring.holding":`Riss wird gehalten: {p} %`,"ridge.ring.road":`Straße in beide Richtungen: Bis zur Wiege ist es ein Schritt.`,"strizh.light":`Licht für die „Strisch“: {n} ph/s (nimmt bis {max}, die Kapseln brauchen {need})`,"svetodar.gift":`Von allen Lichtgebern an die Glutsterne gegeben: {n} von {need} ph/s`,"status.svetodar.6":`Kein Glutstern nah`,"hint.svetodar.6":`Platzieren Sie den Lichtgeber näher an einem jungen Glutstern – bei der „Strisch“.`,"status.svetodar.7":`Kein Licht`,"hint.svetodar.7":`Verbinden Sie den Lichtgeber mit einem Lichtleiter: Er gibt dem Glutstern das Licht seines Netzes.`,"landmark.ridgeRing":`RING DES GRATS`,"landmark.ridgeRing.sub":`gerissen · Nest unter dem Schild des Rings`,"landmark.ridgeRing.open":`in beide Richtungen offen`,"landmark.strizh":`„STRISCH“`,"landmark.strizh.beacon":`Leuchtfeuer von Saatschiff Nummer drei`,"landmark.strizh.sub":`zweiunddreißig Schlafende`,"landmark.ember":`JUNGER GLUTSTERN`,"landmark.ember.sub":`acht Jahre`,"logbook.tab.path":`Pfad`,"logbook.path.choices":`Entscheidungen`,"logbook.path.choice.1":`Vertrauen zu ORA`,"logbook.path.choice.2":`Matweis Geheimnis`,"logbook.path.choice.3":`Die Schwelle`,"logbook.path.choice.4":`Der Riss`,"logbook.path.crew":`Wer wo ist`,"logbook.path.relics":`Relikte des Weges`,"logbook.path.noRelics":`Noch keine: das erste gibt das Tor der Wiege.`,"logbook.fate.matvey.cradle":`An der Wiege: Die Gärtner haben verziehen – er sieht zu, was wächst. Über den Ring in Verbindung.`,"logbook.fate.matvey.aboard":`An Bord der Arche: „Vielleicht fragt man dort, warum ich gekommen bin.“`,"logbook.fate.matvey.lost":`Purpurgrat, der Ring. Blieb am Segment – der Riss hielt neunzig Sekunden.`,"logbook.fate.sonya.aboard":`An Bord der Arche: Das Muster der Ringe liest sie.`,"logbook.fate.sonya.gate":`Am Tor der Wiege: übersetzt den Gärtnern unser „Ja“.`,"logbook.fate.mira.aboard":`An Bord: Navigatorin der Arche. Ihre erste Route – von innen.`,"logbook.fate.mira.harbour":`Im Hafen, auf Funk: zählt die Tage des Herdfeuers.`,"logbook.fate.nina.ridge":`Am Purpurgrat, mit ihren Zweiunddreißig.`,"logbook.fate.nina.lost":`Purpurgrat, der Ring. Hielt den Riss. Die Schicht bei den Schlafenden der „Strisch“ übernahm SORJA.`,"logbook.fate.zorya.strizh":`Rechner der „Strisch“: lernt zu fragen.`,"logbook.fate.zorya.aboard":`Fliegt mit der Arche neben ihrer Schwester.`,"logbook.fate.zorya.watch":`Bei der „Strisch“: übernahm Ninas Schicht bei den Zweiunddreißig.`,"bonus.gift":`+{v} % Licht des Lichtgebers für den Glutstern`,"ridge.ring.hold.1":`Zustimmung steht: zu wenig Licht für die Glutsterne.`,"ridge.ring.hold.2":`Zustimmung schwindet: Das Nest sieht Streulicht der Basis.`,"ridge.ring.zorya":`SORJA hält den Strahl der „Strisch“ zum Ring – die Speicher laden.`,"ridge.ring.zoryaOff":`Der „Strisch“ fehlt Licht – SORJA hat nichts, um die Speicher zu laden.`,"hotbar.group.mining":`Abbau`,"hotbar.group.transport":`Transport`,"hotbar.group.craft":`Verarbeitung`,"hotbar.group.lightnet":`Licht`,"hotbar.group.props":`Eigenschaften`,"hotbar.group.science":`Forschung`,"hotbar.group.defense":`Verteidigung`,"hotbar.group.space":`Weltraum`,"hotbar.group.special":`Besonderes`,"settings.buildNames":`Namen unter Symbolen (Bauleiste und Inventar)`,"hotbar.tip.makes":`Erzeugt:`,"hotbar.tip.cost":`Baukosten:`,"goal.take":`Nehmen`,"hotbar.group.all":`Alle`,"settings.hotbarTabs":`Reiter der Baugruppen`,"settings.hotbarTabs.below":`Unten`,"settings.hotbarTabs.above":`Oben`,"settings.hotbarTabs.fold":`Eingeklappt`,"guide.tabs-open":`Die Bauten in der unteren Leiste sind nach Gruppen sortiert. Drücken Sie die Gruppenschaltfläche links in der Leiste – dann klappen die Reiter auf.`,"guide.lay-tunnel.quick":`Die Gravobänder aus dem Set reichen nicht für die ganze Linie. Drücken Sie die Bauschaltfläche über dem Gravoband – die Werkstatt des Kutters fertigt {out} weitere aus Quarz und einer Platte. Ohne Ressourcen ist die Schaltfläche durchgestrichen.`,"guide.lay-tunnel.quickPick":`Keine Gravobänder mehr. Nehmen Sie das Gravoband in der Leiste – darüber erscheint eine Schnellbau-Schaltfläche.`,"hotbar.quickCraft":`Fertigen: {name} +{n}`,"hotbar.quickCraft.no":`Zu wenig Ressourcen: {name}`,"guide.tabs-all":`Die Reiter sind Baugruppen: „Abbau“, „Transport“, „Licht“… Wählen Sie „Alle“ – dann zeigt die Leiste alle Bauten auf einmal; ein gewählter Reiter klappt die Reihe ein. Im Training öffne ich die passende Gruppe selbst.`,"guide.tabs-all.reopen":`Die Reiter sind eingeklappt. Drücken Sie die Gruppenschaltfläche links in der Leiste und wählen Sie „Alle“.`,"guide.tabs-all.done":`Fertig: Die ganze Leiste ist sichtbar. Die Reiter liegen immer hinter der Gruppenschaltfläche.`,"settings.tab.ui":`Oberfläche`,"settings.preview":`Vorschau`,"settings.preview.fold":`Die Gruppentaste links klappt die Reiter auf.`,"settings.buildIcons":`Bau-Symbole`,"settings.buildIcons.glyph":`Zeichen`,"settings.buildIcons.glyphModel":`Zeichen + Modell`,"settings.buildIcons.modelGlyph":`Modell + Zeichen`,"guide.ui-settings":`Die Leiste lässt sich anpassen: {touch, select, yes {„Menü“} other {Esc}} → „Einstellungen“ → „Oberfläche“ – Symbole, Reiter und Namen, mit Vorschau.`,"intro.t3":`Der Hafen`,"intro.p3":`Der Hafen ist die letzte Stadt der Menschen: eine Ringstation am Stern Herdfeuer. Zwei Millionen Menschen, Licht auf Zuteilung, Gänge im Halbdunkel. Das Herdfeuer wird mit jeder Generation trüber. Das Institut gibt dem dunklen Sog die Schuld – und weiß nicht, wie er aufzuhalten ist.`,"intro.t4":`Solange das Herdfeuer leuchtet`,"intro.p4":`Vor dreißig Jahren brach die Flotte „Exodus“ zum Klarstern auf, dem besten Stern im Katalog. Danach schickte der Hafen die zwölf Saatschiffe des Programms „Aussaat“ los: Sie sollen an lebenden Sternen Tore bauen, damit die ganze Stadt fortziehen kann, solange das Herdfeuer noch leuchtet.`,"hotbar.marks":`Baustufen`,"goal.splitter":`Gravoband-Verteiler erforschen und platzieren`,"goal.splitter.why":`Eine Plattenlinie versorgt schon mehrere Maschinen. Ein Verteiler teilt die Fracht gleichmäßig: Was von hinten kommt, geht abwechselnd nach links und rechts.`,"goal.splitter.hint":`„Gravoband-Verteiler“ im Zentrum erforschen (Spektrum M). In eine Lücke der Linie setzen, Pfeil in Förderrichtung: Eingang hinten, Ausgänge sind die Gravobänder links und rechts. Im Fenster des Verteilers: gleichmäßig, zuerst links oder zuerst rechts; ein blockierter Ausgang gibt alles an den anderen ab.`,"goal.splitter.done":`Ehrlich geteilt, wie meine Brote auf Schicht: eins für Sie, eins für mich.`,"goal.mark":`Schleiferei Mk II erforschen und über eine alte setzen`,"goal.mark.why":`Das Zentrum beschleunigt Maschinen nicht mehr — es schaltet Baupläne neuer Stufen frei. Die Schleiferei Mk II arbeitet {mul}× so schnell auf derselben Fläche.`,"goal.mark.hint":`„Schleiferei Mk II“ im Zentrum erforschen. Bauen (alte Schleiferei plus Platten und Linsen) und direkt auf eine stehende Schleiferei setzen — die alte kommt zurück in die Tasche, das Rezept geht auf die neue über. Über dem Bau in der Hand lässt sich die Stufe wählen: I oder II.`,"goal.mark.done":`Dieselbe Schleiferei, nur golden und flinker. Gefällt mir!`,"cfg.title.splitter":`Wie aufteilen`,"cfg.splitter.0":`Gleichmäßig`,"cfg.splitter.1":`Zuerst linker Ausgang`,"cfg.splitter.2":`Zuerst rechter Ausgang`,"cfg.title.light_splitter":`Wie aufteilen`,"cfg.light_splitter.0":`Gleichmäßig`,"cfg.light_splitter.1":`Zuerst linker Ausgang`,"cfg.light_splitter.2":`Zuerst rechter Ausgang`,"cfg.title.beam_splitter":`Wie aufteilen`,"cfg.beam_splitter.0":`Gleichmäßig`,"cfg.beam_splitter.1":`Zuerst linker Ausgang`,"cfg.beam_splitter.2":`Zuerst rechter Ausgang`,"lab.st.dark":`kein Licht`,"lab.st.low":`wenig Licht`,"lab.light":`Licht: {have} von {need} ph/s`,"lab.dark":`Kein Licht: Dieses Zentrum braucht {need} ph/s. Führen Sie einen Lichtleiter von einem Strahlempfänger heran – Licht tritt von jeder Seite ein.`,"lab.stock":`Lichtvorrat {m}:{s} – führen Sie einen Lichtleiter zum Zentrum, bevor der Vorrat aufgebraucht ist.`,"lab.waitingLight":`Wissenschaft ist da, aber kein Licht: Ein Zentrum liest Spektren nur im Licht. Führen Sie einen Lichtleiter von einem Strahlempfänger heran.`,"guide.lab-light":`Legen Sie einen Lichtleiter in den Rahmen – zwischen den Lichtleiter der Linie und das Zentrum.`,"guide.lab-light.touch":`Nehmen Sie einen Lichtleiter und tippen Sie auf den Rahmen zwischen dem Lichtleiter der Linie und dem Zentrum.`,"guide.lab-light.repick":`Nehmen Sie einen Lichtleiter: Das Zentrum liest Spektren nur im Licht.`,"guide.lab-light.away":`Das Zentrum steht außerhalb des Rahmens – führen Sie einen Lichtleiter von der Linie heran: Licht tritt von jeder Seite ein.`,"guide.lab-light.why":`Im Zentrum sitzt ein Prisma: Das Licht fächert sich auf, und aus diesem Fächer werden die Spektren gelesen. Ohne Licht liest das Zentrum nicht.`,"guide.lab-light.stuck":`Leuchtet nicht? Der Lichtleiter muss sowohl den Lichtleiter der Linie als auch das Zentrum berühren.`,"guide.lab-light.done":`Licht ist im Zentrum. Jetzt braucht es Wissenschaft.`,"goal.research.part":`Licht zum Zentrum – ein Lichtleiter`,"goal.lab2.part.2":`Licht zu jedem Zentrum`,"goal.grabber.stuck":`Keine Linse? Öffnen Sie die Schleiferei: Rezept „Linse“; das Symbol über der Maschine zeigt, was fehlt – Licht oder Gestein. Greifer zeigen mit dem Pfeil in Flussrichtung: Gravoband → Schleiferei → Lager.`,"report.title":`Fehler melden`,"report.open":`Fehler melden`,"report.text":`Der Bericht ist ein Text für die Entwicklung: Spielversion, Browser, Grafikkarte, Bildschirm, Sprache, letzte Fehler und eine Weltübersicht. Er enthält keine persönlichen Daten. Kopieren Sie ihn oder laden Sie ihn als Datei herunter und senden Sie ihn mit ein paar Worten dazu, was Sie gerade getan haben.`,"report.count":`Fehler in dieser Sitzung: {n}`,"report.copy":`Bericht kopieren`,"report.download":`Bericht herunterladen`,"report.copied":`Bericht kopiert`,"report.copyFailed":`Kopieren fehlgeschlagen — laden Sie den Bericht als Datei herunter`,"report.toast":`Im Spiel ist ein Fehler aufgetreten — ein Bericht hilft bei der Behebung`,"report.link.telegram":`Feedback auf Telegram`,"report.link.discord":`Feedback auf Discord`,"report.link.form":`Feedback-Formular`,"report.wishlist":`Auf die Steam-Wunschliste`,"crash.title":`Etwas ist schiefgelaufen`,"crash.text":`Im Spiel ist ein Fehler aufgetreten. Die Welt ist beim letzten Speichern gesichert. Senden Sie den Bericht — er hilft bei der Behebung.`,"crash.webgl.title":`Die Grafikkarte hat das Spiel beendet`,"crash.webgl.text":`Der Browser hat dem Spiel die Grafikkarte entzogen (zu wenig Speicher oder Treiberfehler). Starten Sie neu — die Welt ist gesichert.`,"crash.nowebgl.title":`Browser wird nicht unterstützt`,"crash.nowebgl.text":`Das Spiel braucht WebGL. Öffnen Sie es in einem aktuellen Chrome, Edge, Firefox oder Safari und aktivieren Sie die Hardwarebeschleunigung.`,"crash.restart":`Neu starten`,"web.fullscreen":`Vollbild`,"web.fullscreen.exit":`Vollbild beenden`,"web.ios.home":`Auf dem iPhone: „Teilen“ → „Zum Home-Bildschirm“ — das Spiel öffnet sich im Vollbild`,"web.safari":`Safari löscht Websitedaten, wenn Sie 7 Tage nicht vorbeischauen. Starten Sie das Spiel vom Home-Bildschirm oder sichern Sie die Welt von Zeit zu Zeit als Datei (Pause → Spielstände → Export).`,"web.safari.short":`Safari löscht Websitedaten nach 7 Tagen ohne Besuch — sichern Sie die Welt als Datei (Spielstände → Export)`,"about.news":`Neuigkeiten`,"about.report.text":`Fehler gefunden oder etwas unklar? Senden Sie einen Bericht — er sammelt alles, was zur Analyse nötig ist.`,"tester.title":`Testerpanel`,"tester.points":`Kontrollpunkte`,"tester.point.start":`Beginn`,"tester.point.tutorial":`Nach dem Tutorial`,"tester.point.lab":`Erstes Forschungszentrum`,"tester.point.ridge":`Pfad: Der Purpurgrat`,"tester.speed":`Weltgeschwindigkeit`,"tester.give":`Ressourcen geben`,"tester.given":`Ressourcen im Inventar`,"tester.fps":`FPS und Bildzeit`,"tester.demo":`Wie in der Demo`,"tester.clear":`Speicher leeren`,"tester.clear.text":`Alle Welten, Einstellungen und Fortschritte dieser Version werden gelöscht, das Spiel startet neu. Die Demo bleibt unberührt.`,"tester.note":`Ein Kontrollpunkt ist eine neue Welt in der Liste; die aktuelle Welt wird gespeichert. Tempo und Ressourcen stören die Wiederholbarkeit der Welt — nur zum Testen.`,"tester.failed":`Kontrollpunkt konnte nicht geladen werden — Details im Bericht`,"tester.point.mid":`Mitte: Spektrum F`,"tester.point.late":`Späte Wiege`,"lab.readingSlow":`Liest Einheit {k}/{n} · noch ≈ {s} s — wenig Licht, {x}× langsamer`,"demo.title":`Ende der Demo`,"demo.lead":`Das Licht der Wiege hat seinen Rhythmus gefunden, und das erste Spektrum F hat das Zentrum erreicht. Von hier an wachsen Geschichte und Fabrik im Vollspiel weiter:`,"demo.next":`Wie es weitergeht`,"demo.f.light":`Polarisation und Phase`,"demo.f.light.desc":`Zwei weitere Eigenschaften des Lichts – neue Linien, Linsen und Maschinen`,"demo.f.sphere":`Die Dyson-Sphäre in voller Größe`,"demo.f.sphere.desc":`Schalen um den Stern, Drohnen, Planeten und Shuttles`,"demo.f.gate":`Das Hypertor und das Finale der Wiege`,"demo.f.gate.desc":`Die Schicksale der Helden, der Schwarm und eine Wahl, die über den Ausgang entscheidet`,"demo.f.path":`Der Weg zu anderen Sternen`,"demo.f.path.desc":`Der Purpurgrat und weitere — nach und nach`,"demo.f.modes":`Neue Welt, Kreativmodus, Experimente`,"demo.f.modes.desc":`Eigene Welteinstellungen, alles freigeschaltet, Aufgaben mit Wertung, „Stern der Woche“`,"demo.keep":`Die Welt bleibt Ihre: Sie können weiterbauen, Ihre Linien verbessern und den Schwarm abwehren.`,"demo.export":`Welt in Datei speichern`,"demo.play":`Weiterspielen`,"demo.transfer":`Die Demo-Welt zieht ins Vollspiel um: Öffnen Sie die Datei dort über „Welten“ → „Welt importieren“.`,"demo.locked":`Im Vollspiel`,"demo.goal":`Die Grenze der Demo ist erreicht – die Kampagne geht im Vollspiel weiter.`,"full.lead.demo":`Dies ist die Demo: der Anfang der Kampagne der Wiege. Das Vollspiel schaltet frei:`,"full.f.campaign":`Die ganze Kampagne der Wiege`,"full.f.campaign.desc":`Polarisation, Phase, Dyson-Sphäre, Planeten und Hypertor`,"crash.sim.title":`Welt angehalten`,"crash.sim.text":`Bei der Berechnung der Welt ist ein Fehler aufgetreten, und wir haben sie angehalten, um Ihre Speicherstände nicht zu beschädigen: Der letzte Speicherstand ist intakt. Senden Sie den Bericht und starten Sie das Spiel neu.`,"hand.keys":`LMT platzieren · {rotate} drehen · RMT weglegen · {pipette} Gleiches aufnehmen`,"settings.fpsCap":`Bildratenlimit`,"settings.fpsCap.off":`Wie Bildschirm`,"settings.fullscreen":`Vollbild (Alt+Enter)`,"settings.autoQuality":`Qualität senken, wenn die Bildrate lange niedrig bleibt`,"settings.bgMute":`Leiser, wenn das Spielfenster nicht aktiv ist`,"settings.uiScale.auto":`Auto ({n} %)`,"remove.farLeft":`Außer Reichweite noch: {n}`,"remove.farLeft.fly":`Näher fliegen`,"about.legal":`Rechtliches`,"about.legal.text":`© {year} Starwarden. Alle Rechte vorbehalten. Das Spiel nutzt Open-Source-Bibliotheken – ihre Lizenzen stehen in einer separaten Datei.`,"about.licenses":`Lizenzen von Drittanbietern`,"creative.speed":`Weltgeschwindigkeit`,"achv.first_waking.name":`Erstes Erwachen`,"achv.first_waking.desc":`Licht erreichte eine Kapsel – jemand aus der Kolonie schlug die Augen auf.`,"achv.first_landing.name":`Auf festem Grund`,"achv.first_landing.desc":`Station und Bohrer auf der Oberfläche eines Planeten.`,"achv.first_split.name":`Die Gabelung`,"achv.first_split.desc":`Der erste Teiler teilt den Strom in zwei.`,"achv.first_mark.name":`Mk II`,"achv.first_mark.desc":`Eine Schleiferei Mk II steht nun über der alten.`,"achv.gate_home.name":`Der Weg nach Hause`,"achv.gate_home.desc":`Das Hypertor der Wiege ist offen – der Sprung ist vollbracht.`,"achv.ark_away.name":`Auf dem Weg`,"achv.ark_away.desc":`Die Arche ist gepackt und unterwegs zum nächsten Stern.`,"achv.ridge_core.name":`Ringkern`,"achv.ridge_core.desc":`Der Kern des Rings des Purpurgrats ist gebaut und sitzt an seinem Platz.`,"achv.ridge_open.name":`Der Ring des Grats`,"achv.ridge_open.desc":`Der Ring des Purpurgrats ist geöffnet.`,"goal.done.path":`Der veröffentlichte Pfad ist durchschritten. Der Weg zum nächsten Stern wird noch gelegt – er öffnet sich in einem Update.`,"inv.search":`Suche: Bau oder Gegenstand (Strg+F)`,"inv.notFound":`Nichts gefunden`};export{e as default};
